/**
 * components/shared/helpRegistry.js: parses + indexes the bundled help corpus.
 *
 * Article content lives in src/docs/manual/**.md (admin) + src/docs/creator/**.md
 * (creator). The prebuild script generate-help-bundle.js writes
 * src/docs/articles.generated.js (imported below).
 *
 * Used by: components/shared/HelpView.js, components/shared/HelpIcon.js.
 *
 * @gotcha articles.generated.js is generated; after editing any .md run
 *         `npm run build:help` (auto-run via prestart/prebuild/pretest:ci) or
 *         the bundle goes stale. @see CLAUDE.md (Help System)
 */
import RAW_ARTICLES from '../../docs/articles.generated';

/**
 * Minimal YAML front-matter parser. Supports:
 *   key: value
 *   key: [a, b, c]
 *   key: "quoted value"
 * No nested objects, no multi-line strings - that's all the help corpus uses.
 */
function parseFrontMatter(raw) {
  const match = /^---\r?\n([\s\S]*?)\r?\n---\r?\n?([\s\S]*)$/.exec(raw);
  if (!match) return { meta: {}, body: raw };
  const block = match[1];
  const body = match[2] || '';
  const meta = {};
  block.split(/\r?\n/).forEach(line => {
    const m = /^([A-Za-z0-9_]+)\s*:\s*(.*)$/.exec(line);
    if (!m) return;
    const key = m[1];
    let val = m[2].trim();
    if (val.startsWith('[') && val.endsWith(']')) {
      val = val.slice(1, -1).split(',').map(s => s.trim().replace(/^["']|["']$/g, '')).filter(Boolean);
    } else {
      val = val.replace(/^["']|["']$/g, '');
    }
    meta[key] = val;
  });
  return { meta, body };
}

function buildArticles() {
  const out = [];
  (RAW_ARTICLES || []).forEach(rec => {
    const { meta, body } = parseFrontMatter(rec.content);
    if (!meta.slug || !meta.title) return;
    const firstPara = (body.replace(/^#+ .*$/gm, '').trim().split(/\r?\n\r?\n/)[0] || '')
      .replace(/[#>*_`[\]]/g, '')
      .trim();
    out.push({
      slug: meta.slug,
      title: meta.title,
      category: meta.category || 'overview',
      audience: meta.audience || rec.audience,
      tags: Array.isArray(meta.tags) ? meta.tags : [],
      related: Array.isArray(meta.related) ? meta.related : [],
      lastReviewed: meta.last_reviewed || '',
      body,
      firstParagraph: firstPara,
    });
  });
  return out;
}

const ALL = buildArticles();

const CATEGORY_ORDER = ['overview', 'daily', 'periodic', 'annual', 'corrections', 'setup', 'troubleshooting'];
const CATEGORY_LABELS = {
  overview: 'Overview',
  daily: 'Daily Operations',
  periodic: 'Periodic Tasks',
  annual: 'Year-End',
  corrections: 'Corrections',
  setup: 'Setup',
  troubleshooting: 'Troubleshooting',
};

export function getCategoryLabel(cat) {
  return CATEGORY_LABELS[cat] || cat;
}

export function allArticles(audience) {
  return ALL.filter(a => a.audience === audience);
}

export function getArticle(slug, audience) {
  return ALL.find(a => a.slug === slug && a.audience === audience) || null;
}

/**
 * Articles for an audience grouped into ordered category sections (known
 * categories in CATEGORY_ORDER first, then any extras), each sorted by title.
 */
export function byCategory(audience) {
  const list = allArticles(audience);
  const groups = {};
  list.forEach(a => {
    const k = a.category || 'overview';
    if (!groups[k]) groups[k] = [];
    groups[k].push(a);
  });
  Object.keys(groups).forEach(k => groups[k].sort((a, b) => a.title.localeCompare(b.title)));
  return CATEGORY_ORDER
    .filter(k => groups[k] && groups[k].length)
    .map(k => ({ key: k, label: getCategoryLabel(k), articles: groups[k] }))
    .concat(
      Object.keys(groups)
        .filter(k => !CATEGORY_ORDER.includes(k))
        .map(k => ({ key: k, label: getCategoryLabel(k), articles: groups[k] }))
    );
}

export function search(query, audience) {
  const q = (query || '').trim().toLowerCase();
  if (!q) return [];
  return allArticles(audience).filter(a => {
    if (a.title.toLowerCase().includes(q)) return true;
    if (a.firstParagraph.toLowerCase().includes(q)) return true;
    if (a.tags.some(t => String(t).toLowerCase().includes(q))) return true;
    return false;
  });
}

/** First sentence of an article's preview, truncated to ~120 chars for the HelpIcon tooltip. */
export function tooltipFor(slug, audience) {
  const a = getArticle(slug, audience);
  if (!a) return '';
  const sentence = (a.firstParagraph.split(/(?<=[.!?])\s/)[0] || a.firstParagraph).trim();
  return sentence.length > 120 ? sentence.slice(0, 119) + '…' : sentence;
}
