/**
 * components/shared/RewardsPage.js: platform reward earnings + creator payouts.
 *
 * The reward-side counterpart to PaymentsPage. A reward entry (platform_reward_entries) records
 * what a creator earned from a platform's rewards program for a month; from it flows the same
 * two-stage model: invoice platform to Patrick (invoices, reward_entry_id set), then payout
 * Patrick to creator (creator_payouts + payout_splits). campaign_id XOR reward_entry_id.
 *
 * Renders components/shared/PayoutForm.js with parent={kind:'reward'} for the payout half.
 * Used by AdminDashboard, and read-only by CreatorDashboard / MobilePostPage.
 *
 * @invariant editable reward-entry and invoice fields mirror the DB lock triggers via
 *            components/shared/InvoiceLock.js. gross_amount has no DB column-lock trigger, so
 *            its lock is enforced UI-only here.
 * @gotcha the payout_splits to payment_destinations embed has TWO FKs; always use
 *         PAYOUT_SPLIT_DESTINATION_EMBED or the query fails silently with PGRST201.
 * @see docs/MONEY.md (rewards, Patterns C to F), docs/CODEBASE.md
 */
import React, { useState, useEffect, useCallback } from 'react';
import { supabase } from '../../lib/supabase';
import { PAYOUT_SPLIT_DESTINATION_EMBED } from '../../utils/queries';
import { BILLED_PAYMENT_VALUES } from '../../utils/statusValues';
import PayoutForm from './PayoutForm';
import SplitBreakdown, { splitLabel } from './SplitBreakdown';
import CreatorFilterChips from './CreatorFilterChips';
import ReceiptUpload from './ReceiptUpload';
import HelpIcon from './HelpIcon';
import { useEscapeKey } from '../../hooks/useEscapeKey';
import { fmtDate, fmtMoney, fmtMonth, extractMonths, isValidNumber, todayYMD } from '../../utils/format';
import { lastMonth, inPeriod, PeriodSelect } from '../../utils/period';
import { useStatusOptions } from '../../contexts/StatusOptionsContext';
import { resolveStatusRow } from '../../utils/statusRow';
import { useCreators } from '../../hooks/useCreators';
import { uploadPaymentReceipt } from '../../utils/receipt';
import { computeProcessingFee, receivedTotal, validateReceiptSums } from '../../utils/invoiceMath';
import { generateAndUploadIssuedInvoice, loadCurrentDoc } from '../../utils/invoiceDocuments';
import ReverseEntryModal from './ReverseEntryModal';
import { useRewardEntryJournalEntries, LockedField, CheckboxLock, PostedBadge, PostedEntries } from './InvoiceLock';
import { humanizeError } from '../../utils/errors';
import { useFormValidation } from '../../hooks/useFormValidation';
import Feedback from './Feedback';
import ReadError from './ReadError';
import EmptyState from './EmptyState';
import { DB_DATE_MIN } from '../../utils/dbLimits';
import { mutate } from '../../utils/mutate';
import { useToast } from './Toast';
import Tabs, { tabPanelProps } from './Tabs';
import { activationProps } from '../../utils/rowActivation';
import Modal from './Modal';
import Field from './Field';
import { useUnsavedGuard } from '../../hooks/useUnsavedGuard';
import Loading from './Loading';
import SubmitButton from './SubmitButton';
import MoneyInput from './MoneyInput';
import { useLoadState } from '../../hooks/useLoadState';
import Refreshing from './Refreshing';


/**
 * The `status_options` row behind a payout, by id and then by value.
 *
 * COLOUR and label both come from it. Three sites here decided the colour with
 * `payout_status === 'Paid' ? green : orange` while taking the label from the vocabulary, so
 * recolouring or renaming a payout status in Admin > Config > Workflow Setup moved the word
 * and never the colour, and N/A was painted the same alert orange as Pending on a money
 * screen. The id-then-value order is the one the split status in this file already uses.
 *
 * @see .claude/rules/hub-data.md (status vocabulary is data, never hardcoded)
 */
const payoutOpt = (payoutOptions, row) =>
  resolveStatusRow({ payout: payoutOptions }, 'payout', {
    statusId: row.payout_status_id, status: row.payout_status,
  });

// ============================================================
// Main page
// ============================================================
/**
 * Reward earnings list (table desktop / cards mobile) with a detail panel.
 *
 * @param {object} props
 * @param {boolean} props.isAdmin - admin: all creators, edit forms, Add Entry, Manage Programs. creator: own rows read-only
 * @param {string} [props.profileId] - restricts rows to one creator (creator view)
 * @param {function} [props.onNavigateToLedger] - jump to a JE in the GL ({source_type, source_id}).
 *        It reaches the reader through the DETAIL PANEL and never through a row: a row here is
 *        `role="button"`, so a second control inside one is `nested-interactive`.
 *        @see utils/rowActivation.js
 * @gotcha reward_payout_summary is anon-blocked + security_invoker; rows RLS-filtered.
 */
export default function RewardsPage({ isAdmin, profileId, onNavigateToLedger, pendingEntryId, onConsumed }) {
  const { options: statusOptions } = useStatusOptions();
  const payoutOptions   = statusOptions.payout || [];
  const splitOptions    = statusOptions.split || [];

  const [entries, setEntries]             = useState([]);
  const [splitsByPayoutId, setSplits]     = useState({});
  const [glInvoiceSet, setGlInvoiceSet]   = useState(() => new Set());

  /**
   * The panel's jump to this entry's journal entry, or null when there is nothing to jump to.
   * Built here because the set of invoices that HAVE a posted entry is a page-level read.
   */
  const ledgerJump = (e) => (
    isAdmin && e?.invoice_id && glInvoiceSet.has(e.invoice_id) && onNavigateToLedger
      ? () => onNavigateToLedger({ source_type: 'invoice', source_id: e.invoice_id })
      : null
  );
  const [programs, setPrograms]           = useState([]);
  const [platforms, setPlatforms]         = useState([]);
  const { creators } = useCreators(isAdmin);
  const { loading, refreshing, begin, end } = useLoadState();
  // Holds the RAW error, not a humanized one: ReadError humanizes, and a second pass over an
  // already-humanized object finds no code and no message and collapses it to the fallback.
  const [loadErr, setLoadErr]             = useState(null);
  const [period, setPeriod]               = useState(lastMonth);
  const [creatorFilter, setCreatorFilter] = useState('all');
  const [programFilter, setProgramFilter] = useState('all');
  const [selected, setSelected]           = useState(null);
  const [showPrograms, setShowPrograms]   = useState(false);
  const [isMobile, setIsMobile]           = useState(() => window.innerWidth <= 768);

  // This page opens on LAST month, so in late August it is showing July, and a quiet July
  // read as a product that has never paid a creator anything. `entries.length` separates
  // that from a genuinely new account.
  const filtersDirty = creatorFilter !== 'all' || programFilter !== 'all' || period !== 'all';
  function clearAllFilters() {
    setCreatorFilter('all'); setProgramFilter('all'); setPeriod('all');
  }

  useEffect(() => {
    const mq = window.matchMedia('(max-width: 768px)');
    const handler = e => setIsMobile(e.matches);
    mq.addEventListener('change', handler);
    return () => mq.removeEventListener('change', handler);
  }, []);

  useEscapeKey(useCallback(() => setSelected(null), []), !!selected);

  useEffect(() => { fetchAll(); }, []);

  // Deep-link target: open a reward entry's panel when a ledger/reconciliation
  // line navigated here. entries holds every period (no period filter on fetch),
  // so the panel opens even if the row is filtered out of the current view.
  useEffect(() => {
    if (!pendingEntryId || entries.length === 0) return;
    const target = entries.find((e) => e.entry_id === pendingEntryId);
    if (target) setSelected(target);
    if (onConsumed) onConsumed();
  }, [pendingEntryId, entries]);

  async function fetchAll() {
    begin();
    setLoadErr(null);
    if (isAdmin) {
      const [sumRes, progRes, plRes, glRes] = await Promise.all([
        supabase.from('reward_payout_summary').select('*').order('period_month', { ascending: false }),
        supabase.from('platform_rewards_programs').select('*, platform:platforms(name)').eq('is_active', true),
        supabase.from('platforms').select('*').eq('is_active', true),
        supabase.from('ledger_journal_entries').select('source_id').eq('source_type', 'invoice').is('reversed_by_je_id', null),
      ]);
      const readErr = sumRes.error || progRes.error || plRes.error || glRes.error;
      if (readErr) { setLoadErr(readErr); setEntries([]); end(); return; }
      const all = sumRes.data || [];
      setEntries(all);
      setPrograms(progRes.data || []);
      setPlatforms(plRes.data || []);
      setGlInvoiceSet(new Set((glRes?.data || []).map(r => r.source_id).filter(Boolean)));
      await loadSplits(all);
    } else {
      const [sumRes, progRes] = await Promise.all([
        supabase.from('reward_payout_summary').select('*').eq('profile_id', profileId).order('period_month', { ascending: false }),
        supabase.from('platform_rewards_programs').select('*, platform:platforms(name)').eq('is_active', true),
      ]);
      const readErr = sumRes.error || progRes.error;
      if (readErr) { setLoadErr(readErr); setEntries([]); end(); return; }
      const all = sumRes.data || [];
      setEntries(all);
      setPrograms(progRes.data || []);
      await loadSplits(all);
    }
    end();
  }

  async function loadSplits(all) {
    const payoutIds = all.map(e => e.payout_id).filter(Boolean);
    if (payoutIds.length === 0) { setSplits({}); return; }
    const { data: splits, error: splitsErr } = await supabase
      .from('payout_splits')
      .select(`*, ${PAYOUT_SPLIT_DESTINATION_EMBED}(name, account_type, account_last4, institution, memo), expense:expenses(id, name, type, frequency, amount)`)
      .in('payout_id', payoutIds);
    if (splitsErr) { setLoadErr(splitsErr); end(); return; }
    const map = {};
    (splits || []).forEach(s => {
      if (!map[s.payout_id]) map[s.payout_id] = [];
      map[s.payout_id].push(s);
    });
    setSplits(map);
  }

  const months = extractMonths(entries, 'period_month');

  const filtered = entries.filter(e => {
    if (isAdmin && creatorFilter !== 'all' && e.profile_id !== creatorFilter) return false;
    if (programFilter !== 'all' && e.program_id !== programFilter) return false;
    if (!inPeriod(e.period_month, period)) return false;
    return true;
  });

  // Stats
  const totalGross    = filtered.reduce((s, e) => s + (e.gross_amount || 0), 0);
  const totalReceived = receivedTotal(filtered);
  const totalPaidOut  = filtered.filter(e => e.payout_status === 'Paid').reduce((s, e) => s + (e.payout_amount || 0), 0);
  const totalPending  = filtered.filter(e => e.payout_status !== 'Paid').reduce((s, e) => s + (e.gross_amount || 0), 0);
  const totalFees     = filtered.reduce((s, e) => s + (e.processing_fee || 0), 0);

  if (loading) return <div className="page"><Loading /></div>;
  // Error before Empty: an empty rewards list reads as "no rewards were earned".
  if (loadErr) return <div className="page"><ReadError error={loadErr} onRetry={fetchAll} /></div>;

  if (isMobile) return (
    <div className="page">
      <div style={{ marginBottom: 16 }}>
        <h1 className="page-title">{isAdmin ? 'REWARDS' : 'MY REWARDS'}</h1>
        {isAdmin ? (
          <div style={{ display: 'flex', gap: 8, marginTop: 10 }}>
            <button className="btn btn-secondary btn-sm" onClick={() => setShowPrograms(true)}>Manage Programs</button>
            <button className="btn btn-primary btn-sm" onClick={() => setSelected({ _new: true })}>+ Add Entry</button>
          </div>
        ) : (
          <div style={{ marginTop: 10 }}>
            <PeriodSelect period={period} onChange={setPeriod} months={months} />
          </div>
        )}
      </div>

      {isAdmin ? (
        <div className="stats-row" style={{ gridTemplateColumns: 'repeat(3, 1fr)', gap: 8, marginBottom: 16 }}>
          <div className="stat-card"><div className="stat-value" style={{ fontSize: 18 }}>{fmtMoney(totalGross)}</div><div className="stat-label">Gross</div></div>
          <div className="stat-card"><div className="stat-value stat-green" style={{ fontSize: 18 }}>{fmtMoney(totalReceived)}</div><div className="stat-label">Received</div></div>
          <div className="stat-card"><div className="stat-value stat-accent" style={{ fontSize: 18 }}>{fmtMoney(totalPaidOut)}</div><div className="stat-label">Paid Out</div></div>
          <div className="stat-card"><div className="stat-value stat-orange" style={{ fontSize: 18 }}>{fmtMoney(totalPending)}</div><div className="stat-label">Pending</div></div>
          <div className="stat-card"><div className="stat-value" style={{ fontSize: 18, color: totalFees > 0 ? 'var(--red)' : 'var(--muted)' }}>{fmtMoney(totalFees)}</div><div className="stat-label">Fees</div></div>
        </div>
      ) : (
        <div className="stats-row" style={{ gridTemplateColumns: 'repeat(2, 1fr)', gap: 8, marginBottom: 16 }}>
          <div className="stat-card"><div className="stat-value" style={{ fontSize: 18 }}>{fmtMoney(totalGross)}</div><div className="stat-label">Total Earned</div></div>
          <div className="stat-card"><div className="stat-value stat-accent" style={{ fontSize: 18 }}>{fmtMoney(totalPaidOut)}</div><div className="stat-label">Paid to Me</div></div>
          <div className="stat-card"><div className="stat-value stat-orange" style={{ fontSize: 18 }}>{fmtMoney(totalPending)}</div><div className="stat-label">Pending</div></div>
          <div className="stat-card"><div className="stat-value" style={{ fontSize: 18, color: totalFees > 0 ? 'var(--red)' : 'var(--muted)' }}>{fmtMoney(totalFees)}</div><div className="stat-label">Fees</div></div>
        </div>
      )}

      {isAdmin ? (
        <div style={{ marginBottom: 16 }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 10, flexWrap: 'wrap' }}>
            <span className="text-muted text-xs">CREATOR</span>
            <CreatorFilterChips value={creatorFilter} onChange={setCreatorFilter} creators={creators} />
          </div>
          <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 10, flexWrap: 'wrap' }}>
            <span className="text-muted text-xs">PROGRAM</span>
            <button className={`filter-chip ${programFilter === 'all' ? 'active' : ''}`} aria-pressed={programFilter === 'all'} onClick={() => setProgramFilter('all')}>All</button>
            {programs.map(p => (
              <button key={p.id} className={`filter-chip ${programFilter === p.id ? 'active' : ''}`} aria-pressed={programFilter === p.id} onClick={() => setProgramFilter(p.id)}>{p.name}</button>
            ))}
          </div>
          <PeriodSelect period={period} onChange={setPeriod} months={months} />
        </div>
      ) : (
        <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 16, flexWrap: 'wrap' }}>
          <span className="text-muted text-xs">PROGRAM</span>
          <button className={`filter-chip ${programFilter === 'all' ? 'active' : ''}`} aria-pressed={programFilter === 'all'} onClick={() => setProgramFilter('all')}>All</button>
          {programs.map(p => (
            <button key={p.id} className={`filter-chip ${programFilter === p.id ? 'active' : ''}`} aria-pressed={programFilter === p.id} onClick={() => setProgramFilter(p.id)}>{p.name}</button>
          ))}
        </div>
      )}

      {filtered.length === 0 ? (
        <EmptyState icon="★"
          title="No rewards yet"
          text={isAdmin ? 'Tap + Add Entry to get started.' : 'Platform rewards earnings will appear here once recorded by your manager.'}
          filtered={{ unfiltered: entries, dirty: filtersDirty, onClear: clearAllFilters,
            title: 'No rewards match these filters',
            text: `${entries.length} ${entries.length === 1 ? 'entry is' : 'entries are'} hidden by the filters above.` }} />
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
          {filtered.map(e => {
            const splits = splitsByPayoutId[e.payout_id] || [];
            const periodLabel = e.period_month ? fmtDate(e.period_month, 'MMM yyyy') : '—';
            const creatorName = e.creator_name || e.creator_full_name || '—';
            return (
              <div key={e.entry_id} className={`card${selected?.entry_id === e.entry_id ? ' is-selected' : ''}`} style={{ cursor: 'pointer', padding: '14px 16px' }} {...activationProps(() => setSelected(e), { pressed: selected?.entry_id === e.entry_id })}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 6 }}>
                  <div style={{ minWidth: 0, flex: 1, marginRight: 12 }}>
                    <div title={e.program_name} style={{ fontFamily: 'var(--font-display)', fontSize: 16, letterSpacing: 0.5, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{e.program_name}</div>
                    <div style={{ fontSize: 12, color: 'var(--muted)', marginTop: 2 }}>{e.platform_name || '—'}</div>
                  </div>
                  <div style={{ fontWeight: 700, fontSize: 18, color: 'var(--blue)', flexShrink: 0 }}>{fmtMoney(e.gross_amount)}</div>
                </div>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <div style={{ fontSize: 12, color: 'var(--muted)' }}>
                    {isAdmin && <span style={{ marginRight: 8, fontWeight: 500, color: 'var(--white)' }}>{creatorName}</span>}
                    <span>{periodLabel}</span>
                  </div>
                  <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                    {e.processing_fee > 0 && <span style={{ fontSize: 11, color: 'var(--red)', fontWeight: 600 }}>-{fmtMoney(e.processing_fee)}</span>}
                    <span style={{ fontSize: 11, fontWeight: 600, textTransform: 'uppercase', letterSpacing: 0.5, color: payoutOpt(payoutOptions, e)?.text_color || 'var(--muted)' }}>{payoutOpt(payoutOptions, e)?.label || e.payout_status || 'Pending'}</span>
                  </div>
                </div>
                {e.payout_amount != null && (
                  <div style={{ marginTop: 6, fontSize: 12, color: 'var(--muted)' }}>
                    Payout <span style={{ color: 'var(--blue)', fontWeight: 600 }}>{fmtMoney(e.payout_amount)}</span>
                    {splits.length > 1 && <span> · {splits.length} splits</span>}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}

      {selected && isAdmin && (
        <AdminRewardDetailPanel
          entry={selected}
          programs={programs}
          creators={creators}
          isMobile={true}
          onClose={() => setSelected(null)}
          onUpdated={() => { fetchAll(); setSelected(null); }}
          onUpdatedKeepOpen={() => fetchAll()}
          onGoToLedger={ledgerJump(selected)}
        />
      )}

      {selected && !isAdmin && (
        <CreatorRewardDetailPanel
          entry={selected}
          isMobile={true}
          onClose={() => setSelected(null)}
        />
      )}

      {showPrograms && isAdmin && (
        <ProgramsModal platforms={platforms} onClose={() => { setShowPrograms(false); fetchAll(); }} />
      )}
    </div>
  );

  return (
    <div className="page">
      <div className="page-header">
        <div>
          <h1 className="page-title">
            {isAdmin ? 'REWARDS' : 'MY REWARDS'}
            {isAdmin && <HelpIcon slug="platform-reward" />}
          </h1>
          <div className="page-subtitle">Platform creator rewards program earnings<Refreshing on={refreshing} /></div>
        </div>
        {isAdmin ? (
          <div className="flex gap-8" style={{ alignItems: 'center' }}>
            <button className="btn btn-secondary btn-sm" onClick={() => setShowPrograms(true)}>Manage Programs</button>
            <HelpIcon slug="manage-rewards-programs" />
            <button className="btn btn-primary" onClick={() => setSelected({ _new: true })}>+ Add Entry</button>
            <HelpIcon slug="platform-reward" />
          </div>
        ) : (
          <PeriodSelect period={period} onChange={setPeriod} months={months} />
        )}
      </div>

      {/* Tiles */}
      {isAdmin ? (
        <div className="stats-row" style={{ gridTemplateColumns: 'repeat(5,1fr)' }}>
          <div className="stat-card"><div className="stat-value" style={{ fontSize: 22 }}>{fmtMoney(totalGross)}</div><div className="stat-label">Gross Earned<HelpIcon slug="platform-reward" /></div></div>
          <div className="stat-card"><div className="stat-value stat-green" style={{ fontSize: 22 }}>{fmtMoney(totalReceived)}</div><div className="stat-label">You Received<HelpIcon slug="invoice-receive" /></div></div>
          <div className="stat-card"><div className="stat-value stat-accent" style={{ fontSize: 22 }}>{fmtMoney(totalPaidOut)}</div><div className="stat-label">Paid to Creators<HelpIcon slug="payout" /></div></div>
          <div className="stat-card"><div className="stat-value stat-orange" style={{ fontSize: 22 }}>{fmtMoney(totalPending)}</div><div className="stat-label">Pending Payout<HelpIcon slug="payout" /></div></div>
          <div className="stat-card"><div className="stat-value" style={{ fontSize: 22, color: totalFees > 0 ? 'var(--red)' : 'var(--muted)' }}>{fmtMoney(totalFees)}</div><div className="stat-label">Fees Paid<HelpIcon slug="invoice-receive" /></div></div>
        </div>
      ) : (
        <div className="stats-row" style={{ gridTemplateColumns: 'repeat(4, 1fr)' }}>
          <div className="stat-card"><div className="stat-value" style={{ fontSize: 22 }}>{fmtMoney(totalGross)}</div><div className="stat-label">Total Earned</div></div>
          <div className="stat-card"><div className="stat-value stat-accent" style={{ fontSize: 22 }}>{fmtMoney(totalPaidOut)}</div><div className="stat-label">Paid to Me</div></div>
          <div className="stat-card"><div className="stat-value stat-orange" style={{ fontSize: 22 }}>{fmtMoney(totalPending)}</div><div className="stat-label">Pending Payout</div></div>
          <div className="stat-card"><div className="stat-value" style={{ fontSize: 22, color: totalFees > 0 ? 'var(--red)' : 'var(--muted)' }}>{fmtMoney(totalFees)}</div><div className="stat-label">Fees Paid</div></div>
        </div>
      )}

      {/* Filters */}
      <div className="filters-row" style={{ flexWrap: 'wrap' }}>
        {isAdmin && (
          <>
            <span className="text-muted text-xs">CREATOR</span>
            <CreatorFilterChips value={creatorFilter} onChange={setCreatorFilter} creators={creators} />
            <div style={{ width: 1, height: 16, background: 'var(--border)', margin: '0 6px' }} />
            <span className="text-muted text-xs">PROGRAM</span>
            <button className={`filter-chip ${programFilter === 'all' ? 'active' : ''}`} aria-pressed={programFilter === 'all'} onClick={() => setProgramFilter('all')}>All</button>
            {programs.map(p => (
              <button key={p.id} className={`filter-chip ${programFilter === p.id ? 'active' : ''}`} aria-pressed={programFilter === p.id} onClick={() => setProgramFilter(p.id)}>
                {p.name}
              </button>
            ))}
            <PeriodSelect period={period} onChange={setPeriod} months={months} style={{ marginLeft: 8 }} />
          </>
        )}
        {!isAdmin && (
          <>
            <span className="text-muted text-xs">PROGRAM</span>
            <button className={`filter-chip ${programFilter === 'all' ? 'active' : ''}`} aria-pressed={programFilter === 'all'} onClick={() => setProgramFilter('all')}>All</button>
            {programs.map(p => (
              <button key={p.id} className={`filter-chip ${programFilter === p.id ? 'active' : ''}`} aria-pressed={programFilter === p.id} onClick={() => setProgramFilter(p.id)}>
                {p.name}
              </button>
            ))}
          </>
        )}
      </div>

      {/* Table */}
      {filtered.length === 0 ? (
        <EmptyState icon="★"
          title="No rewards yet"
          text={isAdmin ? 'Click + Add Entry to get started.' : 'Platform rewards earnings will appear here once recorded by your manager.'}
          filtered={{ unfiltered: entries, dirty: filtersDirty, onClear: clearAllFilters,
            title: 'No rewards match these filters',
            text: `${entries.length} ${entries.length === 1 ? 'entry is' : 'entries are'} hidden by the filters above.` }} />
      ) : (
        <div className="table-wrap">
          <table>
            <thead>
              <tr>
                {isAdmin && <th scope="col">Creator</th>}
                <th scope="col">Platform</th>
                <th scope="col">Program</th>
                <th scope="col">Period</th>
                <th scope="col">Gross</th>
                <th scope="col">Fees</th>
                <th scope="col">Destination</th>
                <th scope="col">Amount</th>
                <th scope="col">Status</th>
                <th scope="col">Sent</th>
                <th scope="col">Cleared</th>
              </tr>
            </thead>
            <tbody>
              {filtered.map(e => {
                const splits = splitsByPayoutId[e.payout_id] || [];
                const periodLabel = e.period_month ? fmtDate(e.period_month, 'MMM yyyy') : '—';
                const creatorName = e.creator_name || e.creator_full_name || '—';
                const grossCell = <td style={{ fontWeight: 600 }}>{fmtMoney(e.gross_amount)}</td>;
                const feesCell = <td>{e.processing_fee > 0 ? <span style={{ color: 'var(--red)', fontWeight: 600, fontSize: 12 }}>{fmtMoney(e.processing_fee)}</span> : <span className="text-muted">—</span>}</td>;

                if (splits.length === 0) {
                  return (
                    <tr key={e.entry_id} className={selected?.entry_id === e.entry_id ? 'is-selected' : ''} {...activationProps(() => setSelected(e), { pressed: selected?.entry_id === e.entry_id })} style={{ cursor: 'pointer' }}>
                      {isAdmin && <td style={{ fontWeight: 500 }}>{creatorName}</td>}
                      <td>{e.platform_name || '—'}</td>
                      <td>
                        {e.program_name}
                      </td>
                      <td style={{ fontWeight: 500 }}>{periodLabel}</td>
                      {grossCell}
                      {feesCell}
                      <td className="text-muted text-xs">—</td>
                      <td>{e.payout_amount != null ? <span style={{ color: 'var(--blue)', fontWeight: 700 }}>{fmtMoney(e.payout_amount)}</span> : <span className="text-muted">—</span>}</td>
                      <td><span style={{ fontSize: 11, fontWeight: 600, color: payoutOpt(payoutOptions, e)?.text_color || 'var(--muted)', textTransform: 'uppercase', letterSpacing: 0.5 }}>{payoutOpt(payoutOptions, e)?.label || e.payout_status || 'Pending'}</span></td>
                      <td className="text-muted">—</td>
                      <td className="text-muted">—</td>
                    </tr>
                  );
                }

                return splits.map((s, i) => {
                  const splitOpt = splitOptions.find(o => o.id === s.split_status_id) || splitOptions.find(o => o.value === s.split_status);
                  const statusColor = splitOpt?.text_color || 'var(--muted)';
                  const { title: destName, subline: destSubline } = splitLabel(s);

                  return (
                    <tr key={`${e.entry_id}-${s.id}`} className={selected?.entry_id === e.entry_id ? 'is-selected' : ''} {...activationProps(() => setSelected(e), { pressed: selected?.entry_id === e.entry_id })} style={{ cursor: 'pointer' }}>
                      {i === 0 ? (
                        <>
                          {isAdmin && <td rowSpan={splits.length} style={{ verticalAlign: 'top', paddingTop: 14, fontWeight: 500 }}>{creatorName}</td>}
                          <td rowSpan={splits.length} style={{ verticalAlign: 'top', paddingTop: 14 }}>{e.platform_name || '—'}</td>
                          <td rowSpan={splits.length} style={{ verticalAlign: 'top', paddingTop: 14 }}>
                            {e.program_name}
                          </td>
                          <td rowSpan={splits.length} style={{ verticalAlign: 'top', paddingTop: 14, fontWeight: 500 }}>{periodLabel}</td>
                          <td rowSpan={splits.length} style={{ verticalAlign: 'top', paddingTop: 14, fontWeight: 600 }}>{fmtMoney(e.gross_amount)}</td>
                          <td rowSpan={splits.length} style={{ verticalAlign: 'top', paddingTop: 14 }}>{e.processing_fee > 0 ? <span style={{ color: 'var(--red)', fontWeight: 600, fontSize: 12 }}>{fmtMoney(e.processing_fee)}</span> : <span className="text-muted">—</span>}</td>
                        </>
                      ) : null}
                      <td>
                        <div style={{ fontWeight: 500, fontSize: 12 }}>{destName}</div>
                        <div className="text-muted" style={{ fontSize: 10 }}>{destSubline}</div>
                      </td>
                      <td style={{ color: 'var(--blue)', fontWeight: 700 }}>{fmtMoney(s.amount)}</td>
                      <td><span style={{ fontSize: 11, fontWeight: 600, color: statusColor, textTransform: 'uppercase', letterSpacing: 0.5 }}>{splitOpt?.label || s.split_status}</span></td>
                      <td style={{ fontSize: 12 }}>{s.sent_date ? fmtDate(s.sent_date) : <span className="text-muted">—</span>}</td>
                      <td style={{ fontSize: 12, color: s.cleared_date ? 'var(--green)' : 'var(--muted)' }}>
                        {s.cleared_date ? `✓ ${fmtDate(s.cleared_date)}` : '—'}
                      </td>
                    </tr>
                  );
                });
              })}
            </tbody>
          </table>
        </div>
      )}

      {selected && isAdmin && (
        <AdminRewardDetailPanel
          entry={selected}
          programs={programs}
          creators={creators}
          onClose={() => setSelected(null)}
          onUpdated={() => { fetchAll(); setSelected(null); }}
          onUpdatedKeepOpen={() => fetchAll()}
          onGoToLedger={ledgerJump(selected)}
        />
      )}

      {selected && !isAdmin && (
        <CreatorRewardDetailPanel
          entry={selected}
          onClose={() => setSelected(null)}
        />
      )}

      {showPrograms && isAdmin && (
        <ProgramsModal platforms={platforms} onClose={() => { setShowPrograms(false); fetchAll(); }} />
      )}
    </div>
  );
}

// ============================================================
// Admin Detail Panel - full edit with tabs
// ============================================================
/**
 * Admin panel for one reward entry: Entry / Invoice / Payout tabs (Entry only
 * when creating a new entry). Slide-in desktop, bottom-sheet mobile.
 *
 * @param {object} props.entry - the reward_payout_summary row, or {_new:true} to create
 * @param {function} props.onUpdated - save-and-close (refetch list + close panel)
 * @param {function} props.onUpdatedKeepOpen - save without closing (refetch list, keep editing)
 */
function AdminRewardDetailPanel({ entry, programs, creators, isMobile = false, onClose, onUpdated, onUpdatedKeepOpen, onGoToLedger }) {
  const { dirtyProps } = useUnsavedGuard();
  const isNew = entry?._new;
  const [tab, setTab] = useState('entry');
  const [entryData, setEntryData] = useState(null);
  const [initialLoading, setInitialLoading] = useState(!isNew);
  const [detailErr, setDetailErr] = useState(null);
  const [panelVisible, setPanelVisible] = useState(false);

  useEffect(() => {
    if (!isNew) fetchDetail(true);
  }, [entry?.entry_id]);

  useEffect(() => {
    if (isMobile) requestAnimationFrame(() => setPanelVisible(true));
  }, [isMobile]);

  function handleClose() {
    if (isMobile) { setPanelVisible(false); setTimeout(onClose, 280); }
    else onClose();
  }

  async function fetchDetail(initial = false) {
    if (initial) setInitialLoading(true);
    // The reward's own money row. A refused read left the panel showing the
    // stale `entry` prop as if it were current.
    const { data, error } = await supabase.from('reward_payout_summary').select('*').eq('entry_id', entry.entry_id).single();
    if (error) { setDetailErr(humanizeError(error)); if (initial) setInitialLoading(false); return; }
    setDetailErr(null);
    setEntryData(data);
    if (initial) setInitialLoading(false);
  }

  const data = isNew ? null : (entryData || entry);

  const panelInner = (
    <>
      <div className="detail-header">
        <div className="flex items-center justify-between mb-8">
          <span className="text-muted text-xs">{isNew ? 'New Entry' : data?.platform_name}</span>
          <button className="btn btn-ghost btn-icon btn-sm" onClick={handleClose} aria-label="Close reward entry">✕</button>
        </div>
        {!isNew && (
          <>
            <h2 className="detail-panel-title">{data?.program_name}</h2>
            <div className="text-muted mt-4">{data?.creator_name || data?.creator_full_name}</div>
            <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 10, marginTop: 8 }}>
              <div style={{ color: 'var(--blue)', fontWeight: 700, fontSize: 18 }}>{fmtMoney(data?.gross_amount)}</div>
              {onGoToLedger && (
                <button type="button" className="detail-ledger-link" onClick={onGoToLedger}>
                  View in General Ledger
                </button>
              )}
            </div>
          </>
        )}
      </div>

      <Tabs
        label="Reward entry"
        panelId="reward-detail-panel"
        style={{ padding: '0 24px' }}
        value={tab}
        onChange={setTab}
        items={(isNew ? ['entry'] : ['entry', 'invoice', 'payout']).map(t => ({
          id: t,
          label: t === 'entry' ? 'Entry' : t === 'invoice' ? (isMobile ? 'Invoice' : 'Invoice (Platform → You)') : (isMobile ? 'Payout' : 'Payout (You → Creator)'),
        }))}
      />

      <div className="detail-body" style={isMobile ? { overflowY: 'auto', flex: 1 } : {}} {...tabPanelProps('reward-detail-panel', tab)}>
        {initialLoading ? <Loading /> : detailErr ? <Feedback value={detailErr} /> : (
          <>
            {tab === 'entry' && (
              <EntryForm
                entry={isNew ? null : data}
                programs={programs}
                creators={creators}
                onSaved={() => {
                  if (isNew) onUpdated();
                  else { onUpdatedKeepOpen(); fetchDetail(); }
                }}
              />
            )}
            {tab === 'invoice' && !isNew && (
              <RewardInvoiceForm entry={data} onUpdated={() => { onUpdatedKeepOpen(); fetchDetail(); }} />
            )}
            {tab === 'payout' && !isNew && (
              <PayoutForm
                /* Reward-side config for the shared PayoutForm (campaign side
                   passes kind:'campaign'). PayoutForm self-loads its own
                   payout/splits/destinations from parentId.
                   @see components/shared/PayoutForm.js */
                parent={{
                  kind: 'reward',
                  parentId: data.entry_id,
                  creatorId: data.profile_id,
                  creatorName: data.creator_name,
                  youReceived: data.you_received,
                  isInKind: false,
                  payoutAmountDefault: data.amount_received ?? data.gross_amount ?? '',
                  // The month the PLATFORM's cash landed, which is the month payroll settles it
                  // in. @see components/shared/PayoutForm.js
                  cashMonth: (data.payment_received_date || '').slice(0, 7) || null,
                }}
                onUpdated={() => { onUpdatedKeepOpen(); fetchDetail(); }}
              />
            )}
          </>
        )}
      </div>
    </>
  );

  if (isMobile) {
    return (
      <>
        <div aria-hidden="true" onClick={handleClose} style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.6)', zIndex: 200, animation: 'fadeIn 0.2s ease' }} />
        <div style={{
          position: 'fixed', bottom: 0, left: 0, right: 0, height: '92dvh',
          background: 'var(--surface)', borderRadius: '16px 16px 0 0',
          zIndex: 201, display: 'flex', flexDirection: 'column', overflow: 'hidden',
          transform: panelVisible ? 'translateY(0)' : 'translateY(100%)',
          transition: 'transform 0.28s cubic-bezier(0.4,0,0.2,1)',
        }}>
          <div style={{ display: 'flex', justifyContent: 'center', padding: '12px 0 4px', flexShrink: 0 }}>
            <div style={{ width: 36, height: 4, background: 'var(--border2)', borderRadius: 2 }} />
          </div>
          {panelInner}
        </div>
      </>
    );
  }
  return <div className="detail-panel" {...dirtyProps}>{panelInner}</div>;
}

