// ============================================================
// Entry form - create or edit (admin only)
// ============================================================
/**
 * Create / edit a reward entry (program, creator, month, gross amount).
 *
 * @gotcha gross_amount is baked into the Pattern D cash-receipt JE (CR 411x).
 *         There is no DB column-lock trigger for it, so once that JE exists this
 *         form gates the field UI-only (grossLocked) via useRewardEntryJournalEntries.
 *         The payload omits gross_amount entirely while locked so a stray value
 *         can't desync the books. @see components/shared/InvoiceLock.js
 */
function EntryForm({ entry, programs, creators, onSaved }) {
  const toast = useToast();
  const [form, setForm] = useState({
    program_id: entry?.program_id || '',
    profile_id: entry?.profile_id || '',
    period_month: entry?.period_month ? entry.period_month.slice(0, 7) : '',
    gross_amount: entry?.gross_amount ?? '',
    notes: entry?.notes || '',
  });
  const [saving, setSaving] = useState(false);
  const [formError, setFormError] = useState('');
  // gross_amount is baked into the Pattern D cash-receipt JE (CR 411x). If
  // that JE exists, mutating gross_amount silently desyncs the books - the
  // DB has no trigger for this column, so we gate at the UI layer using the
  // shared invoice-lock hook.
  const { cashJe, error: jeError, refetch: refetchJes } = useRewardEntryJournalEntries(entry?.entry_id);
  const [reverseFor, setReverseFor] = useState(null);
  // A refused probe is not permission to edit. cashJe is null both when nothing is posted and
  // when the read did not answer, and this is the ONLY guard on gross_amount: there is no
  // column-lock trigger behind it, so an unlocked field here rewrites a figure that is already
  // baked into a posted Pattern D entry.
  const grossLocked = !!cashJe || !!jeError;

  async function save() {
    setFormError('');
    if (!form.program_id || !form.profile_id || !form.period_month) { setFormError('Program, creator, and period are required.'); return; }
    if (form.gross_amount !== '' && !isValidNumber(form.gross_amount)) { setFormError('Gross amount must be a number.'); return; }
    setSaving(true);
    const payload = {
      program_id: form.program_id,
      profile_id: form.profile_id,
      period_month: form.period_month + '-01',
      notes: form.notes || null,
    };
    if (!grossLocked) {
      payload.gross_amount = form.gross_amount !== '' ? parseFloat(form.gross_amount) : null;
    }
    if (entry?.entry_id) {
      const { error: e } = await supabase.from('platform_reward_entries').update(payload).eq('id', entry.entry_id);
      if (e) { setFormError(humanizeError(e)); setSaving(false); return; }
    } else {
      payload.gross_amount = form.gross_amount !== '' ? parseFloat(form.gross_amount) : null;
      const { error: e } = await supabase.from('platform_reward_entries').insert(payload);
      if (e) { setFormError(humanizeError(e)); setSaving(false); return; }
    }
    setSaving(false);
    toast.success(entry?.entry_id ? 'Reward entry saved' : 'Reward entry added');
    onSaved();
  }

  if (jeError) return <ReadError error={jeError} onRetry={refetchJes} />;

  return (
    <div>
      <h3 className="detail-section-title">REWARD ENTRY<PostedBadge visible={grossLocked} /></h3>
      <div className="form-row">
        <Field label="Program">{(id) => (<>
          <select id={id} className="form-select" value={form.program_id} onChange={e => setForm(f => ({ ...f, program_id: e.target.value }))}>
            <option value="">Select…</option>
            {programs.map(p => <option key={p.id} value={p.id}>{p.platform?.name}: {p.name}</option>)}
          </select>
        </>)}</Field>
        <Field label="Creator">{(id) => (<>
          <select id={id} className="form-select" value={form.profile_id} onChange={e => setForm(f => ({ ...f, profile_id: e.target.value }))}>
            <option value="">Select…</option>
            {creators.map(c => <option key={c.id} value={c.id}>{c.creator_name || c.full_name}</option>)}
          </select>
        </>)}</Field>
      </div>
      <div className="form-row">
        <Field label="Period (Month)">{(id) => (<>
          <input id={id} className="form-input" type="month" value={form.period_month} onChange={e => setForm(f => ({ ...f, period_month: e.target.value }))} />
        </>)}</Field>
        <Field label={<>Gross Amount ($)<PostedBadge visible={grossLocked} /></>}>{(id) => (<>
          <LockedField je={cashJe} onReverse={setReverseFor} tooltip="Locked. Reverse the cash-receipt entry to edit gross amount.">
            <MoneyInput id={id} value={form.gross_amount} disabled={grossLocked} onChange={e => setForm(f => ({ ...f, gross_amount: e.target.value }))} placeholder="0.00" style={grossLocked ? { paddingRight: 38 } : undefined} />
          </LockedField>
        </>)}</Field>
      </div>
      <Field label="Notes">{(id) => (<>
        <textarea id={id} className="form-textarea" value={form.notes} maxLength={2000} onChange={e => setForm(f => ({ ...f, notes: e.target.value }))} style={{ minHeight: 52 }} />
      </>)}</Field>
      {formError && <Feedback value={formError} style={{ marginBottom: 12 }} />}
      <SubmitButton saving={saving} className="btn btn-primary w-full mt-12" onClick={save} disabled={saving} style={{ justifyContent: 'center' }}>{entry?.entry_id ? 'Update Entry' : 'Create Entry'}</SubmitButton>

      <PostedEntries jes={cashJe ? [cashJe] : []} title="Posted ledger entry for this reward" onReverse={(je) => setReverseFor(je)} />

      {reverseFor ? (
        <ReverseEntryModal
          journalEntry={reverseFor.entry}
          lines={reverseFor.lines}
          onClose={() => setReverseFor(null)}
          onReversed={() => { setReverseFor(null); refetchJes(); onSaved(); }}
        />
      ) : null}
    </div>
  );
}

// ============================================================
// Reward Invoice Form - platform paying Patrick (admin only)
// ============================================================
/**
 * Admin editor for the platform -> Patrick reward invoice. The amount is fixed
 * to the entry's gross (read-only here); user enters net received + discount and
 * the processing fee is derived. On save it re-posts Pattern D (cash received)
 * idempotently and auto-generates the issued PDF when billed.
 *
 * @gotcha invoice_amount is forced to entry.gross_amount; never invoice a
 *         zero/blank gross. Auto-fills invoice_date (last day of period month) and
 *         paid date (program payout_day of the following month), the latter only once that
 *         day has arrived: see the prefill below.
 * @gotcha receipt math mirrors the campaign side: gross = net_received +
 *         processing_fee + discount_amount. @see utils/invoiceMath.js
 * @invariant cash-receipt fields seal once the JE posts (LockedField / CheckboxLock).
 *            @see components/shared/InvoiceLock.js
 */
function RewardInvoiceForm({ entry, onUpdated }) {
  const toast = useToast();
  const { options: statusOptions } = useStatusOptions();
  const agencyOptions = (statusOptions.payment || []).filter(o => o.value !== 'In Kind');
  const today = todayYMD();
  const v = useFormValidation({
    invoice_date:          { date: true, dateBetween: [DB_DATE_MIN, today], message: 'Invoice date cannot be in the future.' },
    payment_received_date: { date: true, dateBetween: [DB_DATE_MIN, today], message: 'Payment received date cannot be in the future.' },
    you_received_date:     { date: true, dateBetween: [DB_DATE_MIN, today], message: 'Cash received date cannot be in the future.' },
    net_received:          { number: true, min: 0, message: 'Net received must be zero or more.' },
    discount_amount:       { number: true, min: 0, message: 'Discount must be zero or more.' },
  });
  const [invoice, setInvoice] = useState(undefined);
  const [paymentMethods, setPaymentMethods] = useState([]);
  // The picker's own state, beside the form rather than in place of it. Same rule and same
  // sentence as the campaign invoice form.
  const [methodsError, setMethodsError] = useState(null);
  const [form, setForm] = useState(null);
  const [saving, setSaving] = useState(false);
  const [saveError, setSaveError] = useState('');
  const [generatingPdf, setGeneratingPdf] = useState(false);
  const [issuedDoc, setIssuedDoc]   = useState(null);
  // Held apart from `issuedDoc`, because null means two things and only one of them may
  // offer to regenerate. @see utils/invoiceDocuments.js loadCurrentDoc
  const [issuedDocError, setIssuedDocError] = useState(null);
  const [genRetrying, setGenRetrying] = useState(false);
  const [genError, setGenError]     = useState('');
  const [receiptPath, setReceiptPath] = useState(null);
  const [receiptName, setReceiptName] = useState(null);
  // The receipt's twin of `issuedDocError`, and for the same reason. Raw; ReadError humanizes.
  const [receiptError, setReceiptError] = useState(null);
  const [uploading, setUploading] = useState(false);
  const [uploadError, setUploadError] = useState('');
  const { invoiceJes, cashJe, error: jeError, refetch: refetchJes } = useRewardEntryJournalEntries(entry?.entry_id);
  const [reverseFor, setReverseFor] = useState(null);
  // The third state for this form's own reads. `invoice` null is what "not invoiced yet" looks
  // like, and Save then takes the INSERT branch: `invoices` has no unique constraint on
  // reward_entry_id, so a refused read buys the entry a second invoice row.
  const [loadError, setLoadError] = useState(null);

  function getAutoFillDates() {
    let invoiceDate = '';
    if (entry?.period_month) {
      const [y, mo] = entry.period_month.slice(0, 7).split('-').map(Number);
      const lastDay = new Date(y, mo, 0);
      invoiceDate = `${y}-${String(mo).padStart(2, '0')}-${String(lastDay.getDate()).padStart(2, '0')}`;
    }
    let paidDate = '';
    if (entry?.period_month && entry?.payout_day) {
      const [y, mo] = entry.period_month.slice(0, 7).split('-').map(Number);
      const nextMonth = mo === 12 ? 1 : mo + 1;
      const nextYear = mo === 12 ? y + 1 : y;
      const day = String(Math.min(entry.payout_day, 28)).padStart(2, '0');
      paidDate = `${nextYear}-${String(nextMonth).padStart(2, '0')}-${day}`;
    }
    return { invoiceDate, paidDate };
  }

  useEffect(() => { loadAll(); }, [entry?.entry_id]);

  async function loadAll() {
    setLoadError(null);
    const [invRes, pmRes] = await Promise.all([
      supabase.from('invoices').select('*').eq('reward_entry_id', entry.entry_id).maybeSingle(),
      supabase.from('payment_methods').select('*').eq('is_active', true).order('sort_order').order('name'),
    ]);
    if (invRes.error) { setLoadError(invRes.error); return; }
    const inv = invRes.data;
    setInvoice(inv);
    setMethodsError(pmRes.error || null);
    setPaymentMethods(pmRes.data || []);
    if (inv?.id) {
      // `{ doc }` alone made a refused read look like "no receipt on file", which is what the
      // sibling issued_invoice read one hundred lines down already refuses to do.
      // @see utils/invoiceDocuments.js loadCurrentDoc
      const { doc, error: docErr } = await loadCurrentDoc(inv.id, 'payment_receipt');
      setReceiptPath(doc?.file_path || null);
      setReceiptName(doc?.file_name || null);
      setReceiptError(docErr || null);
    } else {
      setReceiptPath(null);
      setReceiptName(null);
      setReceiptError(null);
    }
    const { invoiceDate, paidDate } = getAutoFillDates();
    setForm({
      invoice_date: inv?.invoice_date || invoiceDate,
      payment_status_id: inv?.payment_status_id || agencyOptions.find(o => o.value === 'Not Invoiced')?.id || '',
      // Only once the payout day has arrived. It is in the FUTURE for the first half of every
      // month and this field refuses one, so prefilling it opens the form on a value its own
      // Save rejects. The hint below still names the scheduled day; that is what it is for.
      payment_received_date: inv?.payment_received_date || (paidDate && paidDate <= today ? paidDate : ''),
      payment_method: inv?.payment_method || '',
      payment_notes: inv?.payment_notes || '',
      you_received: inv?.you_received ?? false,
      you_received_date: inv?.you_received_date || '',
      net_received: inv?.amount_received != null ? String(inv.amount_received) : '',
      discount_amount: inv?.discount_amount != null && inv.discount_amount !== 0 ? String(inv.discount_amount) : '',
      you_received_notes: inv?.you_received_notes || '',
    });
    // useRewardEntryJournalEntries keeps cashJe in sync.
  }

  async function save() {
    if (!form) return;
    setSaveError('');
    if (!v.validate(form)) {
      setSaveError({ tone: 'error', title: 'Fix the highlighted fields and try again.' });
      return;
    }
    // @invariant these three dates run in sequence, and nothing below the browser knows it:
    //            `chk_invoices_dates` bounds each column on its own, and `useFormValidation`
    //            declares one window per field with no way to relate two. Must run AFTER
    //            v.validate, which REPLACES the errors object. Same shape and same sentences
    //            as the campaign invoice form.
    const dateErrors = {};
    if (form.invoice_date && form.payment_received_date && form.payment_received_date < form.invoice_date) {
      dateErrors.payment_received_date = 'Paid date cannot be before the invoice date.';
    }
    // Mirrors chk_invoices_received_needs_date, and this form needs it more than the campaign
    // one does: it writes the invoice row straight to the table rather than through
    // save_invoice_with_postings, so trg_invoice_update_ledger posts the cash entry with no
    // RPC in the path to guard it. `!cashJe` because Date Cleared is disabled once that entry
    // is posted, and a save must never be refused over a field the person cannot type into.
    if (form.you_received && !cashJe && !form.you_received_date) {
      dateErrors.you_received_date = 'Enter the date the money cleared your account.';
    }
    if (form.you_received && form.payment_received_date && form.you_received_date
        && form.you_received_date < form.payment_received_date) {
      dateErrors.you_received_date = 'Date cleared cannot be before the paid date.';
    }
    if (Object.keys(dateErrors).length) {
      v.setErrors(e => ({ ...e, ...dateErrors }));
      setSaveError({ tone: 'error', title: 'Fix the highlighted fields and try again.' });
      return;
    }
    // The reward invoice's amount is the entry's gross. Never invoice a zero/blank value.
    if (!(parseFloat(entry?.gross_amount) > 0)) {
      setSaveError({ tone: 'error', title: 'Set a gross amount first', body: 'This reward has no gross amount. Enter a gross amount greater than zero on the reward entry before invoicing.' });
      return;
    }
    const sumErr = validateReceiptSums(entry?.gross_amount, form.net_received, form.discount_amount);
    if (sumErr) { setSaveError(sumErr.replace('invoice amount', 'gross amount')); return; }
    setSaving(true);
    const discountVal = form.discount_amount !== '' ? parseFloat(parseFloat(form.discount_amount).toFixed(2)) : 0;
    const payload = {
      invoice_date: form.invoice_date || null,
      invoice_amount: entry?.gross_amount ?? null,
      payment_status_id: form.payment_status_id || null,
      payment_received_date: form.payment_received_date || null,
      payment_method: form.payment_method || null,
      payment_notes: form.payment_notes || null,
      you_received: form.you_received,
      you_received_date: form.you_received_date || null,
      amount_received: form.net_received !== '' ? parseFloat(parseFloat(form.net_received).toFixed(2)) : null,
      discount_amount: discountVal,
      processing_fee: computeProcessingFee(entry?.gross_amount, form.net_received, discountVal),
      you_received_notes: form.you_received_notes || null,
      reward_entry_id: entry.entry_id,
      campaign_id: null,
    };
    let savedInvoice = invoice;
    if (invoice) {
      const { error: e } = await supabase.from('invoices').update(payload).eq('id', invoice.id);
      if (e) { setSaveError(humanizeError(e)); setSaving(false); return; }
    } else {
      const { data: newInv, error: e } = await supabase.from('invoices').insert(payload).select().single();
      if (e) { setSaveError(humanizeError(e)); setSaving(false); return; }
      savedInvoice = newInv;
    }
    setInvoice(savedInvoice);

    // Idempotent re-post of Pattern D (Cash received - reward). Covers the
    // reverse-then-edit flow where you_received was already true so the
    // existing trigger condition wouldn't refire. Internal NOT EXISTS guard
    // makes this a no-op when a live JE exists.
    if (savedInvoice?.id && payload.you_received) {
      const { error: rpcErr } = await supabase.rpc('create_invoice_received_entry', { p_invoice_id: savedInvoice.id });
      // The raw message plus a prefix in the product's own developer vocabulary, on a screen
      // whose reader is not one. Its sibling eleven lines above already humanizes.
      if (rpcErr) { setSaveError(humanizeError(rpcErr)); setSaving(false); return; }
    }

    // Auto-generate the issued_invoice PDF when the saved status is in
    // the billed set. Skip if a current document already exists.
    if (savedInvoice?.id && payload.payment_status_id) {
      const newStatus = agencyOptions.find(o => o.id === payload.payment_status_id);
      if (newStatus && BILLED_PAYMENT_VALUES.includes(newStatus.value)) {
        try {
          setGeneratingPdf(true);
          // A refused probe is not "no PDF yet": generating over it supersedes the version
          // already sent. Leave it to the form's own read, which reports it.
          const { doc: existing, error: probeErr } = await loadCurrentDoc(savedInvoice.id, 'issued_invoice');
          if (probeErr) throw probeErr;
          if (existing) { setIssuedDoc(existing); setIssuedDocError(null); }
          else {
            await generateAndUploadIssuedInvoice(savedInvoice.id);
            // The CONFIRMING re-read, and both halves of its result are load bearing. A
            // refused confirm is not evidence the generate failed, so it may not fall through
            // to `issuedDoc: null` with no reason beside it: that is the state the "Issued PDF
            // missing" banner reads, and generating again supersedes the version already sent.
            const { doc: made, error: confirmErr } = await loadCurrentDoc(savedInvoice.id, 'issued_invoice');
            setIssuedDoc(made || null);
            setIssuedDocError(confirmErr || null);
          }
        } catch (e) {
          if (process.env.NODE_ENV !== 'production') console.error('[RewardInvoiceForm] auto PDF gen', e);
        } finally {
          setGeneratingPdf(false);
        }
      }
    }

    setSaving(false);
    toast.success('Reward invoice saved');
    onUpdated();
  }

  // Refresh issuedDoc when the invoice loads.
  useEffect(() => {
    let alive = true;
    if (invoice?.id) {
      loadCurrentDoc(invoice.id, 'issued_invoice').then(({ doc, error }) => {
        if (!alive) return;
        setIssuedDoc(doc);
        setIssuedDocError(error || null);
      });
    } else {
      setIssuedDoc(null);
      setIssuedDocError(null);
    }
    return () => { alive = false; };
  }, [invoice?.id]);

  async function handleGenRetry() {
    if (!invoice?.id) return;
    setGenRetrying(true);
    setGenError('');
    try {
      await generateAndUploadIssuedInvoice(invoice.id);
      const { doc, error: docErr } = await loadCurrentDoc(invoice.id, 'issued_invoice');
      setIssuedDoc(doc);
      setIssuedDocError(docErr || null);
    } catch (e) {
      setGenError(e?.message || String(e));
    }
    setGenRetrying(false);
  }

  const paymentValue = invoice
    ? agencyOptions.find(o => o.id === invoice.payment_status_id)?.value
    : null;
  const showRetryBanner = !!invoice && BILLED_PAYMENT_VALUES.includes(paymentValue) && !issuedDoc && !issuedDocError;

  async function uploadReceipt(file) {
    let invId = invoice?.id;
    if (!invId) {
      const { data: newInv, error: newInvErr } = await supabase.from('invoices').insert({
        reward_entry_id: entry.entry_id,
        payment_status_id: form?.payment_status_id || null,
        campaign_id: null,
      }).select().single();
      // Same shape as PaymentsPage: a write whose result is read, so a failed
      // insert dropped the receipt upload with nothing shown.
      if (newInvErr) { setUploadError(humanizeError(newInvErr)?.body || 'Could not create the invoice.'); return; }
      invId = newInv?.id;
      setInvoice(newInv);
    }
    if (!invId) return;
    await uploadPaymentReceipt({ file, invoiceId: invId, setUploading, onSuccess: (path, name) => { setReceiptPath(path); setReceiptName(name); }, onError: (msg) => setUploadError(msg) });
  }

  if (loadError) return <ReadError error={loadError} onRetry={loadAll} />;
  if (jeError) return <ReadError error={jeError} onRetry={refetchJes} />;
  if (invoice === undefined || !form) return <Loading />;

  const { paidDate } = getAutoFillDates();
  const expectedPayoutDate = paidDate
    ? new Date(paidDate + 'T12:00:00').toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })
    : null;

  return (
    <div>
      {expectedPayoutDate && (
        <div style={{ padding: '8px 12px', borderRadius: 6, marginBottom: 16, fontSize: 12, background: 'rgba(255,255,255,0.04)', border: '1px solid var(--border)', color: 'var(--muted)' }}>
          Expected platform payout: <strong style={{ color: 'var(--white)' }}>{expectedPayoutDate}</strong>
        </div>
      )}
      {/* Generate is withheld while the reason stands: it inserts a superseding v2 and the
          trigger demotes the version already issued. */}
      {issuedDocError ? (
        <div style={{ marginBottom: 16 }}><ReadError error={issuedDocError} onRetry={loadAll} /></div>
      ) : null}
      {showRetryBanner ? (
        <div style={{ padding: '10px 14px', marginBottom: 16, background: 'var(--orange-glow)', borderLeft: '3px solid var(--orange)', borderRadius: 4, display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: 12, flexWrap: 'wrap' }}>
          <div style={{ fontSize: 12 }}>
            <strong>Issued PDF missing.</strong> The platform-facing invoice PDF was not generated when this invoice was last saved.
            {genError ? <div role="alert" style={{ color: 'var(--red)', marginTop: 4 }}>{genError}</div> : null}
          </div>
          <button className="btn btn-secondary btn-sm" onClick={handleGenRetry} disabled={genRetrying}>
            {genRetrying ? 'Generating…' : 'Generate PDF'}
          </button>
        </div>
      ) : null}
      <h3 className="detail-section-title">PLATFORM PAYMENT TO YOU</h3>
      <div className="form-row">
        <Field label="Invoice #">{(id) => (<>
          <input id={id} className="form-input" value={invoice?.invoice_number || ''} placeholder="Assigned automatically when saved" readOnly />
        </>)}</Field>
        <Field label="Invoice Date">{(id) => (<>
          <input id={id} className="form-input" type="date" min={DB_DATE_MIN} max={today} value={form.invoice_date} {...v.fieldProps('invoice_date')} onChange={e => { setForm(f => ({ ...f, invoice_date: e.target.value })); v.clear('invoice_date'); }} />
          {v.errors.invoice_date && <div {...v.errorProps('invoice_date')}>{v.errors.invoice_date}</div>}
        </>)}</Field>
      </div>
      <div className="form-row">
        <div className="form-group">
          <div className="form-label">Amount ($)</div>
          <div className="form-input" style={{ background: 'var(--surface)', color: 'var(--muted)', cursor: 'default' }}>{entry?.gross_amount != null ? fmtMoney(entry.gross_amount) : '—'}</div>
        </div>
        <Field label="Status">{(id) => (<>
          <select id={id} className="form-select" value={form.payment_status_id} onChange={e => setForm(f => ({ ...f, payment_status_id: e.target.value }))}>
            {agencyOptions.map(o => <option key={o.id} value={o.id}>{o.label}</option>)}
          </select>
        </>)}</Field>
      </div>
      <div className="form-row">
        <Field label="Paid Date">{(id) => (<>
          <input id={id} className="form-input" type="date" min={form.invoice_date || DB_DATE_MIN} max={today} value={form.payment_received_date} {...v.fieldProps('payment_received_date')} onChange={e => { setForm(f => ({ ...f, payment_received_date: e.target.value })); v.clear('payment_received_date'); }} />
          {v.errors.payment_received_date && <div {...v.errorProps('payment_received_date')}>{v.errors.payment_received_date}</div>}
        </>)}</Field>
        <Field label="Payment Method">{(id) => (<>
          {methodsError ? <ReadError error={methodsError} onRetry={loadAll} /> : (
            <select id={id} className="form-select" value={form.payment_method} onChange={e => setForm(f => ({ ...f, payment_method: e.target.value }))}>
              <option value="">Select…</option>
              {paymentMethods.map(m => <option key={m.id} value={m.name}>{m.name}</option>)}
            </select>
          )}
        </>)}</Field>
      </div>
      <Field label="Notes">{(id) => (<>
        <textarea id={id} className="form-textarea" value={form.payment_notes} maxLength={1000} onChange={e => setForm(f => ({ ...f, payment_notes: e.target.value }))} style={{ minHeight: 44 }} />
      </>)}</Field>

      <div className="divider" />
      <h3 className="detail-section-title">
        RECEIVED BY YOU
        <PostedBadge visible={!!cashJe} />
      </h3>
      <div className="form-group">
        <label className="checkbox-row">
          <input type="checkbox" checked={form.you_received} disabled={!!cashJe} onChange={e => setForm(f => ({ ...f, you_received: e.target.checked }))} />
          Money has cleared my account
          <CheckboxLock je={cashJe} onReverse={setReverseFor} tooltip="Locked. Reverse the cash-receipt entry to edit." />
        </label>
      </div>
      {form.you_received && (
        <>
          <div className="form-row">
            <Field label="Date Cleared">{(id) => (<>
              <LockedField je={cashJe} onReverse={setReverseFor} tooltip="Locked. Reverse the cash-receipt entry to edit.">
                <input id={id} className="form-input" type="date" min={form.payment_received_date || DB_DATE_MIN} max={today} value={form.you_received_date} disabled={!!cashJe} {...v.fieldProps('you_received_date')} onChange={e => { setForm(f => ({ ...f, you_received_date: e.target.value })); v.clear('you_received_date'); }} style={cashJe ? { paddingRight: 38 } : undefined} />
              </LockedField>
              {v.errors.you_received_date && <div {...v.errorProps('you_received_date')}>{v.errors.you_received_date}</div>}
            </>)}</Field>
            <Field label="Net Received ($)">{(id) => (<>
              <LockedField je={cashJe} onReverse={setReverseFor} tooltip="Locked. Reverse the cash-receipt entry to edit.">
                <MoneyInput id={id} value={form.net_received} disabled={!!cashJe} {...v.fieldProps('net_received')} onChange={e => { setForm(f => ({ ...f, net_received: e.target.value })); v.clear('net_received'); }} placeholder={entry?.gross_amount != null ? String(entry.gross_amount) : '0.00'} style={cashJe ? { paddingRight: 38 } : undefined} />
              </LockedField>
              {v.errors.net_received && <div {...v.errorProps('net_received')}>{v.errors.net_received}</div>}
            </>)}</Field>
          </div>
          <div className="form-row">
            <Field label="Discount / Write-off ($)">{(id) => (<>
              <LockedField je={cashJe} onReverse={setReverseFor} tooltip="Locked. Reverse the cash-receipt entry to edit.">
                <MoneyInput id={id} value={form.discount_amount} disabled={!!cashJe} {...v.fieldProps('discount_amount')} onChange={e => { setForm(f => ({ ...f, discount_amount: e.target.value })); v.clear('discount_amount'); }} placeholder="0.00" style={cashJe ? { paddingRight: 38 } : undefined} />
              </LockedField>
              {v.errors.discount_amount && <div {...v.errorProps('discount_amount')}>{v.errors.discount_amount}</div>}
            </>)}</Field>
            <div className="form-group">
              <div className="form-label">Processing Fee (calculated)</div>
              <div className="form-input" style={{ background: 'var(--surface)', color: 'var(--muted)', cursor: 'default' }}>
                {entry?.gross_amount != null && form.net_received !== ''
                  ? fmtMoney(computeProcessingFee(entry.gross_amount, form.net_received, form.discount_amount))
                  : '—'}
              </div>
            </div>
          </div>
        </>
      )}

      <Feedback value={saveError} style={{ marginTop: 12, marginBottom: 0 }} />
      <SubmitButton
        saving={saving || generatingPdf}
        savingLabel={generatingPdf ? 'Saving + generating PDF…' : 'Saving…'}
        className="btn btn-primary w-full mt-12"
        onClick={save}
        style={{ justifyContent: 'center' }}
      >Save Invoice</SubmitButton>

      <PostedEntries jes={invoiceJes} title="Posted ledger entries for this invoice" onReverse={(je) => setReverseFor(je)} />

      {reverseFor ? (
        <ReverseEntryModal
          journalEntry={reverseFor.entry}
          lines={reverseFor.lines}
          onClose={() => setReverseFor(null)}
          onReversed={() => { setReverseFor(null); refetchJes(); loadAll(); onUpdated(); }}
        />
      ) : null}

      {/* The same block as the campaign invoice form, which is why it is a component: this
          copy of it had lost the download button. */}
      <ReceiptUpload
        invoiceId={invoice?.id}
        path={receiptPath}
        name={receiptName}
        uploading={uploading}
        error={uploadError}
        readError={receiptError}
        onRetryRead={loadAll}
        onSelect={uploadReceipt}
        onError={setUploadError}
        onRemoved={() => { setReceiptPath(null); setReceiptName(null); }}
      />
    </div>
  );
}

// ============================================================
// Programs Modal - manage reward programs (admin only)
// ============================================================
// The reward payout form is not a component here. Both pages render the shared
// components/shared/PayoutForm.js (parent={kind:'reward'}).
/** Admin modal to create / edit / enable / disable platform_rewards_programs. */
function ProgramsModal({ platforms, onClose }) {
  const toast = useToast();
  const [programs, setPrograms] = useState([]);
  const [programsErr, setProgramsErr] = useState(null);
  const { loading: progLoading, refreshing: progRefreshing, begin: progBegin, end: progEnd } = useLoadState();
  const [editing, setEditing] = useState(null);
  const [form, setForm] = useState({ name: '', platform_id: '', description: '', payout_day: 15 });
  const [saving, setSaving] = useState(false);

  useEffect(() => { load(); }, []);

  async function load() {
    progBegin();
    const { data, error } = await supabase.from('platform_rewards_programs').select('*, platform:platforms(name)').order('created_at');
    if (error) { setProgramsErr(humanizeError(error)); progEnd(); return; }
    setProgramsErr(null);
    setPrograms(data || []);
    progEnd();
  }

  function startEdit(p) {
    setEditing(p?.id || 'new');
    setForm(p ? { name: p.name, platform_id: p.platform_id || '', description: p.description || '', payout_day: p.payout_day || 15 } : { name: '', platform_id: '', description: '', payout_day: 15 });
  }

  async function save() {
    if (!form.name.trim()) return;
    setSaving(true);
    const payload = { name: form.name.trim(), platform_id: form.platform_id || null, description: form.description || null, payout_day: parseInt(form.payout_day) || 15 };
    if (editing === 'new') await supabase.from('platform_rewards_programs').insert(payload);
    else await supabase.from('platform_rewards_programs').update(payload).eq('id', editing);
    setSaving(false);
    setEditing(null);
    load();
  }

  async function toggleActive(p) {
    const { error } = await mutate(supabase.from('platform_rewards_programs').update({ is_active: !p.is_active }).eq('id', p.id));
    if (error) { toast.error(error); return; }
    load();
  }

  return (
    <Modal
      title="REWARD PROGRAMS"
      titleStyle={{ fontSize: 20 }}
      size="md"
      onClose={onClose}
    >
        <div className="modal-body">
          <Refreshing on={progRefreshing} />
          {progLoading ? <Loading /> : programsErr ? <Feedback value={programsErr} /> : (
            <>
              <div className="table-wrap" style={{ marginBottom: 16 }}>
                <table className="pinned-actions">
                  <thead><tr><th scope="col">Program</th><th scope="col">Platform</th><th scope="col">Payout Day</th><th scope="col">Active</th><th scope="col"></th></tr></thead>
                  <tbody>
                    {programs.map(p => (
                      <tr key={p.id}>
                        <td style={{ fontWeight: 500 }}>{p.name}</td>
                        <td>{p.platform?.name || '—'}</td>
                        <td style={{ color: 'var(--muted)' }}>15th of following month</td>
                        <td><span style={{ color: p.is_active ? 'var(--green)' : 'var(--muted)', fontSize: 12 }}>{p.is_active ? 'Active' : 'Inactive'}</span></td>
                        <td>
                          <div className="flex gap-6">
                            <button className="btn btn-ghost btn-sm" onClick={() => startEdit(p)}>Edit</button>
                            <button className="btn btn-ghost btn-sm" style={{ color: p.is_active ? 'var(--red)' : 'var(--green)' }} onClick={() => toggleActive(p)}>{p.is_active ? 'Disable' : 'Enable'}</button>
                          </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>

              {editing ? (
                <div>
                  <div style={{ fontSize: 11, fontWeight: 600, textTransform: 'uppercase', letterSpacing: 1, color: 'var(--dim)', marginBottom: 12 }}>
                    {editing === 'new' ? 'New Program' : 'Edit Program'}
                  </div>
                  <div className="form-row">
                    <Field label="Name">{(id) => (<>
                      <input id={id} className="form-input" value={form.name} onChange={e => setForm(f => ({ ...f, name: e.target.value }))} placeholder="Creator Rewards" />
                    </>)}</Field>
                    <Field label="Platform">{(id) => (<>
                      <select id={id} className="form-select" value={form.platform_id} onChange={e => setForm(f => ({ ...f, platform_id: e.target.value }))}>
                        <option value="">Select…</option>
                        {platforms.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
                      </select>
                    </>)}</Field>
                  </div>
                  <div className="form-row">
                    <Field label="Payout Day (of following month)">{(id) => (<>
                      <input id={id} className="form-input" type="number" min="1" max="28" value={form.payout_day} onChange={e => setForm(f => ({ ...f, payout_day: e.target.value }))} />
                    </>)}</Field>
                    <Field label="Description">{(id) => (<>
                      <input id={id} className="form-input" value={form.description} onChange={e => setForm(f => ({ ...f, description: e.target.value }))} />
                    </>)}</Field>
                  </div>
                  <div className="flex gap-8">
                    <SubmitButton saving={saving} className="btn btn-primary btn-sm" onClick={save} disabled={saving}>Save</SubmitButton>
                    <button className="btn btn-ghost btn-sm" onClick={() => setEditing(null)}>Cancel</button>
                  </div>
                </div>
              ) : (
                <button className="btn btn-secondary btn-sm" onClick={() => startEdit(null)}>+ Add Program</button>
              )}
            </>
          )}
        </div>
    </Modal>
  );
}
