/**
 * hooks/useSplitForms.js - payout-split form state with auto-balancing to 100%.
 *
 * Editing any non-last split's percentage or amount recomputes the LAST split
 * so the rows always total both 100% AND the payout amount exactly.
 *
 * Used by: components/shared/PayoutForm.js (campaign + reward payouts).
 *
 * @invariant the last split absorbs BOTH remainders: the leftover percentage
 *            and the leftover cent. Deriving its amount from its own percentage
 *            lets a half cent round the wrong way and puts the splits a penny
 *            off the payout: a 50/50 of $485.05 becomes $242.53 twice, $485.06
 *            in total. A split seals once cleared, so that penny cannot be
 *            corrected in place afterwards.
 * @see CLAUDE.md "Payout split auto-adjust", docs/MONEY.md
 */
import { useState } from 'react';
import { round2 } from '../utils/format';

/**
 * Recompute the last row so the set totals 100% and the payout amount exactly.
 *
 * Exported for tests: the cent-level correctness here is the whole point, and a
 * hook is an awkward place to assert it.
 *
 * @param {object[]} rows - split-form rows; the LAST one absorbs the remainder.
 * @param {number|string} payoutAmt - the payout total the rows must sum to.
 * @returns {object[]} rows with the last one rebalanced.
 *
 * @gotcha the last amount is the payout MINUS the others, never its own
 *         percentage of the payout. Those differ by a cent whenever a share
 *         lands on a half-cent.
 */
export function balanceLastSplit(rows, payoutAmt) {
  if (!rows || rows.length < 2) return rows;
  const head = rows.slice(0, -1);
  const last = rows[rows.length - 1];

  const otherPct = head.reduce((a, x) => a + (parseFloat(x.percentage) || 0), 0);
  const lastPct = (100 - otherPct).toFixed(4);

  let lastAmt = '';
  if (payoutAmt && lastPct !== '') {
    const otherAmt = head.reduce((a, x) => a + (parseFloat(x.amount_override) || 0), 0);
    lastAmt = round2(parseFloat(payoutAmt) - otherAmt).toFixed(2);
  }

  return [...head, { ...last, percentage: lastPct, amount_override: lastAmt }];
}

/**
 * @param {object[]} initialForms - initial split-form rows.
 * @returns {{splitForms, setSplitForms, setSF, totalPct, onPctChange, onAmtChange}}
 *          setSF(i, key, value) patches one field; onPctChange/onAmtChange take
 *          the current payout amount at CALL time (not closed over) so the
 *          derived amounts reflect live form state.
 */
export function useSplitForms(initialForms) {
  const [splitForms, setSplitForms] = useState(initialForms);
  const totalPct = splitForms.reduce((s, f) => s + (parseFloat(f.percentage) || 0), 0);

  function setSF(i, k, v) {
    setSplitForms(sf => sf.map((s, idx) => idx === i ? { ...s, [k]: v } : s));
  }

  // Auto-adjusts the last split so splits always total 100% and the payout.
  // payoutAmt is passed at call time so it reflects current form state.
  function onPctChange(i, pct, payoutAmt) {
    const amt = payoutAmt && pct !== '' ? (payoutAmt * parseFloat(pct) / 100).toFixed(2) : '';
    setSplitForms(sf => {
      const u = sf.map((s, idx) => idx === i ? { ...s, percentage: pct, amount_override: amt } : s);
      return (u.length > 1 && i !== u.length - 1) ? balanceLastSplit(u, payoutAmt) : u;
    });
  }

  function onAmtChange(i, amt, payoutAmt) {
    const pct = payoutAmt && amt !== '' ? ((parseFloat(amt) / payoutAmt) * 100).toFixed(4) : '';
    setSplitForms(sf => {
      const u = sf.map((s, idx) => idx === i ? { ...s, amount_override: amt, percentage: pct } : s);
      return (u.length > 1 && i !== u.length - 1) ? balanceLastSplit(u, payoutAmt) : u;
    });
  }

  return { splitForms, setSplitForms, setSF, totalPct, onPctChange, onAmtChange };
}
