const InvoicePreviewModal = lazy(() => import('./InvoicePreviewModal'));

// Getter maps for sort - defined outside component to avoid re-creation on each render
const CASH_GETTERS_STATIC = {
  campaign:   r => campaignLabelParts(r).label,
  creator:    r => (r.creator_name || r.creator_full_name || '').toLowerCase(),
  contracted: r => r.contracted_rate || 0,
  agency:     r => r.agency_payment_status || '',
  received:   r => r.you_received_date || '',
  cashin:     r => r.amount_received ?? r.invoice_amount ?? 0,
  fee:        r => r.processing_fee || 0,
  payout:     r => r.payout_status || '',
  payoutamt:  r => r.payout_amount || 0,
  splits:     r => r.splits_cleared || 0,
  invoice_date: r => r.invoice_date || '',
};
const INK_GETTERS_STATIC = {
  campaign:      r => campaignLabelParts(r).label,
  creator:       r => (r.creator_name || r.creator_full_name || '').toLowerCase(),
  agency:        r => r.agency_name || '',
  fairvalue:     r => r.invoice_amount ?? r.contracted_rate ?? 0,
  agencystatus:  r => r.agency_payment_status || '',
};

/**
 * One row of All / Paid / Not paid chips.
 *
 * @param {string} props.name - what this row filters, for the accessible name ONLY. Both rows
 *        print the same three words, so without it a reader hears them twice and the visible
 *        caption beside them was the only thing that said which was which. The visible label
 *        stays inside the spoken one, which is what voice control matches. @see utils/paidFilter.js
 */
function PaidFilterChips({ value, onChange, name }) {
  return PAID_FILTER_CHOICES.map(c => (
    <button key={c.value} className={`filter-chip ${value === c.value ? 'active' : ''}`} aria-pressed={value === c.value}
      aria-label={`${c.label} ${name}`} onClick={() => onChange(c.value)}>{c.label}</button>
  ));
}

// ── Main exported component ───────────────────────────────────────────────────
/**
 * Campaign payments list (cash + in-kind tables) with a slide-in detail panel.
 *
 * @param {object} props
 * @param {boolean} props.isAdmin - admin sees all creators + edit forms; creator sees own rows read-only
 * @param {string} [props.creatorProfileId] - restricts rows to one creator (creator view)
 * @param {function} [props.onNavigateToLedger] - jump to a JE in the GL ({source_type, source_id}).
 *        It reaches the reader through the DETAIL PANEL and never through a row: a row here is
 *        `role="button"`, so a second control inside one is `nested-interactive` and a screen
 *        reader announces neither. @see utils/rowActivation.js
 * @param {string} [props.pendingCampaignId] - deep-link target: auto-opens this campaign's panel once rows load
 * @param {function} [props.onConsumed] - called after the deep-link is honored so a refresh can't reopen it
 * @gotcha campaign_payout_summary is anon-blocked + security_invoker; rows are RLS-filtered.
 *         Cancelled campaigns are excluded (action-less, would show confusing $payout vs N/A status).
 */
export default function PaymentsPage({ isAdmin, creatorProfileId, onNavigateToLedger, pendingCampaignId, onConsumed }) {
  const [rows, setRows]         = useState([]);
  const [glInvoiceSet, setGlInvoiceSet] = useState(() => new Set());

  /**
   * The panel's jump to this row's journal entry, or null when there is nothing to jump to.
   *
   * Built here rather than in the panel because the set of invoices that HAVE a posted entry
   * is a page-level read; the panel only needs to know whether to draw the control.
   */
  const ledgerJump = (r) => (
    isAdmin && r?.invoice_id && glInvoiceSet.has(r.invoice_id) && onNavigateToLedger
      ? () => onNavigateToLedger({ source_type: 'invoice', source_id: r.invoice_id })
      : null
  );
  // Two flags, not one: a refetch after a save keeps the table, the totals and the open
  // detail panel on screen and says it is re-reading. @see hooks/useLoadState.js
  const { loading, refreshing, begin, end } = useLoadState();
  // The third state. Without it a refused read renders "No payments to show. Payments will
  // appear here once campaigns are set up." to a creator who is owed money, and the GL set
  // beside it empties, which drops the ledger deep-link from every posted invoice so the row
  // reads as one with nothing in the books.
  const [loadError, setLoadError] = useState(null);
  const { creators } = useCreators(isAdmin);
  // The open row's ID, never a snapshot of the row: `selected` below re-reads it. @see P30
  const [selectedId, setSelectedId]  = useState(null);

  const [creatorFilter, setCreatorFilter] = useState('all');
  const [agencyFilter,  setAgencyFilter]  = useState('');
  const [statusFilter,  setStatusFilter]  = useState(PAID_FILTER_ALL);
  const [payoutFilter,  setPayoutFilter]  = useState(PAID_FILTER_ALL);
  // Opens on ALL TIME, not on the current month. Every figure above the table is a standing
  // balance rather than a monthly one: Awaiting Payout is money owed until it is sent, whatever
  // month it was earned in, so a month window silently drops the overdue rows that are the
  // reason to open this page at all. @see utils/period.js
  const [period,        setPeriod]        = useState('all');

  const cashSort = useSortState('invoice_date', 'desc');
  const inkSort  = useSortState('campaign');
  const [isMobile, setIsMobile] = useState(() => window.innerWidth <= 768);

  useEscapeKey(useCallback(() => setSelectedId(null), []), !!selectedId);

  useEffect(() => { fetchAll(); }, []);
  // Deep-link from the campaign Invoice tab: open this campaign's detail panel
  // once rows are loaded, then clear the pending id so a later refresh doesn't
  // reopen it. Search unfiltered rows so the period filter can't hide the target.
  useEffect(() => {
    if (!pendingCampaignId || rows.length === 0) return;
    const target = rows.find(r => r.campaign_id === pendingCampaignId);
    if (target) setSelectedId(target.campaign_id);
    if (onConsumed) onConsumed();
  }, [pendingCampaignId, rows]);
  useEffect(() => {
    const mq = window.matchMedia('(max-width: 768px)');
    const handler = e => setIsMobile(e.matches);
    mq.addEventListener('change', handler);
    return () => mq.removeEventListener('change', handler);
  }, []);

  async function fetchAll() {
    begin();
    setLoadError(null);
    // Cancelled campaigns are hidden from Payments - they're action-less
    // (nothing to invoice, receive, or pay out) and produce confusing rows
    // like a $400 payout_amount sitting next to a payout_status='N/A'.
    // Same rule the agency-dashboard edge function applies.
    //
    // Read to exhaustion rather than `.limit(500)`: these rows are reduced into seven money
    // totals below, so a prefix makes the figures WRONG rather than short, and nothing on
    // screen said the list had been cut. `campaign_id` is the paging tiebreak, because
    // `invoice_date` is not unique and is nullable. @see .claude/rules/hub-data.md
    // @perf this is a VIEW, so each page re-runs it, which is why it was worth measuring
    //       rather than assuming. Production: 82 rows, 4.9 ms execution and 137 ms wall, one
    //       page at the 1,000 row default. Nothing to tune. P179.
    const makeSummary = () => {
      const q = supabase.from('campaign_payout_summary').select('*').neq('status', 'Cancelled')
        .order('invoice_date', { ascending: false, nullsFirst: false })
        .order('campaign_id');
      return isAdmin ? q : q.eq('creator_profile_id', creatorProfileId);
    };
    const [sumRes, glRes] = await Promise.all([
      // fetchAllRows throws; the failure is BOUND here, never swallowed into an empty list.
      fetchAllRows(makeSummary).then((data) => ({ data, error: null }), (error) => ({ data: null, error })),
      isAdmin
        ? supabase.from('ledger_journal_entries').select('source_id').eq('source_type', 'invoice').is('reversed_by_je_id', null)
        : Promise.resolve({ data: [] }),
    ]);
    if (sumRes.error || glRes?.error) {
      setLoadError(sumRes.error || glRes.error);
      setRows([]);
      setGlInvoiceSet(new Set());
      end();
      return;
    }
    setRows(sumRes.data || []);
    setGlInvoiceSet(new Set((glRes?.data || []).map(r => r.source_id).filter(Boolean)));
    end();
  }

  // Re-read on every render, so a save that refetches the list refreshes the panel's header
  // rather than leaving it on pre-save numbers. A row absent from a refetch closes the panel,
  // which is the honest answer for a campaign that was just cancelled.
  const selected = selectedId ? rows.find(r => r.campaign_id === selectedId) || null : null;

  // Every filter is compared against its own opening value, `period` included: filter-aware
  // copy that fires unconditionally tells a brand new admin to clear filters they never set.
  // `rows.length` is the other half of that answer, in the EmptyState below.
  const filtersDirty = creatorFilter !== 'all' || !!agencyFilter
    || statusFilter !== PAID_FILTER_ALL || payoutFilter !== PAID_FILTER_ALL || period !== 'all';
  function clearAllFilters() {
    setCreatorFilter('all'); setAgencyFilter(''); setStatusFilter(PAID_FILTER_ALL);
    setPayoutFilter(PAID_FILTER_ALL); setPeriod('all');
  }

  // Period anchor: invoice_date when invoiced, else campaign_start_date.
  // Without this fallback, Not Invoiced rows bypassed the period filter entirely.
  const rowPeriodDate = r => r.invoice_date || r.campaign_start_date || '';
  const months = useMemo(() => extractMonths(rows.map(r => ({ d: rowPeriodDate(r) })), 'd'), [rows]);

  // All filters apply to both tables
  const agencyNames = useMemo(() => [...new Set(rows.map(r => r.agency_name).filter(Boolean))].sort(), [rows]);

  const filtered = useMemo(() => rows.filter(r => {
    if (isAdmin && creatorFilter !== 'all' && r.creator_profile_id !== creatorFilter) return false;
    if (isAdmin && agencyFilter && r.agency_name !== agencyFilter) return false;
    if (!matchesPaidFilter(statusFilter, agencyHasPaid(r.agency_payment_status))) return false;
    if (!matchesPaidFilter(payoutFilter, creatorHasBeenPaid(r.payout_status))) return false;
    const pd = rowPeriodDate(r);
    if (pd && !inPeriod(pd, period)) return false;
    return true;
  }), [rows, creatorFilter, agencyFilter, statusFilter, payoutFilter, period, isAdmin]);

  const { cashRows, inkRows, totalContracted, totalReceived, totalPaidOut, totalPendingPayout, totalFees, totalInKind, totalStillComing } = useMemo(() => {
    const cash = filtered.filter(r => !isInKind(r.is_in_kind));
    const ink  = filtered.filter(r => isInKind(r.is_in_kind));
    const contracted = filtered.reduce((s, r) => s + (r.contracted_rate || 0), 0);
    const paidOut    = cash.filter(r => r.payout_status === 'Paid').reduce((s, r) => s + (r.payout_amount || 0), 0);
    const inKindSum  = ink.reduce((s, r) => s + (r.invoice_amount ?? r.contracted_rate ?? 0), 0);
    return {
      cashRows:          cashSort.sortRows(cash, CASH_GETTERS_STATIC),
      inkRows:           inkSort.sortRows(ink, INK_GETTERS_STATIC),
      totalContracted:   contracted,
      totalReceived:     receivedTotal(cash),
      totalPaidOut:      paidOut,
      totalPendingPayout: cash.filter(r => r.payout_status !== 'Paid' && r.payout_status !== 'N/A' && r.you_received).reduce((s, r) => s + (r.payout_amount || r.contracted_rate || 0), 0),
      // The discount belongs here too. It is billed-and-never-banked exactly like the fee,
      // and summing the fee alone made this card disagree with My Money's. @see P41
      totalFees:         round2(cash.reduce((s, r) => s + invoiceFees(r), 0)),
      totalInKind:       inKindSum,
      // Creator-only: cash owed to the creator that hasn't been paid out yet,
      // regardless of whether the bottleneck is the agency or the LLC. By
      // construction totalContracted = totalPaidOut + totalStillComing +
      // totalInKind so the five creator cards reconcile arithmetically.
      totalStillComing:  Math.max(0, contracted - paidOut - inKindSum),
    };
  }, [filtered, cashSort.sortBy, cashSort.sortDir, inkSort.sortBy, inkSort.sortDir]);

  if (loading) return <div className="page"><Loading /></div>;
  if (loadError) return <div className="page"><ReadError error={loadError} onRetry={fetchAll} /></div>;

  function CashTh({ col, children }) {
    return <SortTh sortBy={cashSort.sortBy} sortDir={cashSort.sortDir} col={col} onToggle={cashSort.toggle}>{children}</SortTh>;
  }
  function InkTh({ col, children }) {
    return <SortTh sortBy={inkSort.sortBy} sortDir={inkSort.sortDir} col={col} onToggle={inkSort.toggle}>{children}</SortTh>;
  }

  // ── Mobile render ─────────────────────────────────────────────────────────────
  if (isMobile) {
    const dimLabel = { fontSize: 9, fontWeight: 600, letterSpacing: '2.5px', textTransform: 'uppercase', color: 'var(--dim)' };
    return (
      <div className="page">

        {/* Header */}
        <div style={{ marginBottom: 20 }}>
          <h1 className="page-title">{isAdmin ? 'PAYMENTS' : 'MY PAYMENTS'}</h1>
          <div className="page-subtitle">{isAdmin ? 'Agency invoices and creator payouts' : 'Earnings and payout details per campaign'}<Refreshing on={refreshing} /></div>
        </div>

        {/* Stats: admin 2x3, creator 1x3 + 1x2 (drop Agency Paid; "Pending" → Still Coming) */}
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: 8, marginBottom: 20 }}>
          <div className="stat-card" style={{ padding: '12px 10px' }}>
            <div className="stat-value" style={{ fontSize: 16 }}>{fmtMoney(totalContracted)}</div>
            <div className="stat-label" style={{ fontSize: 10 }}>Contracted</div>
          </div>
          {isAdmin && (
            <div className="stat-card" style={{ padding: '12px 10px' }}>
              <div className="stat-value stat-green" style={{ fontSize: 16 }}>{fmtMoney(totalReceived)}</div>
              <div className="stat-label" style={{ fontSize: 10 }}>You Received</div>
            </div>
          )}
          <div className="stat-card" style={{ padding: '12px 10px' }}>
            <div className="stat-value stat-accent" style={{ fontSize: 16 }}>{fmtMoney(totalPaidOut)}</div>
            <div className="stat-label" style={{ fontSize: 10 }}>{isAdmin ? 'Paid Out' : 'Paid to Me'}</div>
          </div>
          <div className="stat-card" style={{ padding: '12px 10px' }}>
            <div className="stat-value stat-orange" style={{ fontSize: 16 }}>{fmtMoney(isAdmin ? totalPendingPayout : totalStillComing)}</div>
            <div className="stat-label" style={{ fontSize: 10 }}>{isAdmin ? 'Pending' : 'Still Coming'}</div>
          </div>
          <div className="stat-card" style={{ padding: '12px 10px' }}>
            <div className="stat-value" style={{ fontSize: 16, color: totalFees > 0 ? 'var(--red)' : 'var(--muted)' }}>{fmtMoney(totalFees)}</div>
            <div className="stat-label" style={{ fontSize: 10 }}>Fees</div>
          </div>
          <div className="stat-card" style={{ padding: '12px 10px' }}>
            <div className="stat-value" style={{ fontSize: 16, color: 'var(--muted)', fontStyle: 'italic' }}>{fmtMoney(totalInKind)}</div>
            <div className="stat-label" style={{ fontSize: 10 }}>In-Kind</div>
          </div>
        </div>

        {/* Filters: stacked labeled rows */}
        <div style={{ marginBottom: 20 }}>
          {isAdmin && creators.length > 0 && (
            <div style={{ marginBottom: 10 }}>
              <CreatorFilterChips value={creatorFilter} onChange={setCreatorFilter} creators={creators} />
            </div>
          )}
          {isAdmin && agencyNames.length > 0 && (
            <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 10 }}>
              <span style={dimLabel}>AGENCY</span>
              <AgencySelect value={agencyFilter} onChange={setAgencyFilter} options={agencyNames} />
            </div>
          )}
          <div style={{ display: 'flex', alignItems: 'center', gap: 6, flexWrap: 'wrap', marginBottom: 8 }}>
            <span style={dimLabel}>STATUS</span>
            <PaidFilterChips value={statusFilter} onChange={setStatusFilter} name="agency payments" />
          </div>
          <div style={{ display: 'flex', alignItems: 'center', gap: 6, flexWrap: 'wrap', marginBottom: 8 }}>
            <span style={dimLabel}>PAYOUT</span>
            <PaidFilterChips value={payoutFilter} onChange={setPayoutFilter} name="creator payouts" />
          </div>
          <PeriodSelect period={period} onChange={setPeriod} months={months} style={{ padding: '6px 10px', fontSize: 13 }} />
        </div>

        {/* Payment cards */}
        {cashRows.length === 0 && inkRows.length === 0 ? (
          <EmptyState icon="◇"
            title="No payments to show"
            text={isAdmin ? 'Payments will appear here once campaigns are set up.' : 'Payments will appear here once your manager sets them up.'}
            filtered={{ unfiltered: rows, dirty: filtersDirty, onClear: clearAllFilters,
              title: 'No payments match these filters',
              text: `${rows.length} ${rows.length === 1 ? 'payment is' : 'payments are'} hidden by the filters above.` }} />
        ) : (
          <>
            {cashRows.length > 0 && (
              <div style={{ display: 'flex', flexDirection: 'column', gap: 8, marginBottom: 24 }}>
                {cashRows.map(r => {
                  const { label, month } = campaignLabelParts(r);
                  return (
                    <div
                      key={r.campaign_id}
                      {...activationProps(() => setSelectedId(r.campaign_id), { pressed: selectedId === r.campaign_id })}
                      style={{
                        background: selectedId === r.campaign_id ? 'var(--orange-glow)' : 'var(--surface)',
                        border: `1px solid ${selectedId === r.campaign_id ? 'rgba(255, 92, 0, 0.45)' : 'var(--border)'}`,
                        borderRadius: 6,
                        padding: '12px 14px',
                        cursor: 'pointer',
                      }}
                    >
                      <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', gap: 8, marginBottom: 6 }}>
                        <div style={{ minWidth: 0 }}>
                          <div style={{ fontWeight: 600, fontSize: 14, lineHeight: 1.3 }}>{label}</div>
                          <div style={{ fontSize: 12, color: 'var(--muted)', marginTop: 2 }}>
                            {month}{isAdmin && (r.creator_name || r.creator_full_name) ? ` · ${r.creator_name || r.creator_full_name}` : ''}
                          </div>
                        </div>
                        <div style={{ fontWeight: 700, fontSize: 15, color: 'var(--blue)', whiteSpace: 'nowrap', flexShrink: 0 }}>{fmtMoney(r.contracted_rate)}</div>
                      </div>
                      <div style={{ display: 'flex', alignItems: 'center', gap: 6, flexWrap: 'wrap' }}>
                        <Badge group="payment" status={r.agency_payment_status || 'Not Invoiced'} />
                        {!r.you_received && (r.payout_status || PAYOUT_DEFAULT_VALUE) === PAYOUT_DEFAULT_VALUE
                          ? <span style={{ fontSize: 10, color: 'var(--muted)', letterSpacing: 0.5, textTransform: 'uppercase' }}>Waiting on agency</span>
                          : <PayoutBadge statusId={r.payout_status_id} status={r.payout_status || PAYOUT_DEFAULT_VALUE} />}
                        {r.you_received && <span style={{ fontSize: 11, color: 'var(--green)' }}>✓ {fmtDate(r.you_received_date)}</span>}
                        {r.split_count > 0 && (
                          <span style={{ fontSize: 11, color: r.splits_cleared === r.split_count ? 'var(--green)' : 'var(--muted)', marginLeft: 'auto' }}>
                            {r.splits_cleared}/{r.split_count} splits
                          </span>
                        )}
                      </div>
                    </div>
                  );
                })}
              </div>
            )}

            {inkRows.length > 0 && (
              <div style={{ borderTop: '1px solid var(--border)', paddingTop: 20, marginBottom: 24 }}>
                <div style={{ fontSize: 9, fontWeight: 600, textTransform: 'uppercase', letterSpacing: 2, color: 'var(--muted)', marginBottom: 10 }}>In-Kind Compensation</div>
                <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
                  {inkRows.map(r => {
                    const { label, month } = campaignLabelParts(r);
                    return (
                      <div
                        key={r.campaign_id}
                        {...activationProps(() => setSelectedId(r.campaign_id), { pressed: selectedId === r.campaign_id })}
                        style={{
                          background: selectedId === r.campaign_id ? 'var(--orange-glow)' : 'var(--surface)',
                          border: `1px solid ${selectedId === r.campaign_id ? 'rgba(255, 92, 0, 0.45)' : 'var(--border)'}`,
                          borderRadius: 6,
                          padding: '12px 14px',
                          cursor: 'pointer',
                        }}
                      >
                        <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', gap: 8, marginBottom: 6 }}>
                          <div style={{ minWidth: 0 }}>
                            <div style={{ fontWeight: 600, fontSize: 14 }}>{label}</div>
                            <div style={{ fontSize: 12, color: 'var(--muted)', marginTop: 2 }}>
                              {month}{isAdmin && (r.creator_name || r.creator_full_name) ? ` · ${r.creator_name || r.creator_full_name}` : ''}
                            </div>
                          </div>
                          <div style={{ fontWeight: 700, fontSize: 15, color: 'var(--muted)', fontStyle: 'italic', whiteSpace: 'nowrap', flexShrink: 0 }}>{fmtMoney(r.invoice_amount ?? r.contracted_rate)}</div>
                        </div>
                        <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                          {r.agency_name && <span style={{ fontSize: 12, color: 'var(--muted)' }}>{r.agency_name}</span>}
                          <Badge group="payment" status={r.agency_payment_status || 'Not Invoiced'} />
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>
            )}
          </>
        )}

        {selected && (
          <PaymentDetailPanel
            row={selected}
            isAdmin={isAdmin}
            isMobile
            onClose={() => setSelectedId(null)}
            onUpdated={fetchAll}
            onGoToLedger={ledgerJump(selected)}
          />
        )}
      </div>
    );
  }
  // ── Desktop render ─────────────────────────────────────────────────────────────

  return (
    <div className="page">
      <div className="page-header">
        <div>
          <h1 className="page-title">
            {isAdmin ? 'PAYMENTS' : 'MY PAYMENTS'}
            {isAdmin && <HelpIcon slug="campaign-and-invoice" />}
          </h1>
          <div className="page-subtitle">{isAdmin ? 'Agency invoices and creator payouts: two-stage tracking' : 'Earnings and payout details per campaign'}<Refreshing on={refreshing} /></div>
        </div>
      </div>

      <div className="stats-row" style={{ gridTemplateColumns: `repeat(${isAdmin ? 6 : 5}, 1fr)` }}>
        <div className="stat-card"><div className="stat-value" style={{ fontSize: 22 }}>{fmtMoney(totalContracted)}</div><div className="stat-label">Contracted<HelpIcon slug="campaign-and-invoice" /></div></div>
        {isAdmin && (
          <div className="stat-card"><div className="stat-value stat-green" style={{ fontSize: 22 }}>{fmtMoney(totalReceived)}</div><div className="stat-label">You Received<HelpIcon slug="invoice-receive" /></div></div>
        )}
        <div className="stat-card"><div className="stat-value stat-accent" style={{ fontSize: 22 }}>{fmtMoney(totalPaidOut)}</div><div className="stat-label">{isAdmin ? 'Paid to Creators' : 'Paid to Me'}<HelpIcon slug="payout" /></div></div>
        {isAdmin
          ? <div className="stat-card"><div className="stat-value stat-orange" style={{ fontSize: 22 }}>{fmtMoney(totalPendingPayout)}</div><div className="stat-label">Awaiting Payout<HelpIcon slug="payout" /></div></div>
          : <div className="stat-card"><div className="stat-value stat-orange" style={{ fontSize: 22 }}>{fmtMoney(totalStillComing)}</div><div className="stat-label">Still Coming<HelpIcon slug="payout" /></div></div>}
        <div className="stat-card">
          <div className="stat-value" style={{ fontSize: 22, color: totalFees > 0 ? 'var(--red)' : 'var(--muted)' }}>{fmtMoney(totalFees)}</div>
          <div className="stat-label">Fees<HelpIcon slug="invoice-receive" /></div>
          {!isAdmin && <div className="stat-note">Already deducted, not part of Contracted.</div>}
        </div>
        <div className="stat-card"><div className="stat-value" style={{ fontSize: 22, color: 'var(--muted)', fontStyle: 'italic' }}>{fmtMoney(totalInKind)}</div><div className="stat-label">In-Kind FMV<HelpIcon slug="in-kind" /></div></div>
      </div>

      <div className="filters-row" style={{ flexWrap: 'wrap' }}>
        {isAdmin && (
          <>
            <span className="text-muted text-xs">CREATOR</span>
            <CreatorFilterChips value={creatorFilter} onChange={setCreatorFilter} creators={creators} />
            <div style={{ width: 1, height: 16, background: 'var(--border)', margin: '0 6px' }} />
            <span className="text-muted text-xs">AGENCY</span>
            <AgencySelect value={agencyFilter} onChange={setAgencyFilter} options={agencyNames} />
            <div style={{ width: 1, height: 16, background: 'var(--border)', margin: '0 6px' }} />
          </>
        )}
        <span className="text-muted text-xs">STATUS</span>
        <PaidFilterChips value={statusFilter} onChange={setStatusFilter} name="agency payments" />
        <div style={{ width: 1, height: 16, background: 'var(--border)', margin: '0 6px' }} />
        <span className="text-muted text-xs">PAYOUT</span>
        <PaidFilterChips value={payoutFilter} onChange={setPayoutFilter} name="creator payouts" />
        <PeriodSelect period={period} onChange={setPeriod} months={months} style={{ marginLeft: 8 }} />
      </div>

      {cashRows.length === 0 && inkRows.length === 0 ? (
        <EmptyState icon="◇"
          title="No payments to show"
          text={isAdmin ? 'Payments will appear here once campaigns are set up.' : 'Payments will appear here once your manager sets them up.'}
          filtered={{ unfiltered: rows, dirty: filtersDirty, onClear: clearAllFilters,
            title: 'No payments match these filters',
            text: `${rows.length} ${rows.length === 1 ? 'payment is' : 'payments are'} hidden by the filters above.` }} />
      ) : (
        <>
          {cashRows.length > 0 && (
            <div className="table-wrap">
              <table>
                <thead>
                  <tr>
                    <CashTh col="campaign">Campaign</CashTh>
                    {isAdmin && <CashTh col="creator">Creator</CashTh>}
                    <CashTh col="contracted">Contracted</CashTh>
                    <CashTh col="agency">Agency Status</CashTh>
                    <CashTh col="received">{isAdmin ? 'You Received' : 'Agency Cleared'}</CashTh>
                    <CashTh col="cashin">Cash In</CashTh>
                    <CashTh col="fee">Fee</CashTh>
                    <CashTh col="payout">Payout Status</CashTh>
                    <CashTh col="payoutamt">Payout Out</CashTh>
                    <CashTh col="splits">Splits</CashTh>
                  </tr>
                </thead>
                <tbody>
                  {cashRows.map(r => (
                    <tr key={r.campaign_id} className={selectedId === r.campaign_id ? 'is-selected' : ''} {...activationProps(() => setSelectedId(r.campaign_id), { pressed: selectedId === r.campaign_id })} style={{ cursor: 'pointer' }}>
                      <td>
                        <CampaignName campaign={r} />
                      </td>
                      {isAdmin && <td>{r.creator_name || r.creator_full_name || '—'}</td>}
                      <td style={{ fontWeight: 600 }}>{fmtMoney(r.contracted_rate)}</td>
                      <td><Badge group="payment" status={r.agency_payment_status || 'Not Invoiced'} /></td>
                      <td>
                        {r.you_received
                          ? <span style={{ color: 'var(--green)', fontWeight: 600, fontSize: 12 }}>✓ {fmtDate(r.you_received_date)}</span>
                          : <span className="text-muted text-xs">Not yet</span>}
                      </td>
                      <td>
                        {r.amount_received != null
                          ? <span style={{ color: r.amount_received < (r.invoice_amount || r.contracted_rate) ? 'var(--orange)' : 'var(--white)' }}>{fmtMoney(r.amount_received)}</span>
                          : <span className="text-muted">—</span>}
                      </td>
                      <td>{r.processing_fee > 0 ? <span style={{ color: 'var(--red)', fontSize: 12 }}>{fmtMoney(r.processing_fee)}</span> : <span className="text-muted">—</span>}</td>
                      <td>
                        {!r.you_received && (r.payout_status || PAYOUT_DEFAULT_VALUE) === PAYOUT_DEFAULT_VALUE
                          ? <span style={{ fontSize: 10, color: 'var(--muted)', letterSpacing: 0.5, textTransform: 'uppercase' }}>Waiting on agency</span>
                          : <PayoutBadge statusId={r.payout_status_id} status={r.payout_status || PAYOUT_DEFAULT_VALUE} />}
                      </td>
                      <td>
                        {r.payout_amount != null
                          ? <span style={{ color: 'var(--blue)', fontWeight: 600 }}>{fmtMoney(r.payout_amount)}</span>
                          : <span className="text-muted">—</span>}
                      </td>
                      <td>
                        {r.split_count > 0
                          ? <span className="text-sm" style={{ color: r.splits_cleared === r.split_count ? 'var(--green)' : 'var(--muted)' }}>{r.splits_cleared}/{r.split_count} cleared</span>
                          : <span className="text-muted text-xs">—</span>}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}

          {inkRows.length > 0 && (
            <div style={{ marginTop: 32, borderTop: '1px solid var(--border)', paddingTop: 24 }}>
              <div style={{ fontSize: 9, fontWeight: 600, textTransform: 'uppercase', letterSpacing: 2, color: 'var(--muted)', marginBottom: 12 }}>In-Kind Compensation</div>
              <div className="table-wrap">
                <table>
                  <thead>
                    <tr>
                      <InkTh col="campaign">Campaign</InkTh>
                      {isAdmin && <InkTh col="creator">Creator</InkTh>}
                      <InkTh col="agency">Agency</InkTh>
                      <InkTh col="fairvalue">Fair Value</InkTh>
                      <InkTh col="agencystatus">Agency Status</InkTh>
                      <th scope="col">Notes</th>
                    </tr>
                  </thead>
                  <tbody>
                    {inkRows.map(r => (
                      <tr key={r.campaign_id} className={selectedId === r.campaign_id ? 'is-selected' : ''} {...activationProps(() => setSelectedId(r.campaign_id), { pressed: selectedId === r.campaign_id })} style={{ cursor: 'pointer' }}>
                        <td>
                          <CampaignName campaign={r} />
                        </td>
                        {isAdmin && <td>{r.creator_name || r.creator_full_name || '—'}</td>}
                        <td>{r.agency_name || <span className="text-muted">—</span>}</td>
                        <td style={{ fontWeight: 600 }}>{fmtMoney(r.invoice_amount ?? r.contracted_rate)}</td>
                        <td><Badge group="payment" status={r.agency_payment_status || 'Not Invoiced'} /></td>
                        <td><span style={{ fontSize: 11, color: 'var(--muted)', fontStyle: 'italic' }}>No cash payout</span></td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          )}
        </>
      )}

      {selected && (
        <PaymentDetailPanel
          row={selected}
          isAdmin={isAdmin}
          onClose={() => setSelectedId(null)}
          onUpdated={fetchAll}
          onGoToLedger={ledgerJump(selected)}
        />
      )}
    </div>
  );
}

// ── Detail panel ──────────────────────────────────────────────────────────────
/**
 * Slide-in (desktop) / bottom-sheet (mobile) panel for one campaign: a
 * CampaignReference reconciliation block plus Invoice and Payout tabs. Admin
 * gets the editable forms; creator gets the read-only views.
 *
 * @gotcha self-loads the invoice + payout + splits + the invoice's JEs so the
 *         list view never has to thread that data through. Destinations and the
 *         per-split JEs are deliberately NOT loaded here: PayoutForm loads both
 *         for itself.
 * @gotcha the creator_payouts split embed MUST use PAYOUT_SPLIT_DESTINATION_EMBED.
 */
function PaymentDetailPanel({ row, isAdmin, isMobile = false, onClose, onUpdated, onGoToLedger }) {
  const { dirtyProps } = useUnsavedGuard();
  const { options: statusOptions } = useStatusOptions();
  const [invoice,      setInvoice]      = useState(null);
  const [payout,       setPayout]       = useState(null);
  const [splits,       setSplits]       = useState([]);
  const [tab,          setTab]          = useState('invoice');
  const { loading, refreshing, begin, end } = useLoadState();
  const [showPreview,  setShowPreview]  = useState(false);
  const [panelVisible, setPanelVisible] = useState(false);
  const [issuedDoc,    setIssuedDoc]    = useState(null);
  // Held apart from `issuedDoc`, because null means two things and only one of them may
  // offer to regenerate. @see utils/invoiceDocuments.js loadCurrentDoc
  const [issuedDocError, setIssuedDocError] = useState(null);
  const [genRetrying,  setGenRetrying]  = useState(false);
  const [genError,     setGenError]     = useState('');
  const [invoiceJes,   setInvoiceJes]   = useState([]);  // [{ entry, lines }]
  // The third state for the panel's own reads. A refused `invoices` read left `invoice` null,
  // which is what "not invoiced yet" looks like: the panel offered to create one, and loadJes
  // was then called with undefined, found no journal entries, and InvoiceLock unlocked every
  // field on an invoice whose AR entry is posted.
  const [detailError,  setDetailError]  = useState(null);

  useEffect(() => { fetchDetail(); }, [row.campaign_id]);
  useEffect(() => {
    if (isMobile) requestAnimationFrame(() => setPanelVisible(true));
  }, [isMobile]);

  function handleClose() {
    if (isMobile) {
      setPanelVisible(false);
      setTimeout(onClose, 280);
    } else {
      onClose();
    }
  }

  async function fetchDetail() {
    begin();
    setDetailError(null);
    const [invRes, payoutRes] = await Promise.all([
      supabase.from('invoices').select('*').eq('campaign_id', row.campaign_id).maybeSingle(),
      supabase.from('creator_payouts').select(`*, payout_splits(*, ${PAYOUT_SPLIT_DESTINATION_EMBED}(*), expense:expenses(id, name, type, frequency, amount))`).eq('campaign_id', row.campaign_id).maybeSingle(),
    ]);
    if (invRes.error || payoutRes.error) {
      setDetailError(invRes.error || payoutRes.error);
      setInvoice(null); setPayout(null); setSplits([]); setInvoiceJes([]); setIssuedDoc(null); setIssuedDocError(null);
      end();
      return;
    }
    setInvoice(invRes.data || null);
    setPayout(payoutRes.data || null);
    setSplits(payoutRes.data?.payout_splits || []);
    end();
    if (invRes.data?.id) {
      const { doc, error: docErr } = await loadCurrentDoc(invRes.data.id, 'issued_invoice');
      setIssuedDoc(doc);
      setIssuedDocError(docErr || null);
    } else {
      setIssuedDoc(null);
      setIssuedDocError(null);
    }
    await loadJes(invRes.data?.id);
  }

  /* Only the invoice's own JEs, which drive InvoiceForm's field locks.
   *
   * @gotcha this panel does NOT load the destinations or the per-split JEs.
   *         PayoutForm loads both for itself, and the copies here were dead
   *         from the day it did. */
  async function loadJes(invoiceId) {
    if (!invoiceId) { setInvoiceJes([]); return; }
    try {
      setInvoiceJes(await fetchJournalEntriesWithLines('invoice', [invoiceId]));
    } catch (e) {
      // An empty JE list is what an unposted invoice looks like, and it is what unlocks the
      // form. A refused probe must not be read as one.
      setInvoiceJes([]);
      setDetailError(e);
    }
  }

  async function handleGenRetry() {
    if (!invoice?.id) return;
    setGenRetrying(true);
    setGenError('');
    try {
      await generateAndUploadIssuedInvoice(invoice.id);
      const { doc, error: docErr } = await loadCurrentDoc(invoice.id, 'issued_invoice');
      setIssuedDoc(doc);
      setIssuedDocError(docErr || null);
    } catch (e) {
      setGenError(e?.message || String(e));
    }
    setGenRetrying(false);
  }

  // Show retry banner only for cash invoices that are in the billed
  // set but have no current issued_invoice document. In-kind invoices
  // skip auto-PDF gen so they don't get a banner.
  const paymentValue = invoice
    ? (statusOptions.payment || []).find(o => o.id === invoice.payment_status_id)?.value
    : null;
  const showRetryBanner = !!invoice && !invoice.is_in_kind
    && BILLED_PAYMENT_VALUES.includes(paymentValue) && !issuedDoc && !issuedDocError && !loading;

  const panelInner = (
    <>
      <div className="detail-header">
        <div className="flex items-center justify-end mb-8">
          <button className="btn btn-ghost btn-icon btn-sm" onClick={handleClose} aria-label="Close payment details">✕</button>
        </div>
        {/* The display name carries agency AND creator, so neither is repeated
            below it. The date is: a name carries none, and it is what separates
            two deals with the same agency and creator. */}
        <h2 className="detail-panel-title">{campaignLabelParts(row).label}</h2>
        <div className="text-muted mt-4">{campaignLabelParts(row).date}</div>
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginTop: 8 }}>
          <div style={{ color: 'var(--blue)', fontWeight: 700, fontSize: 18 }}>{fmtMoney(row.contracted_rate)}</div>
          <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
            {onGoToLedger && (
              <button type="button" className="detail-ledger-link" onClick={onGoToLedger}>
                View in General Ledger
              </button>
            )}
            {!loading && invoice && (
              <button className="btn btn-secondary btn-sm" onClick={() => setShowPreview(true)}>
                {isInKind(row.is_in_kind) ? 'View Record' : 'View Invoice'}
              </button>
            )}
          </div>
        </div>
      </div>

      <CampaignReference campaignId={row.campaign_id} row={row} isMobile={isMobile} />

      <Tabs
        label="Payment detail"
        panelId="payment-detail-panel"
        style={{ padding: '0 24px' }}
        value={tab}
        onChange={setTab}
        items={['invoice', 'payout'].map(t => ({
          id: t,
          label: isMobile
            ? (t === 'invoice' ? 'Invoice' : 'Payout')
            : (t === 'invoice' ? 'Invoice (Agency → You)' : 'Payout (You → Creator)'),
        }))}
      />

      <div className="detail-body" style={isMobile ? { flex: 1, overflowY: 'auto', WebkitOverflowScrolling: 'touch' } : {}} {...tabPanelProps('payment-detail-panel', tab)}>
        <Refreshing on={refreshing} />
        {/* Generate is withheld while the reason stands: it inserts a superseding v2 and the
            trigger demotes the version the agency already holds a link to. */}
        {tab === 'invoice' && isAdmin && issuedDocError ? (
          <div style={{ margin: '0 0 16px 0' }}><ReadError error={issuedDocError} onRetry={fetchDetail} /></div>
        ) : null}
        {tab === 'invoice' && isAdmin && showRetryBanner ? (
          <div style={{ margin: '0 0 16px 0', padding: '10px 14px', background: 'var(--orange-glow)', borderLeft: '3px solid var(--orange)', borderRadius: 4, display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: 12, flexWrap: 'wrap' }}>
            <div style={{ fontSize: 12 }}>
              <strong>Issued PDF missing.</strong> The agency-facing invoice PDF was not generated when this invoice was last saved.
              {genError ? <div role="alert" style={{ color: 'var(--red)', marginTop: 4 }}>{genError}</div> : null}
            </div>
            <button className="btn btn-secondary btn-sm" onClick={handleGenRetry} disabled={genRetrying}>
              {genRetrying ? 'Generating…' : 'Generate PDF'}
            </button>
          </div>
        ) : null}
        {loading ? <Loading /> : detailError ? (
          <ReadError error={detailError} onRetry={fetchDetail} />
        ) : (
          tab === 'invoice'
            ? (isAdmin
                ? <InvoiceForm invoice={invoice} row={row} invoiceJes={invoiceJes} onUpdated={() => { fetchDetail(); onUpdated(); }} />
                : <InvoiceReadOnly invoice={invoice} row={row} />)
            : (isAdmin
                ? <PayoutForm
                    /* Campaign-side config for the shared PayoutForm (reward side
                       passes kind:'reward'). PayoutForm self-loads its own
                       payout/splits/destinations from parentId.
                       @see components/shared/PayoutForm.js */
                    parent={{
                      kind: 'campaign',
                      parentId: row.campaign_id,
                      creatorId: row.creator_profile_id,
                      creatorName: row.creator_name,
                      youReceived: row.you_received,
                      isInKind: isInKind(row.is_in_kind),
                      payoutAmountDefault: row.amount_received ?? row.contracted_rate ?? '',
                      invoiceId: row.invoice_id,
                      contractedAmount: row.contracted_rate,
                      // The month the AGENCY's cash landed, which is the month payroll settles
                      // it in. @see components/shared/PayoutForm.js
                      cashMonth: (row.agency_paid_date || '').slice(0, 7) || null,
                    }}
                    onUpdated={() => { fetchDetail(); onUpdated(); }}
                  />
                : <PayoutReadOnly payout={payout} splits={splits} row={row} />)
        )}
      </div>

      {showPreview && (
        <Suspense fallback={
          <div className="modal-overlay" style={{ display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
            <div className="splash-spinner" />
          </div>
        }>
          <InvoicePreviewModal
            row={row}
            invoice={invoice}
            onClose={() => setShowPreview(false)}
          />
        </Suspense>
      )}
    </>
  );

  if (isMobile) {
    return (
      <>
        <div
          aria-hidden="true"
          onClick={handleClose}
          style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.6)', zIndex: 200, animation: 'fadeIn 0.2s ease' }}
        />
        <div style={{
          position: 'fixed', bottom: 0, left: 0, right: 0, height: '92dvh',
          background: 'var(--surface)', borderRadius: '16px 16px 0 0',
          zIndex: 201, display: 'flex', flexDirection: 'column', overflow: 'hidden',
          transform: panelVisible ? 'translateY(0)' : 'translateY(100%)',
          transition: 'transform 0.28s cubic-bezier(0.4,0,0.2,1)',
        }}>
          <div style={{ display: 'flex', justifyContent: 'center', padding: '12px 0 4px', flexShrink: 0 }}>
            <div style={{ width: 36, height: 4, background: 'var(--border2)', borderRadius: 2 }} />
          </div>
          {panelInner}
        </div>
      </>
    );
  }

  return <div className="detail-panel" {...dirtyProps}>{panelInner}</div>;
}

// ── Invoice - read-only (creator view) ────────────────────────────────────────
/** Creator-facing invoice summary (agency-payment status, amount, receipt info). No edits. */
function InvoiceReadOnly({ invoice, row }) {
  const inKind = isInKind(invoice?.is_in_kind ?? row.is_in_kind);
  return (
    <div>
      <h3 className="detail-section-title">AGENCY PAYMENT</h3>
      <div className="detail-grid">
        <div>
          <div className="detail-item-label">Status</div>
          <div className="detail-item-value"><Badge group="payment" statusId={invoice?.payment_status_id} /></div>
        </div>
        <div>
          <div className="detail-item-label">{inKind ? 'Fair Value (In Kind)' : 'Invoice Amount'}</div>
          <div className="detail-item-value" style={{ fontWeight: 600 }}>{fmtMoney(invoice?.invoice_amount ?? row.contracted_rate)}</div>
        </div>
        {invoice?.invoice_number && (
          <div>
            <div className="detail-item-label">Invoice #</div>
            <div className="detail-item-value">{invoice.invoice_number}</div>
          </div>
        )}
        {invoice?.invoice_date && (
          <div>
            <div className="detail-item-label">Invoice Date</div>
            <div className="detail-item-value">{fmtDate(invoice.invoice_date)}</div>
          </div>
        )}
        {invoice?.payment_method && (
          <div>
            <div className="detail-item-label">Payment Method</div>
            <div className="detail-item-value">{invoice.payment_method}</div>
          </div>
        )}
      </div>

      {inKind ? (
        <div style={{ marginTop: 12, padding: '12px 14px', borderRadius: 6, fontSize: 12, background: 'rgba(255,255,255,0.04)', border: '1px solid var(--border)', color: 'var(--muted)', lineHeight: 1.6 }}>
          <div style={{ fontWeight: 600, color: 'var(--white)', marginBottom: 4, fontSize: 11, letterSpacing: 1, textTransform: 'uppercase' }}>In-Kind Compensation</div>
          Fair value tracked for tax purposes only. No cash changes hands.
        </div>
      ) : invoice?.you_received ? (
        <>
          <div className="divider" />
          <h3 className="detail-section-title">RECEIVED BY MANAGER</h3>
          <div className="detail-grid">
            <div>
              <div className="detail-item-label">Date Cleared</div>
              <div className="detail-item-value" style={{ color: 'var(--green)' }}>✓ {fmtDate(invoice.you_received_date)}</div>
            </div>
            <div>
              <div className="detail-item-label">Amount Received</div>
              <div className="detail-item-value" style={{ fontWeight: 600 }}>{fmtMoney(invoice.amount_received)}</div>
            </div>
            {invoice.processing_fee > 0 && (
              <div>
                <div className="detail-item-label">Processing Fee</div>
                <div className="detail-item-value" style={{ color: 'var(--orange)' }}>{fmtMoney(invoice.processing_fee)}</div>
              </div>
            )}
            {invoice.you_received_notes && (
              <div style={{ gridColumn: 'span 2' }}>
                <div className="detail-item-label">Notes</div>
                <div className="detail-item-value text-muted">{invoice.you_received_notes}</div>
              </div>
            )}
          </div>
        </>
      ) : (
        <EmptyState variant="note" style={{ paddingTop: 12 }} text="Payment not yet received by your manager." />
      )}
    </div>
  );
}

// ── Payout - read-only (creator view) ────────────────────────────────────────
/** Creator-facing payout summary with the per-destination split breakdown. No edits. */
function PayoutReadOnly({ payout, splits, row }) {
  const inKind = isInKind(row.is_in_kind);
  if (inKind) {
    return (
      <div style={{ padding: '16px 18px', borderRadius: 8, fontSize: 13, background: 'rgba(255,255,255,0.04)', border: '1px solid var(--border)', color: 'var(--muted)', lineHeight: 1.7 }}>
        <div style={{ fontWeight: 600, color: 'var(--white)', marginBottom: 6, fontSize: 11, letterSpacing: 1, textTransform: 'uppercase' }}>In-Kind Campaign</div>
        This campaign was compensated in kind. No cash payout applies.
      </div>
    );
  }
  if (!payout) {
    return <EmptyState variant="note" text="Payout not yet created by your manager." />;
  }
  return (
    <div>
      <h3 className="detail-section-title">YOUR PAYOUT</h3>
      <div className="detail-grid" style={{ marginBottom: 16 }}>
        <div>
          <div className="detail-item-label">Total Payout</div>
          <div className="detail-item-value" style={{ color: 'var(--blue)', fontWeight: 700, fontSize: 18 }}>{fmtMoney(payout.payout_amount)}</div>
        </div>
        <div>
          <div className="detail-item-label">Status</div>
          <div className="detail-item-value"><PayoutBadge statusId={payout.payout_status_id} status={payout.payout_status} /></div>
        </div>
        {payout.payout_date && (
          <div>
            <div className="detail-item-label">Payout Date</div>
            <div className="detail-item-value">{fmtDate(payout.payout_date)}</div>
          </div>
        )}
        {payout.payout_notes && (
          <div style={{ gridColumn: 'span 2' }}>
            <div className="detail-item-label">Notes</div>
            <div className="detail-item-value text-muted">{payout.payout_notes}</div>
          </div>
        )}
      </div>

      <div style={{ fontSize: 11, fontWeight: 600, textTransform: 'uppercase', letterSpacing: 1, color: 'var(--dim)', marginBottom: 10 }}>DESTINATION BREAKDOWN</div>
      <SplitBreakdown splits={splits} emptyText="No splits recorded yet." />
    </div>
  );
}

// ── Invoice form - editable (admin view) ──────────────────────────────────────
/**
 * The admin invoice editor (this page is the system's single editor for campaign
 * invoice fields). Handles cash + in-kind; on save it re-posts Pattern A/C (AR)
 * and, when received, Pattern B (cash), then auto-generates the issued PDF.
 *
 * @param {object[]} invoiceJes - posted JEs touching this invoice ([{entry,lines}]); drives the field locks
 * @gotcha receipt math: invoice_amount = amount_received + processing_fee +
 *         discount_amount. discount_amount is user-entered; processing_fee is the
 *         derived remainder (read-only). @see utils/invoiceMath.js
 * @gotcha the AR/cash re-post RPCs are idempotent (internal NOT EXISTS guards) so
 *         a reverse-then-edit that leaves status unchanged still reposts the JE.
 * @invariant once a JE posts, its source fields are sealed by DB triggers and
 *            mirrored here via LockedField / CheckboxLock; edits require reversing
 *            the entry first. @see components/shared/InvoiceLock.js
 */
function InvoiceForm({ invoice, row, invoiceJes = [], onUpdated }) {
  const toast = useToast();
  const today = todayYMD();
  const v = useFormValidation({
    invoice_date:          { date: true, dateBetween: [DB_DATE_MIN, today], message: 'Invoice date cannot be in the future.' },
    due_date:              { date: true, dateBetween: [DB_DATE_MIN, DB_DATE_MAX] },
    payment_received_date: { date: true, dateBetween: [DB_DATE_MIN, today], message: 'Payment received date cannot be in the future.' },
    you_received_date:     { date: true, dateBetween: [DB_DATE_MIN, today], message: 'Cash received date cannot be in the future.' },
    invoice_amount:        { number: true, min: 0.01, message: 'Amount must be more than zero.' },
    in_kind_value:         { number: true, min: 0.01, message: 'Fair market value must be more than zero.' },
    net_received:          { number: true, min: 0, message: 'Net received must be zero or more.' },
    discount_amount:       { number: true, min: 0, message: 'Discount must be zero or more.' },
  });
  const [reverseFor, setReverseFor] = useState(null); // { entry, lines }
  const arJe        = findArJe(invoiceJes);
  const cashJe      = findCashJe(invoiceJes);
  const arJeExists  = !!arJe;
  const cashJeExists = !!cashJe;
  const { options: statusOptions } = useStatusOptions();
  const paymentOpts = statusOptions.payment || [];
  const [form, setForm] = useState({
    po_number:            invoice?.po_number || '',
    invoice_date:         invoice?.invoice_date || '',
    due_date:             invoice?.due_date || '',
    invoice_amount:       invoice?.invoice_amount ?? row.contracted_rate ?? '',
    currency:             invoice?.currency || 'USD',
    payment_status_id:    invoice?.payment_status_id || paymentOpts.find(o => o.value === 'Not Invoiced')?.id || '',
    payment_received_date: invoice?.payment_received_date || '',
    payment_method:       invoice?.payment_method || '',
    payment_notes:        invoice?.payment_notes || '',
    is_in_kind:           invoice?.is_in_kind || false,
    in_kind_value:        invoice?.in_kind_value ?? '',
    in_kind_description:  invoice?.in_kind_description || '',
    you_received:         invoice?.you_received ?? false,
    you_received_date:    invoice?.you_received_date || '',
    you_received_notes:   invoice?.you_received_notes || '',
    net_received:         invoice?.amount_received ?? '',
    discount_amount:      invoice?.discount_amount != null && invoice.discount_amount !== 0 ? String(invoice.discount_amount) : '',
    service_description:  invoice?.service_description || '',
    invoice_notes:        invoice?.invoice_notes || '',
  });
  // Agency-status options for the dropdown. Cash invoices never show "In Kind".
  // In-kind invoices drop the cash-terminal statuses (Paid / Overdue) and relabel
  // "In Kind" as "Received" so marking goods-received reads naturally and shows
  // the IN KIND badge (value stays 'In Kind'). @see in-kind table badge.
  const agencyOptions = form.is_in_kind
    ? paymentOpts
        .filter(o => o.value !== 'Paid' && o.value !== 'Overdue')
        .map(o => (o.value === 'In Kind' ? { ...o, label: 'Received' } : o))
    : paymentOpts.filter(o => o.value !== 'In Kind');
  const [saving,        setSaving]        = useState(false);
  const [generatingPdf, setGeneratingPdf] = useState(false);
  const [uploading,     setUploading]     = useState(false);
  const [receiptPath,   setReceiptPath]   = useState(null);
  const [receiptName,   setReceiptName]   = useState(null);
  // Held apart from `receiptPath`, the way RewardsPage holds `issuedDocError` apart from the
  // issued PDF: a null path is "no receipt" AND "we could not check", and only the first may
  // draw a drop zone. Raw, because ReadError humanizes.
  const [receiptError,  setReceiptError]  = useState(null);
  const [paymentMethods, setPaymentMethods] = useState([]);
  // Reports beside the picker, never in place of the form: this read fills one control and the
  // other twenty fields save without it. An empty list reads as "no payment methods are
  // configured", which sends an admin to Payment Setup to add ones already there.
  // @see .claude/rules/hub-ui.md (scope the state to what the read feeds)
  const [methodsError,  setMethodsError]  = useState(null);
  const [formError,     setFormError]     = useState('');
  const [uploadError,   setUploadError]   = useState('');

  const loadMethods = useCallback(() => {
    setMethodsError(null);
    supabase.from('payment_methods').select('name').eq('is_active', true).order('sort_order').order('name')
      .then(({ data, error }) => {
        if (error) { setMethodsError(error); setPaymentMethods([]); return; }
        setPaymentMethods((data || []).map(m => m.name));
      });
  }, []);

  useEffect(() => { loadMethods(); }, [loadMethods]);

  const loadReceipt = useCallback(() => {
    if (!invoice?.id) { setReceiptPath(null); setReceiptName(null); setReceiptError(null); return; }
    loadCurrentDoc(invoice.id, 'payment_receipt').then(({ doc, error }) => {
      setReceiptPath(doc?.file_path || null);
      setReceiptName(doc?.file_name || null);
      setReceiptError(error || null);
    });
  }, [invoice?.id]);

  useEffect(() => { loadReceipt(); }, [loadReceipt]);

  const inKind = form.is_in_kind;

  async function save() {
    setFormError('');
    const ok = v.validate(form);
    // The invoice's value is the FMV for in-kind, or the amount for cash. The
    // static rules can't branch on is_in_kind, so enforce a positive value here
    // and surface it on whichever field is actually visible.
    const extra = {};
    if (inKind) {
      if (!(parseFloat(form.in_kind_value) > 0)) extra.in_kind_value = 'Fair market value must be more than zero.';
    } else if (!(parseFloat(form.invoice_amount) > 0)) {
      extra.invoice_amount = 'Amount must be more than zero.';
    }
    // @invariant these four dates run in sequence. `chk_invoices_dates` bounds each of them on
    //            its own and says nothing about their ORDER, and `useFormValidation` declares
    //            one window per field with no way to relate two, so this is the only guard
    //            there is. ISO YYYY-MM-DD sorts lexically, so a string compare is safe. The
    //            due date is the one that leaves the building: it prints on the PDF the agency
    //            receives.
    if (form.invoice_date && form.due_date && form.due_date < form.invoice_date) {
      extra.due_date = 'Due date cannot be before the invoice date.';
    }
    if (form.invoice_date && form.payment_received_date && form.payment_received_date < form.invoice_date) {
      extra.payment_received_date = 'Agency paid date cannot be before the invoice date.';
    }
    // Invoice Date is what create_invoice_ar_entry dates Pattern A and Pattern C from, and it
    // raises rather than substituting, so the form has to ask for it wherever an entry is about
    // to post: always on the in-kind arm, and on the cash arm once the status is billed. A
    // draft nobody has issued yet is exempt, which is why this reads the status rather than
    // marking the field required outright. @see docs/MONEY.md Pattern A, Pattern C
    const billed = BILLED_PAYMENT_VALUES.includes(
      (agencyOptions.find((o) => o.id === form.payment_status_id) || {}).value
    );
    if (!form.invoice_date && (inKind || billed)) {
      extra.invoice_date = 'Enter the invoice date. It is the date this goes on the books.';
    }
    // Mirrors chk_invoices_received_needs_date: money that has cleared has a day it cleared
    // on. The date is the cash entry's entry_date, so a blank one is not a blank field, it is
    // a receipt posted on the wrong day and sealed there by the field lock.
    // @see docs/MONEY.md Pattern B
    if (!inKind && form.you_received && !cashJeExists && !form.you_received_date) {
      extra.you_received_date = 'Enter the date the money cleared your account.';
    }
    // Scoped the way the expense form scopes its end date: Date Cleared renders only under the
    // you_received checkbox and only on the cash branch, and a save must never be refused over
    // a field the person cannot see. Same reason the check above also waits on `!cashJeExists`:
    // the field is disabled once the cash entry is posted, and an error on a field nobody can
    // type into would block every other still-editable field on the invoice.
    if (!inKind && form.you_received && form.payment_received_date && form.you_received_date
        && form.you_received_date < form.payment_received_date) {
      extra.you_received_date = 'Date cleared cannot be before the agency paid date.';
    }
    if (Object.keys(extra).length) v.setErrors(e => ({ ...e, ...extra }));
    if (!ok || Object.keys(extra).length) {
      setFormError({ tone: 'error', title: 'Fix the highlighted fields and try again.' });
      return;
    }
    if (!inKind) {
      const sumErr = validateReceiptSums(form.invoice_amount, form.net_received, form.discount_amount);
      if (sumErr) { setFormError(sumErr); return; }
    }
    setSaving(true);
    const payload = buildCampaignInvoicePayload(form);
    /* ONE transaction for the invoice row and both of its ledger re-posts. Writing the row,
     * then create_invoice_ar_entry, then create_invoice_received_entry is three PostgREST
     * requests and therefore three committed transactions, and an interrupted save leaves a
     * committed invoice whose ledger entries never posted: Payments shows the invoice, the
     * books do not have it, and nothing compares the two numbers.
     *
     * The RPC calls both posting functions on every save: the reverse-then-edit flow leaves
     * the status unchanged so the trigger does not refire, and both carry their own NOT
     * EXISTS guard, so it is a no-op when a live JE exists.
     * @see schemas/SCHEMA.sql save_invoice_with_postings */
    const { data: savedId, error: saveErr } = await supabase.rpc('save_invoice_with_postings', {
      p_invoice: invoice ? { ...payload, id: invoice.id } : payload,
      p_campaign_id: invoice ? null : row.campaign_id,
    });
    if (saveErr) {
      // Surface DB rejections (e.g. prevent_invoice_trigger_field_mutation) to the user.
      if (process.env.NODE_ENV !== 'production') console.error('[InvoiceForm] save failed', saveErr);
      setFormError(humanizeError(saveErr));
      setSaving(false);
      return;
    }
    const savedInvoiceId = savedId || invoice?.id || null;

    // Auto-generate the formal issued_invoice PDF when the saved status
    // is in the billed set AND a current document doesn't exist yet.
    // Cash invoices only - in-kind records skip PDF gen for now.
    if (savedInvoiceId && !inKind && payload.payment_status_id) {
      const newStatus = agencyOptions.find(o => o.id === payload.payment_status_id);
      if (newStatus && BILLED_PAYMENT_VALUES.includes(newStatus.value)) {
        try {
          setGeneratingPdf(true);
          const { doc: existing, error: probeErr } = await loadCurrentDoc(savedInvoiceId, 'issued_invoice');
          // A refused probe is not "no PDF yet". Leave it to the panel, which reports it.
          if (!probeErr && !existing) await generateAndUploadIssuedInvoice(savedInvoiceId);
        } catch (e) {
          if (process.env.NODE_ENV !== 'production') console.error('[InvoiceForm] auto PDF gen', e);
          // Don't block save flow - the retry banner in the panel will catch this.
        } finally {
          setGeneratingPdf(false);
        }
      }
    }

    setSaving(false);
    toast.success('Invoice saved');
    onUpdated();
  }

  async function uploadReceipt(file) {
    if (!file) return;
    let invoiceId = invoice?.id;
    if (!invoiceId) {
      const { data: newInv, error: newInvErr } = await supabase.from('invoices').insert({ campaign_id: row.campaign_id, payment_status_id: form.payment_status_id || null }).select().single();
      // A write whose result is read, so the unchecked-WRITE gate cannot see it:
      // a failed insert dropped the upload with no message at all.
      if (newInvErr) { setUploadError(humanizeError(newInvErr)?.body || 'Could not create the invoice.'); return; }
      invoiceId = newInv?.id;
      if (!invoiceId) return;
    }
    await uploadPaymentReceipt({ file, invoiceId, setUploading, onSuccess: (path, name) => { setReceiptPath(path); setReceiptName(name); toast.success('Receipt attached'); onUpdated(); }, onError: (msg) => setUploadError(msg) });
  }

  return (
    <div>
      <h3 className="detail-section-title">
        INVOICE TO AGENCY
        <PostedBadge visible={arJeExists} />
      </h3>
      <div className="form-row">
        <Field label="Invoice #">{(id) => (<>
          <input id={id} className="form-input" value={invoice?.invoice_number || ''} placeholder="Assigned automatically when saved" readOnly />
        </>)}</Field>
        <Field label={<>PO / Contract Ref <span style={{ color: 'var(--muted)', fontWeight: 400, textTransform: 'none', letterSpacing: 0, fontSize: 11 }}>optional</span></>}>{(id) => (<>
          <input id={id} className="form-input" value={form.po_number} maxLength={200} onChange={e => setForm(f => ({ ...f, po_number: e.target.value }))} placeholder="PO-1234 or SOW ref" />
        </>)}</Field>
      </div>
      <div className="form-row">
        <Field label="Invoice Date">{(id) => (<>
          <input id={id} className="form-input" type="date" min={DB_DATE_MIN} max={DB_DATE_MAX} value={form.invoice_date} {...v.fieldProps('invoice_date')} onChange={e => { setForm(f => ({ ...f, invoice_date: e.target.value })); v.clear('invoice_date'); }} />
          {v.errors.invoice_date && <div {...v.errorProps('invoice_date')}>{v.errors.invoice_date}</div>}
        </>)}</Field>
        <Field label="Due Date">{(id) => (<>
          <input id={id} className="form-input" type="date" min={form.invoice_date || DB_DATE_MIN} max={DB_DATE_MAX} value={form.due_date} {...v.fieldProps('due_date')} onChange={e => { setForm(f => ({ ...f, due_date: e.target.value })); v.clear('due_date'); }} />
          {v.errors.due_date && <div {...v.errorProps('due_date')}>{v.errors.due_date}</div>}
        </>)}</Field>
      </div>
      <div className="form-row">
        <Field label="Currency">{(id) => (<>
          {/* USD only, and it is the column that says so: invoices_currency_usd_only is a
              CHECK, so the other four this once offered could only ever end in a 23514,
              raised after the whole invoice had been filled in. */}
          <select id={id} className="form-select" value={form.currency} onChange={e => setForm(f => ({ ...f, currency: e.target.value }))}>
            {['USD'].map(c => <option key={c}>{c}</option>)}
          </select>
        </>)}</Field>
        <div className="form-group" />
      </div>
      <div className="form-row">
        {!inKind && (
          <Field label={<>Invoice Amount ($)<HelpIcon slug="wrong-invoice-amount" /></>}>{(id) => (<>
            <LockedField je={arJe} onReverse={setReverseFor} tooltip="Locked: reverse the AR entry to edit">
              <MoneyInput id={id} value={form.invoice_amount} {...v.fieldProps('invoice_amount')} onChange={e => { setForm(f => ({ ...f, invoice_amount: e.target.value })); v.clear('invoice_amount'); }} disabled={arJeExists} style={arJeExists ? { paddingRight: 38 } : undefined} />
            </LockedField>
            {v.errors.invoice_amount && <div {...v.errorProps('invoice_amount')}>{v.errors.invoice_amount}</div>}
          </>)}</Field>
        )}
        <Field label="Agency Payment Status">{(id) => (<>
          <select id={id} className="form-select" value={form.payment_status_id} onChange={e => setForm(f => ({ ...f, payment_status_id: e.target.value }))}>
            {agencyOptions.map(o => <option key={o.id} value={o.id}>{o.label}</option>)}
          </select>
        </>)}</Field>
        {inKind && <div className="form-group" />}
      </div>
      <Field label={<>Service Description <span style={{ color: 'var(--dim)', fontWeight: 400 }}>(appears on invoice: defaults to brand name)</span></>}>{(id) => (<>
        <input id={id} className="form-input" value={form.service_description} maxLength={500} onChange={e => setForm(f => ({ ...f, service_description: e.target.value }))} placeholder={`e.g. "${row.brand_name || 'Song Title'}" by Artist Name`} />
      </>)}</Field>
      <div className="form-row">
        <Field label="Agency Paid Date">{(id) => (<>
          <input id={id} className="form-input" type="date" min={form.invoice_date || DB_DATE_MIN} max={DB_DATE_MAX} value={form.payment_received_date} {...v.fieldProps('payment_received_date')} onChange={e => { setForm(f => ({ ...f, payment_received_date: e.target.value })); v.clear('payment_received_date'); }} />
          {v.errors.payment_received_date && <div {...v.errorProps('payment_received_date')}>{v.errors.payment_received_date}</div>}
        </>)}</Field>
        <Field label="Payment Method">{(id) => (<>
          {methodsError ? <ReadError error={methodsError} onRetry={loadMethods} /> : (
            <select id={id} className="form-select" value={form.payment_method} onChange={e => setForm(f => ({ ...f, payment_method: e.target.value }))}>
              <option value="">Select…</option>
              {paymentMethods.map(m => <option key={m}>{m}</option>)}
            </select>
          )}
        </>)}</Field>
      </div>
      <Field label={<>Invoice Notes <span style={{ color: 'var(--dim)', fontWeight: 400 }}>(footer of invoice)</span></>}>{(id) => (<>
        <textarea id={id} className="form-textarea" value={form.invoice_notes} maxLength={1000} onChange={e => setForm(f => ({ ...f, invoice_notes: e.target.value }))} style={{ minHeight: 52 }} placeholder="e.g. Payment due within 30 days of invoice date." />
      </>)}</Field>
      <Field label="Internal Notes">{(id) => (<>
        <textarea id={id} className="form-textarea" value={form.payment_notes} maxLength={1000} onChange={e => setForm(f => ({ ...f, payment_notes: e.target.value }))} style={{ minHeight: 52 }} />
      </>)}</Field>

      <div className="divider" />

      <div style={{ marginBottom: 16, padding: '10px 14px', background: inKind ? 'color-mix(in oklab, var(--purple) 8%, transparent)' : 'var(--surface)', border: `1px solid ${inKind ? 'var(--purple)' : 'var(--border)'}`, borderRadius: 6 }}>
        <label className="checkbox-row" style={{ fontWeight: 600, fontSize: 13 }}>
          <input type="checkbox" checked={form.is_in_kind} onChange={e => {
            const checked = e.target.checked;
            setForm(f => {
              // Keep the status valid for the new mode: Paid/Overdue have no in-kind
              // option, and "In Kind" has no cash option, so remap when crossing.
              const cur = paymentOpts.find(o => o.id === f.payment_status_id);
              let statusId = f.payment_status_id;
              if (checked && cur && (cur.value === 'Paid' || cur.value === 'Overdue')) {
                statusId = paymentOpts.find(o => o.value === 'In Kind')?.id || statusId;
              } else if (!checked && cur && cur.value === 'In Kind') {
                statusId = paymentOpts.find(o => o.value === 'Pending')?.id || statusId;
              }
              return { ...f, is_in_kind: checked, you_received: false, payment_status_id: statusId };
            });
          }} disabled={arJeExists} />
          In-Kind Compensation (no cash)
          <HelpIcon slug="in-kind" />
          <CheckboxLock je={arJe} onReverse={setReverseFor} tooltip="Locked: reverse the AR entry to change in-kind status" />
        </label>
        {inKind && (
          <div style={{ marginTop: 12 }}>
            <div className="form-row">
              <Field label={<>Fair Market Value ($)<HelpIcon slug="in-kind" /></>}>{(id) => (<>
                <LockedField je={arJe} onReverse={setReverseFor} tooltip="Locked: reverse the in-kind entry to edit">
                  <MoneyInput id={id} value={form.in_kind_value} {...v.fieldProps('in_kind_value')} onChange={e => { setForm(f => ({ ...f, in_kind_value: e.target.value })); v.clear('in_kind_value'); }} placeholder="0.00" disabled={arJeExists} style={arJeExists ? { paddingRight: 38 } : undefined} />
                </LockedField>
                {v.errors.in_kind_value && <div {...v.errorProps('in_kind_value')}>{v.errors.in_kind_value}</div>}
              </>)}</Field>
              <div className="form-group" />
            </div>
            <Field label={<>Description <span style={{ color: 'var(--dim)', fontWeight: 400 }}>(what was received)</span></>}>{(id) => (<>
              <textarea id={id} className="form-textarea" value={form.in_kind_description} maxLength={500} onChange={e => setForm(f => ({ ...f, in_kind_description: e.target.value }))} placeholder="e.g. 4x concert tickets, MSRP $75 each" style={{ minHeight: 64 }} />
            </>)}</Field>
          </div>
        )}
      </div>

      {inKind ? (
        <div style={{ padding: '12px 14px', borderRadius: 6, marginBottom: 4, fontSize: 12, background: 'rgba(255,255,255,0.04)', border: '1px solid var(--border)', color: 'var(--muted)', lineHeight: 1.6 }}>
          <div style={{ fontWeight: 600, color: 'var(--white)', marginBottom: 4, fontSize: 11, letterSpacing: 1, textTransform: 'uppercase' }}>In-Kind Compensation</div>
          Fair value tracked for tax purposes only. No cash changes hands, so there is nothing to mark as received and no payout to the creator.
        </div>
      ) : (
        <>
          <h3 className="detail-section-title">
            RECEIVED BY YOU
            <PostedBadge visible={cashJeExists} />
          </h3>
          <div className="form-group">
            <label className="checkbox-row">
              <input type="checkbox" checked={form.you_received} onChange={e => setForm(f => ({ ...f, you_received: e.target.checked }))} disabled={cashJeExists} />
              Money has cleared my account
              <HelpIcon slug="invoice-receive" />
              <CheckboxLock je={cashJe} onReverse={setReverseFor} tooltip="Locked. Reverse the cash-receipt entry to edit" />
            </label>
          </div>
          {form.you_received && (
            <>
              <div className="form-row">
                <Field label="Date Cleared">{(id) => (<>
                  <LockedField je={cashJe} onReverse={setReverseFor} tooltip="Locked. Reverse the cash-receipt entry to edit">
                    <input id={id} className="form-input" type="date" min={form.payment_received_date || DB_DATE_MIN} max={today} value={form.you_received_date} {...v.fieldProps('you_received_date')} onChange={e => { setForm(f => ({ ...f, you_received_date: e.target.value })); v.clear('you_received_date'); }} disabled={cashJeExists} style={cashJeExists ? { paddingRight: 38 } : undefined} />
                  </LockedField>
                  {v.errors.you_received_date && <div {...v.errorProps('you_received_date')}>{v.errors.you_received_date}</div>}
                </>)}</Field>
                <Field label={<>Net Received ($)<HelpIcon slug="invoice-receive" /></>}>{(id) => (<>
                  <LockedField je={cashJe} onReverse={setReverseFor} tooltip="Locked. Reverse the cash-receipt entry to edit">
                    <MoneyInput id={id} value={form.net_received} {...v.fieldProps('net_received')} onChange={e => { setForm(f => ({ ...f, net_received: e.target.value })); v.clear('net_received'); }} placeholder={form.invoice_amount !== '' ? parseFloat(form.invoice_amount).toFixed(2) : '0.00'} disabled={cashJeExists} style={cashJeExists ? { paddingRight: 38 } : undefined} />
                  </LockedField>
                  {v.errors.net_received && <div {...v.errorProps('net_received')}>{v.errors.net_received}</div>}
                </>)}</Field>
              </div>
              <div className="form-row">
                <Field label={<>Discount / Write-off ($)<HelpIcon slug="invoice-receive" /></>}>{(id) => (<>
                  <LockedField je={cashJe} onReverse={setReverseFor} tooltip="Locked. Reverse the cash-receipt entry to edit">
                    <MoneyInput id={id} value={form.discount_amount} {...v.fieldProps('discount_amount')} onChange={e => { setForm(f => ({ ...f, discount_amount: e.target.value })); v.clear('discount_amount'); }} placeholder="0.00" disabled={cashJeExists} style={cashJeExists ? { paddingRight: 38 } : undefined} />
                  </LockedField>
                  {v.errors.discount_amount && <div {...v.errorProps('discount_amount')}>{v.errors.discount_amount}</div>}
                </>)}</Field>
                <div className="form-group">
                  <div className="form-label">Processing Fee (calculated)</div>
                  <div className="form-input" style={{ background: 'var(--surface)', color: 'var(--muted)', cursor: 'default' }}>
                    {form.net_received !== '' && form.invoice_amount !== ''
                      ? fmtMoney(computeProcessingFee(form.invoice_amount, form.net_received, form.discount_amount))
                      : '—'}
                  </div>
                </div>
              </div>
              <Field label="Notes">{(id) => (<>
                <input id={id} className="form-input" value={form.you_received_notes} onChange={e => setForm(f => ({ ...f, you_received_notes: e.target.value }))} placeholder="e.g. PayPal deducted $12 fee" />
              </>)}</Field>
            </>
          )}
        </>
      )}

      {formError && <Feedback value={formError} style={{ marginBottom: 12 }} />}
      <SubmitButton
        saving={saving || generatingPdf}
        savingLabel={generatingPdf ? 'Saving + generating PDF…' : 'Saving…'}
        className="btn btn-primary w-full mt-12"
        onClick={save}
        style={{ justifyContent: 'center' }}
      >Save Invoice</SubmitButton>

      <PostedEntries jes={invoiceJes} title="Posted ledger entries for this invoice" onReverse={(je) => setReverseFor(je)} />

      {reverseFor ? (
        <ReverseEntryModal
          journalEntry={reverseFor.entry}
          lines={reverseFor.lines}
          onClose={() => setReverseFor(null)}
          onReversed={() => { setReverseFor(null); onUpdated(); }}
        />
      ) : null}

      {/* The same block as the reward invoice form, which is why it is a component: the two
          were copies and the reward copy had lost the download button. */}
      <ReceiptUpload
        invoiceId={invoice?.id}
        path={receiptPath}
        name={receiptName}
        uploading={uploading}
        error={uploadError}
        readError={receiptError}
        onRetryRead={loadReceipt}
        onSelect={uploadReceipt}
        onError={setUploadError}
        onRemoved={() => { setReceiptPath(null); setReceiptName(null); }}
      />
    </div>
  );
}

