/**
 * components/shared/AgencySelect.js: searchable single-select agency filter.
 *
 * A combobox: a chip that opens a listbox with a type-to-filter box above it. `options` is a
 * `string[]` of agency names and `onChange('')` means "all agencies". Used on the Campaigns
 * filter row and on both the desktop and mobile Payments filter rows.
 *
 * @gotcha the chip is TWO buttons sharing one outline, never one button with a control inside
 *         it: nested interactive content is invalid markup and Tab skips it, which leaves the
 *         clear reachable by nothing but a pointer. Neither half draws a border; `.agency-chip`
 *         draws the one they share.
 * @gotcha FOCUS STAYS IN THE SEARCH BOX. The arrows move `aria-activedescendant` through the
 *         list rather than moving DOM focus onto each option, because focusing an option takes
 *         the keyboard out of the box the user is typing in, which is what the box is for.
 * @gotcha the outside-click listener is `mousedown`, not `click`. A `click` fires after the
 *         option's own handler has already closed the list, and the panel is gone by then.
 * @see hub-src/src/components/shared/__tests__/AgencySelect.test.js
 */
import React, { useState, useEffect, useRef, useId, useMemo } from 'react';

/** The `All agencies` row is the first option and clears the filter; `''` is its value. */
const ALL = '';

export default function AgencySelect({ value, onChange, options }) {
  const [open, setOpen]     = useState(false);
  const [search, setSearch] = useState('');
  const [active, setActive] = useState(0);
  const ref        = useRef(null);
  const inputRef   = useRef(null);
  const triggerRef = useRef(null);
  const listId = useId();

  const rows = useMemo(
    () => [ALL, ...options.filter((o) => o.toLowerCase().includes(search.toLowerCase()))],
    [options, search],
  );

  useEffect(() => {
    if (!open) return undefined;
    const close = (e) => { if (ref.current && !ref.current.contains(e.target)) setOpen(false); };
    document.addEventListener('mousedown', close);
    return () => document.removeEventListener('mousedown', close);
  }, [open]);

  useEffect(() => {
    if (open) inputRef.current?.focus();
    else setSearch('');
  }, [open]);

  // Typing narrows the list, so an index into the old list points at the wrong row or past
  // the end. The first row is always `All agencies`, so 0 is always safe.
  useEffect(() => { setActive(0); }, [search]);

  /**
   * Open on whatever is already chosen, so the first arrow press moves from there.
   *
   * Here and not in an effect on `open`: the highlight depends on `rows`, and `rows` changes
   * on every keystroke in the search box, so an effect that honestly depended on it would drag
   * the highlight back to the selection mid-search.
   */
  function openList() {
    const at = rows.indexOf(value);
    setActive(at >= 0 ? at : 0);
    setOpen(true);
  }

  function commit(next) {
    onChange(next);
    setOpen(false);
    triggerRef.current?.focus();
  }

  function onSearchKey(e) {
    if (e.key === 'Escape') { setOpen(false); triggerRef.current?.focus(); return; }
    if (e.key === 'Enter')  { e.preventDefault(); commit(rows[active] ?? ALL); return; }
    if (e.key === 'ArrowDown') { e.preventDefault(); setActive((i) => Math.min(i + 1, rows.length - 1)); return; }
    if (e.key === 'ArrowUp')   { e.preventDefault(); setActive((i) => Math.max(i - 1, 0)); return; }
    if (e.key === 'Home')      { e.preventDefault(); setActive(0); return; }
    if (e.key === 'End')       { e.preventDefault(); setActive(rows.length - 1); }
  }

  const optionId = (i) => `${listId}-opt-${i}`;
  const label = (row) => (row === ALL ? 'All agencies' : row);

  return (
    <div ref={ref} className="agency-select">
      <span className={`agency-chip ${value ? 'is-active' : ''}`}>
        <button
          type="button"
          ref={triggerRef}
          className="agency-chip-trigger"
          role="combobox"
          aria-expanded={open}
          aria-haspopup="listbox"
          aria-controls={open ? listId : undefined}
          aria-label={value ? `Agency filter: ${value}` : 'Filter by agency'}
          onClick={() => (open ? setOpen(false) : openList())}
        >
          {value || 'Agency'}
        </button>
        {value && (
          <button
            type="button"
            className="agency-chip-clear"
            aria-label="Clear agency filter"
            onClick={() => commit(ALL)}
          >✕</button>
        )}
      </span>

      {open && (
        <div className="agency-panel">
          <div className="agency-panel-search">
            <input
              ref={inputRef}
              className="form-input"
              aria-label="Search agencies"
              placeholder="Search agencies…"
              value={search}
              role="searchbox"
              aria-controls={listId}
              aria-activedescendant={rows.length ? optionId(active) : undefined}
              onChange={(e) => setSearch(e.target.value)}
              onKeyDown={onSearchKey}
            />
          </div>
          <ul className="agency-panel-list" id={listId} role="listbox" aria-label="Agencies">
            {rows.map((row, i) => (
              <li
                key={row || '__all'}
                id={optionId(i)}
                role="option"
                aria-selected={row === value}
                className={`agency-option${i === active ? ' is-active' : ''}${row === value ? ' is-selected' : ''}`}
                // A pointer path beside the keyboard one. `onMouseDown` rather than `onClick`
                // so the panel's own outside-click listener never sees the press.
                onMouseDown={(e) => { e.preventDefault(); commit(row); }}
                onMouseEnter={() => setActive(i)}
              >{label(row)}</li>
            ))}
            {rows.length === 1 && search && (
              <li className="agency-option is-empty" role="presentation">No match</li>
            )}
          </ul>
        </div>
      )}
    </div>
  );
}
