/**
 * components/shared/ExpensesPage.js. Admin + creator expenses view.
 *
 * Lists one-time and recurring expenses with coverage tracking, the recurring
 * period grid, OOP recording (Patterns P/Q via OopPaymentModal), receipts, and
 * recurring price history. Coverage = payout-split allocations (Pattern G) plus
 * live OOP entries. Same component for admin (all owners, full edit) and a
 * creator (own expenses only, read-mostly); the `isAdmin` prop gates writes and
 * the data fetch scopes to `profileId` for creators.
 *
 * @gotcha recurring expense amount is managed ONLY through expense_price_history
 *         (the edit form states the amount as text and points to Price History);
 *         never write expenses.amount directly for recurring. @see getEffectiveAmount
 * @gotcha only live JEs count toward coverage: oopMap is built filtering out
 *         entries whose JE is reversed or unposted (see fetchAll).
 * @gotcha the one-time list is split by STATE, not sorted: outstanding rows render in full
 *         and settled rows fold into a compressed pile, so `isExpenseFullyCovered` decides
 *         what the page opens on. A change to the coverage math moves rows between the two.
 *         The name search reaches into the closed pile on purpose. @see expenseSettledSplit
 * @see docs/MONEY.md Patterns G, P, Q; utils/expenses.js (coverage math)
 */
import React, { useState, useEffect, useMemo, useRef } from 'react';
import { supabase } from '../../lib/supabase';
import { ReceiptIcon, AttachIcon } from './Icon';
import { fmtMoney, fmtDate, fmtPct } from '../../utils/format';
import { viewStoredFile, downloadStoredFile, RECEIPT_FILE_ACCEPT, RECEIPT_FILE_HINT } from '../../utils/storage';
import { uploadExpenseReceipt } from '../../utils/receipt';
import { useCreators } from '../../hooks/useCreators';
import { useLoadState } from '../../hooks/useLoadState';
import Refreshing from './Refreshing';
import AttachmentRow from './AttachmentRow';
import { useStatusOptions } from '../../contexts/StatusOptionsContext';
import HelpIcon from './HelpIcon';
import {
  parseLocalDate, toMonthlyAmount, getOccurrencesInRange,
  expenseCoverageStatus, getEffectiveAmount, EXPENSE_FREQUENCIES, DAYS_OF_WEEK,
} from '../../utils/expenses';
import Feedback from './Feedback';
import ReadError from './ReadError';
import EmptyState from './EmptyState';
import { humanizeError } from '../../utils/errors';
import { useConfirm } from './ConfirmDialog';
import OopPaymentModal from './OopPaymentModal';
import ReverseEntryModal from './ReverseEntryModal';
import { DB_DATE_MAX, DB_DATE_MIN } from '../../utils/dbLimits';
import { mutate } from '../../utils/mutate';
import { useToast } from './Toast';
import Modal from './Modal';
import Field from './Field';
import { useUnsavedGuard } from '../../hooks/useUnsavedGuard';
import Loading from './Loading';
import SubmitButton from './SubmitButton';
import MoneyInput from './MoneyInput';

const FREQ_LABELS = { weekly: 'Weekly', monthly: 'Monthly', quarterly: 'Quarterly', annual: 'Annual' };
const PERIOD_MONTHS = 3; // lookahead/lookback for recurring detail

/** 'YYYY-MM' -> 'Mon YYYY' (e.g. '2026-03' -> 'Mar 2026'). */
function fmtPeriod(ym) {
  if (!ym) return '';
  const [y, m] = ym.split('-').map(Number);
  return new Date(y, m - 1, 1).toLocaleDateString('en-US', { month: 'short', year: 'numeric' });
}

const BLANK_FORM = {
  name: '', category_id: '', amount: '', type: 'one_time',
  frequency: 'monthly', recurrence_day_of_week: '1', recurrence_day_of_month: '1',
  start_date: '', end_date: '', creator_id: '', notes: '',
};

/**
 * @param {object} props
 * @param {boolean} props.isAdmin - gates every write + the owner filter; false scopes to one creator
 * @param {string} props.profileId - the signed-in profile; for creators it filters the expense fetch
 */
/**
 * Who a payment was split between, hanging off the record it belongs to.
 *
 * A statement, never a control. A recharge is recovered when the payroll month carves it into
 * a payout and a partner's share is never repaid at all, so there is nothing here to press.
 *
 * @param {Array} props.shares - `shareMap[paymentId]`, already in a stable order, each row
 *        carrying the words for its own settlement. @see fetchAll
 * @param {boolean} [props.indented] - align under the period column, as the receipt strip does.
 * @gotcha a CREATOR paid record gets no list, and that is not an omission: she is the whole
 *         payment and the row already names her, and a reimbursement nets against her
 *         out-of-pocket BALANCE rather than settling one payment, so no row here could say
 *         whether this one has come back. @see docs/MONEY.md Pattern P
 * @gotcha "not recovered yet" is deliberately not an alarm colour. Every share of a bill paid
 *         this month reads that way until payroll runs, so orange here would cry wolf monthly.
 *         The period chips above carry the coverage colours.
 */
function PaymentShares({ shares, indented }) {
  if (!shares?.length) return null;
  return (
    <ul className={`oop-recharge${indented ? ' is-indented' : ''}`}>
      {shares.map((s) => (
        <li key={s.id}>
          <span className="oop-recharge-who">{s.name} · {fmtPct(s.pct)}</span>
          <span className="oop-recharge-amount">{fmtMoney(s.amount)}</span>
          <span className="oop-recharge-state" data-tone={s.tone}>{s.state}</span>
        </li>
      ))}
    </ul>
  );
}

export default function ExpensesPage({ isAdmin, profileId, pendingExpenseId, onConsumed }) {
  const { dirtyProps } = useUnsavedGuard();
  const toast = useToast();
  const askConfirm = useConfirm();
  const [expenses,      setExpenses]      = useState([]);
  const [allocations,   setAllocations]   = useState([]);
  const [priceHistory,  setPriceHistory]  = useState({}); // expense_id → [entries asc by effective_date]
  // A save refetches this page, and one flag blanked the table it was saved from.
  // @see hooks/useLoadState.js
  const { loading, refreshing, begin, end } = useLoadState();
  const [loadErr,       setLoadErr]       = useState(null);
  const [selected,      setSelected]      = useState(null);
  const [modal,         setModal]         = useState(null); // null | 'add' | expense_obj
  const [saving,        setSaving]        = useState(false);
  const [formError,     setFormError]     = useState('');
  const [form,          setForm]          = useState(BLANK_FORM);
  const [priceModal,    setPriceModal]    = useState(null); // null | expense_obj
  const [priceForm,     setPriceForm]     = useState({ amount: '', effective_date: '', notes: '' });
  const [priceSaving,   setPriceSaving]   = useState(false);
  const [priceFormError,setPriceFormError]= useState('');
  const [receiptsMap,      setReceiptsMap]      = useState({}); // expense_id → { 'one-time'|'YYYY-MM': [rows] }
  const [oopMap,           setOopMap]           = useState({}); // expense_id → { 'one-time'|'YYYY-MM': [{ amount, payerType, payerName }] }
  // oop_payment_id → who a payment was split between, whatever kind it is. Admin only: RLS
  // shows a creator her OWN allocation and no other, so she would read half a split as all of
  // it, and the partner half comes off ledger lines she cannot see at all.
  const [shareMap,         setShareMap]         = useState({});
  const [oopModalFor,      setOopModalFor]      = useState(null); // { expense, period }
  const [reverseFor,       setReverseFor]       = useState(null); // journalEntry to reverse
  const [gridSelection,    setGridSelection]    = useState(new Set()); // periodKeys
  const [gridAnchor,       setGridAnchor]       = useState(null);      // periodKey for shift-range
  const [receiptUploading, setReceiptUploading] = useState(false);
  const [receiptError,     setReceiptError]     = useState('');
  const oneTimeInputRef = useRef(null);
  // One input per period, keyed: a single ref shared by a mapped input is the LAST one rendered,
  // so every period's attach button would open the same picker.
  const periodInputs = useRef({});
  const [creatorFilter,  setCreatorFilter]  = useState('all');
  const [typeFilter,     setTypeFilter]     = useState('all');
  // Name is one of the two things a reader remembers about a past expense; the other is its
  // owner, which already has its own chips. Nothing here searches amount or date.
  const [search,         setSearch]         = useState('');
  // The settled pile arrives closed, because the page's job is what still needs paying.
  // Session state on purpose: a reload is how you ask for the default view back.
  const [settledOpen,    setSettledOpen]    = useState(false);
  // Filtered to nothing reads exactly like nothing recorded, and the copy then invites an
  // admin to add an expense that is already there.
  const expenseFiltersDirty = creatorFilter !== 'all' || typeFilter !== 'all' || search.trim() !== '';
  function clearExpenseFilters() { setCreatorFilter('all'); setTypeFilter('all'); setSearch(''); }

  const { creators } = useCreators(isAdmin);
  // The 6xxx accounts fill ONE control, so their read failure reports inside the form that
  // uses the Category picker rather than blanking the page. The context held this error and
  // nothing read it, so an empty picker read as "no expense category exists".
  // @see .claude/rules/hub-ui.md (the four data states)
  const { expenseAccounts, expenseAccountsError, refresh: refreshStatusOptions } = useStatusOptions();
  // Unfiltered list, used for label lookups so inactive accounts still resolve.
  const expenseCategories = useMemo(() => expenseAccounts || [], [expenseAccounts]);
  // Picker shows active categories plus the currently-selected one if inactive.
  const pickerCategories = useMemo(() => {
    const active = expenseCategories.filter((c) => c.is_active !== false);
    if (form.category_id && !active.some((c) => c.id === form.category_id)) {
      const cur = expenseCategories.find((c) => c.id === form.category_id);
      if (cur) return [cur, ...active];
    }
    return active;
  }, [expenseCategories, form.category_id]);

  // Default category_id to the first active category when opening the modal
  useEffect(() => {
    if (!modal || form.category_id) return;
    const first = (expenseCategories || []).find((c) => c.is_active !== false);
    if (first) setForm(f => ({ ...f, category_id: f.category_id || first.id }));
  }, [modal, expenseCategories, form.category_id]);

  useEffect(() => { fetchAll(); }, []);

  // Deep-link target: open an expense's panel when a ledger/reconciliation line
  // navigated here. expenses is the full list, so the panel opens even if the
  // row is filtered out of the current view.
  useEffect(() => {
    if (!pendingExpenseId || expenses.length === 0) return;
    const target = expenses.find((e) => e.id === pendingExpenseId);
    if (target) setSelected(target);
    if (onConsumed) onConsumed();
  }, [pendingExpenseId, expenses]);

  // Clear transient detail-panel state when switching to a different expense
  useEffect(() => {
    setReceiptError('');
    setGridSelection(new Set());
    setGridAnchor(null);
  }, [selected?.id]);

  /**
   * Load expenses + their allocations, price history, receipts, and OOP
   * payments into the page's lookup maps. Creators are scoped to their own
   * expenses; admins see all.
   * @gotcha oopMap only keeps live entries (posted, non-reversed) so coverage
   *         never counts a reversed OOP payment.
   */
  async function fetchAll() {
    begin();
    // Cleared per attempt: the error replaces the whole page and offers no retry, so
    // the only re-entry is a parent re-render, which a stale flag would blank.
    setLoadErr(null);
    let q = supabase
      .from('expenses')
      .select('*, creator:profiles!expenses_creator_id_fkey(id, creator_name, full_name)')
      .order('created_at', { ascending: false });
    if (!isAdmin) q = q.eq('creator_id', profileId);

    const { data: expData, error: expErr } = await q;
    // Expenses, their allocations, price history, receipts and out-of-pocket
    // payments: an empty list on any of them reads as "nothing recorded".
    if (expErr) { setLoadErr(humanizeError(expErr)); end(); return; }
    const { data: allocData, error: allocDataErr } = await supabase
      .from('payout_splits')
      .select('id, expense_id, expense_period, amount, payout:creator_payouts(payout_date, campaign:campaigns(campaign_name, brand_name))')
      .not('expense_id', 'is', null);
    const { data: histData, error: histDataErr } = await supabase
      .from('expense_price_history')
      .select('id, expense_id, amount, effective_date, notes, created_at')
      .order('effective_date', { ascending: true });

    const { data: receiptData, error: receiptDataErr } = await supabase
      .from('expense_receipts')
      .select('id, expense_id, period_key, file_path, file_name, uploaded_by, created_at')
      .order('created_at', { ascending: true });

    const { data: oopData, error: oopDataErr } = await supabase
      .from('expense_oop_payments')
      .select('id, expense_id, period_key, amount, paid_at, notes, payer_type, payer_creator_id, journal_entry_id, payer:profiles!expense_oop_payments_payer_creator_id_fkey(creator_name, full_name), ledger_journal_entries:journal_entry_id(id, entry_date, description, reference, source_type, reversed_by_je_id, is_posted)')
      .order('paid_at', { ascending: true });
    // Who a company-paid cost is recovered from, and whether it has been. Skipped entirely for
    // a creator, whose RLS answer is her own row alone.
    const { data: rechargeData, error: rechargeDataErr } = isAdmin
      ? await supabase
        .from('expense_recharge_allocations')
        .select('id, oop_payment_id, pct, amount, '
              + 'party:profiles!expense_recharge_allocations_party_id_fkey(creator_name, full_name), '
              + 'splits:payout_splits(id, payout:creator_payouts(payout_date))')
      : { data: [], error: null };

    // A partner payment splits too, but into EQUITY rather than into a recoverable allocation,
    // so its shares are only on the journal entry. Read there rather than recomputing from
    // `partner_allocation_pct`, which is today's split and not the one that was booked.
    const partnerJes = (oopData || [])
      .filter((o) => o.payer_type === 'partners' && o.journal_entry_id
                  && o.ledger_journal_entries?.is_posted === true
                  && o.ledger_journal_entries?.reversed_by_je_id == null)
      .map((o) => o.journal_entry_id);
    const { data: equityData, error: equityDataErr } = (isAdmin && partnerJes.length)
      ? await supabase
        .from('ledger_entry_lines')
        .select('id, journal_entry_id, credit, '
              + 'account:ledger_accounts(source_type, profile:profiles(creator_name, full_name))')
        .in('journal_entry_id', partnerJes)
      : { data: [], error: null };

    const anyErr = allocDataErr || histDataErr || receiptDataErr || oopDataErr
                || rechargeDataErr || equityDataErr;
    if (anyErr) { setLoadErr(humanizeError(anyErr)); end(); return; }

    // Build map: expense_id → entries sorted ascending by effective_date
    const histMap = {};
    (histData || []).forEach(row => {
      if (!histMap[row.expense_id]) histMap[row.expense_id] = [];
      histMap[row.expense_id].push(row);
    });

    const rMap = {};
    (receiptData || []).forEach(r => {
      if (!rMap[r.expense_id]) rMap[r.expense_id] = {};
      const key = r.period_key ?? 'one-time';
      if (!rMap[r.expense_id][key]) rMap[r.expense_id][key] = [];
      rMap[r.expense_id][key].push(r);
    });

    // Map: expense_id → { 'one-time'|'YYYY-MM' → [{ amount, payerType, payerName }] }
    // Only live (posted, non-reversed) entries contribute.
    const oMap = {};
    (oopData || []).forEach(o => {
      const je = o.ledger_journal_entries;
      if (!je || je.reversed_by_je_id != null || je.is_posted !== true) return;
      if (!oMap[o.expense_id]) oMap[o.expense_id] = {};
      const key = o.period_key ?? 'one-time';
      if (!oMap[o.expense_id][key]) oMap[o.expense_id][key] = [];
      const payerName = o.payer_type === 'partners'
        ? 'Partners'
        : o.payer_type === 'company'
        ? 'Company'
        : (o.payer?.creator_name || o.payer?.full_name || 'Creator');
      oMap[o.expense_id][key].push({
        id: o.id,
        amount: parseFloat(o.amount) || 0,
        payerType: o.payer_type,
        payerName,
        paid_at: o.paid_at,
        journalEntry: je,
        hasReceipt: false, // wired up later if needed
      });
    });

    // The state text is the whole point of the third column: the three payer kinds split the
    // same way and settle in three different ways, and only this says which.
    const shares = {};
    const push = (paymentId, row) => {
      if (!shares[paymentId]) shares[paymentId] = [];
      shares[paymentId].push(row);
    };

    // A recharge is recovered the moment a payout split references it: it moves no cash, so
    // there is no later clearing to wait for and `cleared_date` stays null on it forever.
    (rechargeData || []).forEach((a) => {
      const settled = (a.splits || [])[0];
      const on = settled?.payout?.payout_date;
      push(a.oop_payment_id, {
        id: a.id,
        name: a.party?.creator_name || a.party?.full_name || 'Unknown',
        pct: parseFloat(a.pct) || 0,
        amount: parseFloat(a.amount) || 0,
        kind: 'owes',
        tone: settled ? 'settled' : 'open',
        state: settled ? (on ? `recovered ${fmtDate(on)}` : 'recovered') : 'not recovered yet',
      });
    });

    // Partner shares carry no percentage of their own, so it comes off the booked amounts. A
    // rounding cent lands on the last partner, and 50.1% is what that entry actually says.
    const paidBy = new Map((oopData || []).map((o) => [o.journal_entry_id, parseFloat(o.amount) || 0]));
    const jeToPayment = new Map((oopData || []).map((o) => [o.journal_entry_id, o.id]));
    (equityData || []).forEach((l) => {
      const credit = parseFloat(l.credit) || 0;
      if (l.account?.source_type !== 'partner' || credit <= 0) return;
      const bill = paidBy.get(l.journal_entry_id) || 0;
      push(jeToPayment.get(l.journal_entry_id), {
        id: l.id,
        name: l.account.profile?.full_name || l.account.profile?.creator_name || 'Partner',
        pct: bill > 0 ? (credit / bill) * 100 : 0,
        amount: credit,
        kind: 'funded',
        tone: 'settled',
        state: 'capital, not repaid',
      });
    });

    // Who FUNDED it first, then who owes a share of it: one partner-paid payment can now carry
    // both, and that is the order the transaction reads in. Then by name, so a party keeps her
    // line between two months whose percentages differ.
    const kindOrder = { funded: 0, owes: 1 };
    Object.values(shares).forEach((list) => list.sort(
      (x, y) => kindOrder[x.kind] - kindOrder[y.kind] || x.name.localeCompare(y.name)
    ));

    setExpenses(expData || []);
    setAllocations(allocData || []);
    setShareMap(shares);
    setPriceHistory(histMap);
    setReceiptsMap(rMap);
    setOopMap(oMap);
    end();
  }

  /**
   * Coverage map: expense_id -> { total (one_time), 'YYYY-MM' (recurring) }.
   * Sums payout-split allocations (Pattern G) + live OOP entries (Patterns P/Q).
   * @see docs/MONEY.md Patterns G, P, Q
   */
  const coverageMap = useMemo(() => {
    const map = {};
    const bump = (expenseId, key, amount) => {
      if (!expenseId) return;
      if (!map[expenseId]) map[expenseId] = {};
      map[expenseId][key] = (map[expenseId][key] || 0) + amount;
    };

    allocations.forEach((a) => {
      if (!a.expense_id) return;
      const key = a.expense_period ? a.expense_period.substring(0, 7) : 'total';
      bump(a.expense_id, key, parseFloat(a.amount) || 0);
    });

    Object.entries(oopMap).forEach(([expenseId, byPeriod]) => {
      Object.entries(byPeriod).forEach(([periodKey, rows]) => {
        const key = periodKey === 'one-time' ? 'total' : periodKey;
        const sum = rows.reduce((s, r) => s + (parseFloat(r.amount) || 0), 0);
        bump(expenseId, key, sum);
      });
    });

    return map;
  }, [allocations, oopMap]);

  function getOnTimeCoverage(expense) {
    const covered = coverageMap[expense.id]?.total || 0;
    const total = parseFloat(expense.amount);
    return { covered, total, status: expenseCoverageStatus(covered, total) };
  }

  /**
   * Whether an expense reads as fully covered. This is what splits the one-time list into
   * the outstanding rows and the settled pile, so it decides what the page opens on.
   * One-time: status === 'covered'. Recurring: every NON-future period from
   * start_date through the current month meets its effective amount.
   */
  function isExpenseFullyCovered(e) {
    if (e.type === 'one_time') {
      const total = parseFloat(e.amount);
      const covered = coverageMap[e.id]?.total || 0;
      return expenseCoverageStatus(covered, total) === 'covered';
    }
    const start = parseLocalDate(e.start_date);
    if (!start) return false;
    const today = new Date();
    const endOfThisMonth = new Date(today.getFullYear(), today.getMonth() + 1, 0);
    const occs = getOccurrencesInRange(e, start, endOfThisMonth);
    if (occs.length === 0) return false;
    for (const occ of occs) {
      if (occ.isFuture) continue;
      const covered = coverageMap[e.id]?.[occ.periodKey] || 0;
      const total = getEffectiveAmount(priceHistory[e.id], occ.date) ?? parseFloat(e.amount);
      if (expenseCoverageStatus(covered, total) !== 'covered') return false;
    }
    return true;
  }

  const searchTerm = search.trim().toLowerCase();

  const filteredExpenses = useMemo(() => expenses.filter(e => {
    if (typeFilter !== 'all' && e.type !== typeFilter) return false;
    if (isAdmin && creatorFilter === 'business' && e.creator_id !== null) return false;
    if (isAdmin && creatorFilter !== 'all' && creatorFilter !== 'business' && e.creator_id !== creatorFilter) return false;
    if (searchTerm && !(e.name || '').toLowerCase().includes(searchTerm)) return false;
    return true;
  }), [expenses, typeFilter, creatorFilter, searchTerm, isAdmin]);

  const oneTimeSorted = filteredExpenses.filter(e => e.type === 'one_time');
  // The one-time list splits by STATE, not by date. Everything unsettled is the working set
  // and keeps its full row; everything covered is finished business that only has to stay
  // findable, so it folds away. Page height then tracks what is OPEN, not what has ever
  // been bought, which is the growth this page was losing to.
  const oneTimeOutstanding = oneTimeSorted.filter(e => !isExpenseFullyCovered(e));
  const oneTimeSettled     = oneTimeSorted.filter(e =>  isExpenseFullyCovered(e));
  const settledTotal = oneTimeSettled.reduce((s, e) => s + parseFloat(e.amount), 0);
  // A narrowed view opens the pile itself: a search whose only hit is settled would
  // otherwise answer with an empty page while holding the row the reader asked for.
  const settledExpanded = settledOpen || expenseFiltersDirty;

  /** Category and owner, the pair an OUTSTANDING row carries. Creators see no owner. */
  function rowMeta(e) {
    const categoryName = expenseCategories.find(c => c.id === e.category_id)?.name || '';
    return (
      <>
        {categoryName ? <span>{categoryName}</span> : null}
        {categoryName && isAdmin ? <span style={{ color: 'var(--dim)' }}>·</span> : null}
        {isAdmin ? <span>{e.creator_id ? (e.creator?.creator_name || e.creator?.full_name || 'Creator') : 'Business'}</span> : null}
      </>
    );
  }

  /** Enter and Space open the detail panel, since the row is a div playing button. */
  function rowKeyDown(e, isSelected) {
    return (ev) => {
      if (ev.key === 'Enter' || ev.key === ' ') {
        ev.preventDefault();
        setSelected(isSelected ? null : e);
      }
    };
  }

  /**
   * An outstanding one-time row: the full anatomy, because every part of it is a reason the
   * row is still here. Coverage bar, amount, date, owner, who paid out of pocket so far, and
   * the one action that settles it.
   */
  function renderOneTimeRow(e) {
    const { covered, total, status } = getOnTimeCoverage(e);
    const records = oopMap[e.id]?.['one-time'] || [];
    const liveRecords = records.filter(r => !r.journalEntry?.reversed_by_je_id);
    const isSelected = selected?.id === e.id;
    const rawPct = total > 0 ? (covered / total) * 100 : 0;
    const pct = Math.min(999, Math.round(rawPct));
    const fillWidth = Math.min(100, pct);
    const coverageColor =
      status === 'overpaid' ? 'var(--red)' :
      status === 'covered'  ? 'color-mix(in oklab, var(--green) 75%, var(--surface))' :
      status === 'partial'  ? 'color-mix(in oklab, var(--orange) 80%, var(--surface))' :
                              'var(--dim)';
    const showActionButton = isAdmin && liveRecords.length === 0 && (status === 'unpaid' || status === 'partial');
    return (
      <div
        key={e.id}
        className={`expense-row${isSelected ? ' is-selected' : ''}`}
        style={{ '--coverage-pct': `${fillWidth}%`, '--coverage-color': coverageColor }}
        role="button"
        tabIndex={0}
        aria-pressed={isSelected}
        onClick={() => setSelected(isSelected ? null : e)}
        onKeyDown={rowKeyDown(e, isSelected)}
      >
        <div className="expense-row-name">{e.name}</div>
        <div className="expense-coverage-cluster" aria-label={`${pct} percent covered`}>
          <div className="expense-coverage-bar"><div className="expense-coverage-bar-fill" /></div>
          <div className="expense-coverage-pct">{pct}<span className="expense-coverage-pct-unit">%</span></div>
        </div>
        <div className="expense-row-amount">{fmtMoney(total)}</div>
        <div className="expense-row-date">{fmtDate(e.start_date)}</div>
        <div className="expense-row-meta">{rowMeta(e)}</div>
        <div className="expense-row-tags">
          {liveRecords.map((r, i) => (
            <React.Fragment key={r.id}>
              {i > 0 && <span className="oop-tag-separator">·</span>}
              <span className="oop-tag">
                <span className="oop-tag-prefix">OOP</span>
                {r.payerName} <span style={{ color: 'var(--dim)' }}>·</span> {fmtMoney(r.amount)}
              </span>
            </React.Fragment>
          ))}
          {showActionButton ? (
            <button
              className="expense-row-action"
              onClick={(ev) => { ev.stopPropagation(); setOopModalFor({ expense: e, period: null }); }}
              tabIndex={-1}
              aria-label={`Record out-of-pocket entry for ${e.name}`}
            >RECORD PAYMENT →</button>
          ) : null}
        </div>
      </div>
    );
  }

  /**
   * A settled one-time row: one line, and only what makes it findable again. No coverage bar
   * and no OOP tag, because at 100% both restate what "settled" already said. Clicking still
   * opens the same detail panel, so compressing costs nothing.
   */
  function renderSettledRow(e) {
    const isSelected = selected?.id === e.id;
    return (
      <div
        key={e.id}
        className={`expense-row is-compact${isSelected ? ' is-selected' : ''}`}
        role="button"
        tabIndex={0}
        aria-pressed={isSelected}
        onClick={() => setSelected(isSelected ? null : e)}
        onKeyDown={rowKeyDown(e, isSelected)}
      >
        <div className="expense-row-name">{e.name}</div>
        {/* Owner only. The category is on the full row and in the detail panel, and on a
            settled line it is 'Other' for most of the list, so it spends a column to say
            nothing. Owner is the half of the lookup the search box cannot do. */}
        <div className="expense-row-meta">
          {isAdmin ? <span>{e.creator_id ? (e.creator?.creator_name || e.creator?.full_name || 'Creator') : 'Business'}</span> : null}
        </div>
        <div className="expense-row-amount">{fmtMoney(e.amount)}</div>
        <div className="expense-row-date">{fmtDate(e.start_date)}</div>
      </div>
    );
  }
  const recurringSorted = filteredExpenses.filter(e => e.type === 'recurring');

  // The two UNFILTERED sets, which each section's empty state needs to tell "the filters hid
  // them" from "there are none". @see .claude/rules/hub-ui.md
  const allOneTime = useMemo(() => expenses.filter(e => e.type === 'one_time'), [expenses]);
  const allRecurring = useMemo(() => expenses.filter(e => e.type === 'recurring'), [expenses]);

  // Stats (all expenses, not filtered)
  const { totalOneTime, totalCovered, monthlyBurn } = useMemo(() => {
    const totalOneTime = allOneTime.reduce((s, e) => s + parseFloat(e.amount), 0);
    const totalCovered = allOneTime.reduce((s, e) => s + Math.min(parseFloat(e.amount), coverageMap[e.id]?.total || 0), 0);
    const monthlyBurn = allRecurring.reduce((s, e) => s + toMonthlyAmount(e), 0);
    return { totalOneTime, totalCovered, monthlyBurn };
  }, [allOneTime, allRecurring, coverageMap]);

  function openAdd() {
    setForm(BLANK_FORM);
    setFormError('');
    setModal('add');
  }

  function openPriceModal(expense) {
    const today = new Date();
    const todayStr = `${today.getFullYear()}-${String(today.getMonth() + 1).padStart(2, '0')}-${String(today.getDate()).padStart(2, '0')}`;
    setPriceForm({ amount: '', effective_date: todayStr, notes: '' });
    setPriceFormError('');
    setPriceModal(expense);
  }

  /**
   * Insert an expense_price_history row, the only sanctioned way to change a
   * recurring expense's amount.
   * @gotcha when the effective_date is today or earlier, also sync
   *         expenses.amount so the denormalized current price stays in step;
   *         a future-dated change leaves expenses.amount alone until it lands.
   */
  async function savePriceChange() {
    const amt = parseFloat(priceForm.amount);
    if (!priceForm.amount || amt <= 0) { setPriceFormError('Amount must be greater than 0.'); return; }
    if (!priceForm.effective_date) { setPriceFormError('Effective date is required.'); return; }

    setPriceSaving(true);
    setPriceFormError('');

    const { error } = await supabase.from('expense_price_history').insert({
      expense_id:     priceModal.id,
      amount:         amt,
      effective_date: priceForm.effective_date,
      notes:          priceForm.notes.trim() || null,
    });

    if (error) {
      if (process.env.NODE_ENV !== 'production') console.error(error);
      setPriceFormError('Failed to save. Please try again.');
      setPriceSaving(false);
      return;
    }

    // If effective_date is today or in the past, bring expenses.amount in sync
    const effectiveDate = parseLocalDate(priceForm.effective_date);
    const today = new Date(); today.setHours(0, 0, 0, 0);
    if (effectiveDate <= today) {
      const { error } = await mutate(supabase.from('expenses').update({ amount: amt }).eq('id', priceModal.id));
      if (error) { setPriceSaving(false); toast.error(error); return; }
      if (selected?.id === priceModal.id) {
        setSelected(s => ({ ...s, amount: amt }));
      }
    }

    setPriceSaving(false);
    setPriceModal(null);
    fetchAll();
  }

  function openEdit(e) {
    setForm({
      name:                    e.name,
      category_id:             e.category_id || '',
      amount:                  String(e.amount),
      type:                    e.type,
      frequency:               e.frequency || 'monthly',
      recurrence_day_of_week:  e.recurrence_day_of_week != null ? String(e.recurrence_day_of_week) : '1',
      recurrence_day_of_month: e.recurrence_day_of_month != null ? String(e.recurrence_day_of_month) : '1',
      start_date:              e.start_date || '',
      end_date:                e.end_date || '',
      creator_id:              e.creator_id || '',
      notes:                   e.notes || '',
    });
    setFormError('');
    setModal(e);
  }

  /**
   * Create or update an expense from the modal form.
   * @gotcha for a recurring expense being edited, `amount` is omitted from the
   *         payload (it lives in price history); on create, the entered amount
   *         both saves on the row AND seeds the first price-history entry so
   *         coverage lookups resolve immediately.
   */
  async function saveExpense() {
    const isEditingRecurring = modal !== 'add' && form.type === 'recurring';
    if (!form.name.trim()) { setFormError({ tone: 'error', title: 'Name is required.' }); return; }
    if (!isEditingRecurring && (!form.amount || parseFloat(form.amount) <= 0)) {
      setFormError({ tone: 'error', title: 'Amount must be greater than zero.' }); return;
    }
    if (!form.start_date)  { setFormError({ tone: 'error', title: 'Start date is required.' }); return; }
    if (form.type === 'recurring' && !form.frequency) { setFormError({ tone: 'error', title: 'Frequency is required for recurring expenses.' }); return; }
    const dateLo = DB_DATE_MIN, dateHi = DB_DATE_MAX;
    if (form.start_date && (form.start_date < dateLo || form.start_date > dateHi)) {
      setFormError({ tone: 'error', title: 'Start date out of range', body: 'Dates must be between Jan 1, 2025 and Dec 31, 2032.' }); return;
    }
    if (form.end_date && (form.end_date < dateLo || form.end_date > dateHi)) {
      setFormError({ tone: 'error', title: 'End date out of range', body: 'Dates must be between Jan 1, 2025 and Dec 31, 2032.' }); return;
    }
    // @invariant end >= start, as the campaign form has always done it. This check and the End
    //            Date field's `min` say it first; chk_expenses_end_after_start says it last, so
    //            a reversed range arriving any other way is refused rather than stored. A
    //            reversed row generates zero occurrences, so the period grid just goes quietly
    //            empty rather than erroring. Recurring is the only branch that shows an End
    //            Date, so a one-time save is never refused over a field it is not displaying.
    //            @see schemas/SCHEMA.sql
    if (form.type === 'recurring' && form.start_date && form.end_date && form.end_date < form.start_date) { setFormError({ tone: 'error', title: 'End date cannot be before the start date.' }); return; }

    setSaving(true);
    setFormError('');

    const payload = {
      name:        form.name.trim(),
      category_id: form.category_id || null,
      type:        form.type,
      start_date:  form.start_date,
      end_date:    form.end_date || null,
      creator_id:  form.creator_id || null,
      notes:       form.notes.trim() || null,
      frequency:   form.type === 'recurring' ? form.frequency : null,
      recurrence_day_of_week:  form.type === 'recurring' && form.frequency === 'weekly'
        ? parseInt(form.recurrence_day_of_week) : null,
      recurrence_day_of_month: form.type === 'recurring' && form.frequency !== 'weekly'
        ? parseInt(form.recurrence_day_of_month) : null,
    };

    // Amount is managed through price history for recurring expenses; only include
    // it in the payload when creating or editing a one-time expense.
    if (!isEditingRecurring) {
      payload.amount = parseFloat(form.amount);
    }

    if (modal === 'add') {
      const { data: inserted, error: insErr } = await supabase.from('expenses').insert(payload).select('id').single();
      if (insErr) { setFormError(humanizeError(insErr)); setSaving(false); return; }
      // Seed initial price history row so coverage lookups work immediately
      if (inserted?.id) {
        await supabase.from('expense_price_history').insert({
          expense_id:     inserted.id,
          amount:         parseFloat(form.amount),
          effective_date: form.start_date,
        });
      }
    } else {
      const { error } = await mutate(supabase.from('expenses').update(payload).eq('id', modal.id));
      if (error) { setSaving(false); toast.error(error); return; }
    }

    setSaving(false);
    setModal(null);
    fetchAll();
  }

  async function deleteReceipt(receipt) {
    if (!(await askConfirm({ title: `Remove "${receipt.file_name}"?`, body: 'This cannot be undone.', danger: true }))) return;
    await supabase.storage.from('expense-receipts').remove([receipt.file_path]);
    const { error } = await mutate(supabase.from('expense_receipts').delete().eq('id', receipt.id));
    if (error) { toast.error(error); return; }
    setReceiptsMap(prev => {
      const key = receipt.period_key ?? 'one-time';
      const updated = (prev[receipt.expense_id]?.[key] || []).filter(r => r.id !== receipt.id);
      return { ...prev, [receipt.expense_id]: { ...prev[receipt.expense_id], [key]: updated } };
    });
  }

  async function handleReceiptUpload(file, expenseId, periodKey) {
    setReceiptError('');
    await uploadExpenseReceipt({
      file,
      expenseId,
      periodKey: periodKey ?? null,
      uploadedBy: profileId,
      setUploading: setReceiptUploading,
      onSuccess: (row) => {
        setReceiptsMap(prev => {
          const key = row.period_key ?? 'one-time';
          const existing = prev[row.expense_id]?.[key] || [];
          return { ...prev, [row.expense_id]: { ...prev[row.expense_id], [key]: [...existing, row] } };
        });
      },
      onError: (msg) => setReceiptError(msg),
    });
  }

  async function deleteExpense(expense) {
    if (!(await askConfirm({ title: `Delete "${expense.name}"?`, body: 'This cannot be undone.', danger: true }))) return;
    const { error } = await mutate(supabase.from('expenses').delete().eq('id', expense.id));
    if (error) { toast.error(error); return; }
    setSelected(null);
    fetchAll();
  }

  const selectedAllocations = selected ? allocations.filter(a => a.expense_id === selected.id) : [];

  // For the recurring detail panel, generate the full period grid back to start_date.
  // Latest period first (so the grid lays out latest top-right, oldest bottom-left).
  const recurringPeriods = useMemo(() => {
    if (!selected || selected.type !== 'recurring') return [];
    const start = parseLocalDate(selected.start_date);
    if (!start) return [];
    const now = new Date();
    const rangeEnd = new Date(now.getFullYear(), now.getMonth() + PERIOD_MONTHS + 1, 0);
    return getOccurrencesInRange(selected, start, rangeEnd).reverse();
  }, [selected]);

  if (loading) return <div className="page"><Loading /></div>;
  // Error before Empty: an empty expense list reads as "nothing is being spent".
  if (loadErr) return <div className="page"><Feedback value={loadErr} /></div>;

  return (
    <div className="page">
      {/* Header */}
      <div className="page-header">
        <div>
          <h1 className="page-title">
            EXPENSES
            {isAdmin && <HelpIcon slug="expense" />}
          </h1>
          <div className="page-subtitle">
            {isAdmin ? 'Business and creator expenses' : 'Your expenses'}<Refreshing on={refreshing} />
          </div>
        </div>
        {isAdmin && (
          <button className="btn btn-primary" onClick={openAdd}>+ Add Expense</button>
        )}
      </div>

      {/* Stats */}
      <div className="stats-row">
        <div className="stat-card">
          <div className="stat-label">ONE-TIME TOTAL<HelpIcon slug="expense" /></div>
          <div className="stat-value">{fmtMoney(totalOneTime)}</div>
        </div>
        <div className="stat-card">
          <div className="stat-label">COVERED<HelpIcon slug="expense-via-split" /></div>
          <div className="stat-value stat-green">{fmtMoney(totalCovered)}</div>
        </div>
        <div className="stat-card">
          <div className="stat-label">OUTSTANDING<HelpIcon slug="expense-via-split" /></div>
          <div className="stat-value stat-accent">{fmtMoney(Math.max(0, totalOneTime - totalCovered))}</div>
        </div>
        <div className="stat-card">
          <div className="stat-label">MONTHLY BURN<HelpIcon slug="expense" /></div>
          <div className="stat-value stat-orange">{fmtMoney(monthlyBurn)}<span style={{ fontSize: 14, color: 'var(--muted)', fontFamily: 'var(--font-body)', fontWeight: 300 }}>/mo</span></div>
        </div>
      </div>

      {/* Filters. Coverage chips used to live here and are gone: the outstanding/settled
          split answers the same question by default, so the chips only restated it. */}
      <div className="filters-row">
        {['all', 'one_time', 'recurring'].map(v => (
          <button key={v} className={`filter-chip ${typeFilter === v ? 'active' : ''}`} aria-pressed={typeFilter === v} onClick={() => setTypeFilter(v)}>
            {v === 'all' ? 'All' : v === 'one_time' ? 'One-Time' : 'Recurring'}
          </button>
        ))}
        {isAdmin && (
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8, marginLeft: 8 }}>
            {[{ v: 'all', label: 'All Owners' }, { v: 'business', label: 'Business' }, ...creators.map(c => ({ v: c.id, label: c.creator_name || c.full_name }))].map(({ v, label }) => (
              <button key={v} className={`filter-chip ${creatorFilter === v ? 'active' : ''}`} aria-pressed={creatorFilter === v} onClick={() => setCreatorFilter(v)}>{label}</button>
            ))}
          </div>
        )}
        <input
          className="form-input expense-search"
          type="search"
          aria-label="Search expenses by name"
          placeholder="Search by name…"
          value={search}
          onChange={(ev) => setSearch(ev.target.value)}
        />
      </div>

      {/* One-Time Expenses */}
      {(typeFilter === 'all' || typeFilter === 'one_time') && (
        <section style={{ marginBottom: 32 }}>
          <h2 className="section-label">ONE-TIME EXPENSES</h2>
          {oneTimeSorted.length === 0 ? (
            <EmptyState icon="$"
              title="No one-time expenses"
              text={isAdmin ? 'Add equipment, gear, or one-off purchases.' : 'No one-time expenses have been recorded yet.'}
              filtered={{ unfiltered: allOneTime, dirty: expenseFiltersDirty,
                onClear: clearExpenseFilters, title: 'No matching one-time expenses',
                text: 'Nothing here matches the filters above.' }} />
          ) : (
            <>
              {oneTimeOutstanding.length > 0 ? (
                <div className="expense-list">
                  {oneTimeOutstanding.map(renderOneTimeRow)}
                </div>
              ) : (
                /* The steady state once everything is paid. It reads as a clean desk rather
                   than as an empty page, so it is a line and not an `EmptyState` block. */
                <p className="expense-settled-note">
                  {expenseFiltersDirty ? 'Nothing outstanding in this view.' : 'Nothing outstanding. Every one-time expense is covered.'}
                </p>
              )}

              {oneTimeSettled.length > 0 && (
                <div className="expense-settled">
                  {/* While a filter or a search is narrowing the page, the pile is forced
                      open and its header stops being a control: offering a toggle that
                      cannot close would be a lie. */}
                  {expenseFiltersDirty ? (
                    <div className="expense-settled-head">
                      <span className="expense-settled-label">Settled</span>
                      <span className="expense-settled-count">{oneTimeSettled.length}</span>
                      <span className="expense-settled-total">{fmtMoney(settledTotal)}</span>
                    </div>
                  ) : (
                    <button
                      type="button"
                      className="expense-settled-head"
                      aria-expanded={settledExpanded}
                      onClick={() => setSettledOpen(o => !o)}
                    >
                      <span className="expense-settled-caret" aria-hidden="true">{settledExpanded ? '\u25be' : '\u25b8'}</span>
                      <span className="expense-settled-label">Settled</span>
                      <span className="expense-settled-count">{oneTimeSettled.length}</span>
                      <span className="expense-settled-total">{fmtMoney(settledTotal)}</span>
                    </button>
                  )}
                  {settledExpanded && (
                    <div className="expense-list expense-list-compact">
                      {oneTimeSettled.map(renderSettledRow)}
                    </div>
                  )}
                </div>
              )}
            </>
          )}
        </section>
      )}

      {/* Recurring Expenses */}
      {(typeFilter === 'all' || typeFilter === 'recurring') && (
        <section style={{ marginBottom: 32 }}>
          <h2 className="section-label">RECURRING EXPENSES</h2>
          {recurringSorted.length === 0 ? (
            <EmptyState icon="↻"
              title="No recurring expenses"
              text={isAdmin ? 'Add subscriptions, licenses, or regular costs.' : 'No recurring expenses have been recorded yet.'}
              filtered={{ unfiltered: allRecurring, dirty: expenseFiltersDirty,
                onClear: clearExpenseFilters, title: 'No matching recurring expenses',
                text: 'Nothing here matches the filters above.' }} />
          ) : (
            <div className="expense-list">
              {recurringSorted.map(e => {
                const categoryName = expenseCategories.find(c => c.id === e.category_id)?.name || '';
                const ownerLabel = e.creator_id ? (e.creator?.creator_name || e.creator?.full_name || 'Creator') : 'Business';
                const isSelected = selected?.id === e.id;
                const today = new Date();
                const stripStart = new Date(today.getFullYear(), today.getMonth() - 11, 1);
                const stripEnd = new Date(today.getFullYear(), today.getMonth() + 1, 0);
                const stripOccs = getOccurrencesInRange(e, stripStart, stripEnd);
                const currentKey = `${today.getFullYear()}-${String(today.getMonth() + 1).padStart(2, '0')}`;
                const onKeyDown = (ev) => {
                  if (ev.key === 'Enter' || ev.key === ' ') {
                    ev.preventDefault();
                    setSelected(isSelected ? null : e);
                  }
                };
                return (
                  <div
                    key={e.id}
                    className={`expense-row${isSelected ? ' is-selected' : ''}`}
                    role="button"
                    tabIndex={0}
                    aria-pressed={isSelected}
                    onClick={() => setSelected(isSelected ? null : e)}
                    onKeyDown={onKeyDown}
                  >
                    <div className="expense-row-name">{e.name}</div>
                    <div className="expense-row-amount">{fmtMoney(e.amount)}<span style={{ fontSize: 11, color: 'var(--muted)', fontWeight: 300 }}>/{e.frequency === 'weekly' ? 'wk' : e.frequency === 'monthly' ? 'mo' : e.frequency === 'quarterly' ? 'qtr' : 'yr'}</span></div>
                    <div className="expense-row-date">{fmtMoney(toMonthlyAmount(e))}<span style={{ fontSize: 10, color: 'var(--dim)' }}>/mo</span></div>
                    <div className="expense-row-strip">
                      {stripOccs.map(({ date, periodKey, isFuture }) => {
                        const covered = coverageMap[e.id]?.[periodKey] || 0;
                        const total = getEffectiveAmount(priceHistory[e.id], date) ?? parseFloat(e.amount);
                        const status = expenseCoverageStatus(covered, total);
                        const isUnpaidPast = status !== 'covered' && status !== 'partial' && !isFuture && periodKey !== currentKey;
                        const cls = [
                          'expense-row-strip-cell',
                          status === 'covered' ? 'is-covered' : '',
                          status === 'partial' ? 'is-partial' : '',
                          isUnpaidPast ? 'is-unpaid' : '',
                          periodKey === currentKey ? 'is-current' : '',
                          isFuture ? 'is-future' : '',
                        ].filter(Boolean).join(' ');
                        return (
                          <div
                            key={periodKey}
                            className={cls}
                            title={`${fmtPeriod(periodKey)} · ${fmtMoney(covered)}/${fmtMoney(total)}`}
                          />
                        );
                      })}
                      <span style={{ marginLeft: 'auto', fontSize: 11, color: 'var(--muted)' }}>
                        {categoryName}{isAdmin && ` · ${ownerLabel}`}
                      </span>
                    </div>
                  </div>
                );
              })}
            </div>
          )}

          {/* Projections */}
          {recurringSorted.length > 0 && (
            <div className="card" style={{ marginTop: 16 }}>
              <h2 className="card-title">RECURRING PROJECTIONS</h2>
              <div style={{ display: 'flex', gap: 32, flexWrap: 'wrap' }}>
                <div>
                  <div style={{ fontSize: 10, color: 'var(--muted)', textTransform: 'uppercase', letterSpacing: '1.5px', marginBottom: 4 }}>Monthly</div>
                  <div style={{ fontFamily: 'var(--font-display)', fontSize: 24, color: 'var(--white)' }}>{fmtMoney(monthlyBurn)}</div>
                </div>
                <div>
                  <div style={{ fontSize: 10, color: 'var(--muted)', textTransform: 'uppercase', letterSpacing: '1.5px', marginBottom: 4 }}>Quarterly</div>
                  <div style={{ fontFamily: 'var(--font-display)', fontSize: 24, color: 'var(--white)' }}>{fmtMoney(monthlyBurn * 3)}</div>
                </div>
                <div>
                  <div style={{ fontSize: 10, color: 'var(--muted)', textTransform: 'uppercase', letterSpacing: '1.5px', marginBottom: 4 }}>Annual</div>
                  <div style={{ fontFamily: 'var(--font-display)', fontSize: 24, color: 'var(--white)' }}>{fmtMoney(monthlyBurn * 12)}</div>
                </div>
              </div>
              <div style={{ display: 'flex', gap: 20, marginTop: 16, flexWrap: 'wrap', paddingTop: 16, borderTop: '1px solid var(--border)' }}>
                {expenseCategories.map(c => {
                  const catExpenses = recurringSorted.filter(e => e.category_id === c.id);
                  if (catExpenses.length === 0) return null;
                  const catMonthly = catExpenses.reduce((s, e) => s + toMonthlyAmount(e), 0);
                  return (
                    <div key={c.id} style={{ fontSize: 11, color: 'var(--muted)' }}>
                      <span style={{ color: 'var(--white)', fontWeight: 500 }}>{c.name}</span> {fmtMoney(catMonthly)}/mo
                    </div>
                  );
                })}
              </div>
            </div>
          )}
        </section>
      )}

      {/* Detail panel */}
      {selected && (
        <div className="detail-panel" {...dirtyProps}>
          <div className="detail-header">
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
              <div style={{ flex: 1, minWidth: 0, paddingRight: 12 }}>
                <h2 className="detail-panel-title">{selected.name}</h2>
                <div style={{ display: 'flex', alignItems: 'baseline', gap: 10, marginTop: 10 }}>
                  <div style={{ fontFamily: 'var(--font-display)', fontSize: 30, color: 'var(--orange)', lineHeight: 1 }}>
                    {fmtMoney(selected.amount)}
                    {selected.type === 'recurring' && (
                      <span style={{ fontSize: 13, color: 'var(--muted)', fontFamily: 'var(--font-body)', fontWeight: 300 }}>
                        /{selected.frequency === 'weekly' ? 'wk' : selected.frequency === 'monthly' ? 'mo' : selected.frequency === 'quarterly' ? 'qtr' : 'yr'}
                      </span>
                    )}
                  </div>
                  <span style={{ fontSize: 9, fontWeight: 700, letterSpacing: '1.2px', textTransform: 'uppercase', color: selected.type === 'recurring' ? 'var(--orange2)' : 'var(--dim)', background: 'var(--surface2)', padding: '2px 6px', borderRadius: 2 }}>
                    {selected.type === 'recurring' ? 'Recurring' : 'One-Time'}
                  </span>
                </div>
              </div>
              <div style={{ display: 'flex', gap: 8, alignItems: 'flex-start', flexShrink: 0 }}>
                {isAdmin && <button className="btn btn-secondary btn-sm" onClick={() => openEdit(selected)}>Edit</button>}
                {isAdmin && <button className="btn btn-ghost btn-sm" style={{ color: 'var(--red)' }} onClick={() => deleteExpense(selected)}>Delete</button>}
                <button className="btn btn-ghost btn-icon btn-sm" onClick={() => setSelected(null)} aria-label="Close expense details">✕</button>
              </div>
            </div>

            <div style={{ display: 'flex', gap: 20, marginTop: 14, paddingTop: 14, borderTop: '1px solid var(--border)', flexWrap: 'wrap' }}>
              {selected.type === 'one_time' ? (
                <div>
                  <div style={{ fontSize: 9, textTransform: 'uppercase', letterSpacing: '1.5px', color: 'var(--muted)', marginBottom: 3 }}>Date</div>
                  <div style={{ fontSize: 13, fontWeight: 500 }}>{fmtDate(selected.start_date)}</div>
                </div>
              ) : (() => {
                const schedParts = [FREQ_LABELS[selected.frequency]];
                if (selected.frequency === 'weekly' && selected.recurrence_day_of_week != null)
                  schedParts.push(DAYS_OF_WEEK[selected.recurrence_day_of_week]);
                else if (selected.frequency !== 'weekly' && selected.recurrence_day_of_month != null)
                  schedParts.push(selected.recurrence_day_of_month === 0 ? 'Last day' : `${selected.recurrence_day_of_month}${ordSuffix(selected.recurrence_day_of_month)}`);
                return (
                  <>
                    <div>
                      <div style={{ fontSize: 9, textTransform: 'uppercase', letterSpacing: '1.5px', color: 'var(--muted)', marginBottom: 3 }}>Schedule</div>
                      <div style={{ fontSize: 13, fontWeight: 500 }}>{schedParts.join(' · ')}</div>
                    </div>
                    <div>
                      <div style={{ fontSize: 9, textTransform: 'uppercase', letterSpacing: '1.5px', color: 'var(--muted)', marginBottom: 3 }}>Started</div>
                      <div style={{ fontSize: 13, fontWeight: 500 }}>{fmtDate(selected.start_date)}</div>
                    </div>
                    {selected.end_date && (
                      <div>
                        <div style={{ fontSize: 9, textTransform: 'uppercase', letterSpacing: '1.5px', color: 'var(--muted)', marginBottom: 3 }}>Ends</div>
                        <div style={{ fontSize: 13, fontWeight: 500 }}>{fmtDate(selected.end_date)}</div>
                      </div>
                    )}
                    <div>
                      <div style={{ fontSize: 9, textTransform: 'uppercase', letterSpacing: '1.5px', color: 'var(--muted)', marginBottom: 3 }}>Monthly</div>
                      <div style={{ fontSize: 13, fontWeight: 500 }}>{fmtMoney(toMonthlyAmount(selected))}</div>
                    </div>
                  </>
                );
              })()}
              <div>
                <div style={{ fontSize: 9, textTransform: 'uppercase', letterSpacing: '1.5px', color: 'var(--muted)', marginBottom: 3 }}>Owner</div>
                <div style={{ fontSize: 13, fontWeight: 500 }}>
                  {selected.creator_id ? (selected.creator?.creator_name || selected.creator?.full_name || 'Creator') : 'Business'}
                </div>
              </div>
              {expenseCategories.find(c => c.id === selected.category_id) && (
                <div>
                  <div style={{ fontSize: 9, textTransform: 'uppercase', letterSpacing: '1.5px', color: 'var(--muted)', marginBottom: 3 }}>Category</div>
                  <div style={{ fontSize: 13, fontWeight: 500 }}>{expenseCategories.find(c => c.id === selected.category_id)?.name}</div>
                </div>
              )}
            </div>

            {selected.notes && (
              <div style={{ marginTop: 12, padding: '10px 12px', background: 'var(--surface2)', borderRadius: 6, fontSize: 12, color: 'var(--muted)', lineHeight: 1.6 }}>
                {selected.notes}
              </div>
            )}
          </div>

          <div className="detail-body">
            {/* One-time: action band + OOP record list */}
            {selected.type === 'one_time' && (() => {
              const { covered, total, status } = getOnTimeCoverage(selected);
              const records = oopMap[selected.id]?.['one-time'] || [];
              const isCovered = status === 'covered';
              return (
                <div className="detail-section">
                  <h3 className="detail-section-title">COVERAGE<HelpIcon slug="expense-via-split" /></h3>
                  <div className="oop-action-band">
                    <div className="oop-action-band-amount">{fmtMoney(total)}</div>
                    <div className="oop-action-band-date">{fmtDate(selected.start_date)}</div>
                    <div className={`oop-action-band-status ${isCovered ? 'is-covered' : 'is-uncovered'}`} style={{ textAlign: 'left' }}>
                      {isCovered ? `COVERED · ${fmtMoney(covered)} of ${fmtMoney(total)}` : `UNCOVERED · ${fmtMoney(Math.max(0, total - covered))} left`}
                    </div>
                    {isAdmin && !isCovered ? (
                      <button className="btn btn-primary btn-sm" onClick={() => setOopModalFor({ expense: selected, period: null })}>
                        RECORD PAYMENT
                      </button>
                    ) : null}
                  </div>

                  {records.length > 0 && (
                    <div className="oop-record-list" style={{ marginTop: 4 }}>
                      {records.map((r) => {
                        const reversed = !!r.journalEntry?.reversed_by_je_id;
                        return (
                          <React.Fragment key={r.id}>
                            <div className={`oop-record-row${reversed ? ' is-reversed' : ''}`}>
                            <div className={`oop-record-payer${r.payerType === 'partners' ? ' is-partners' : ''}`}>{r.payerName}</div>
                            <div className="oop-record-amount">{fmtMoney(r.amount)}</div>
                            <div className="oop-record-date">{fmtDate(r.paid_at)}</div>
                            <div className="oop-record-meta">{reversed ? 'reversed' : ''}</div>
                            {!reversed && isAdmin && r.journalEntry ? (
                              <button
                                className="btn btn-ghost btn-sm"
                                style={{ color: 'var(--orange)', padding: '2px 6px', fontSize: 11 }}
                                onClick={() => setReverseFor(r.journalEntry)}
                              >Reverse</button>
                            ) : <span />}
                            </div>
                            {!reversed && <PaymentShares shares={shareMap[r.id]} />}
                          </React.Fragment>
                        );
                      })}
                    </div>
                  )}

                  {isAdmin && records.length > 0 && !isCovered ? (
                    <button
                      className="btn btn-ghost btn-sm"
                      style={{ marginTop: 10 }}
                      onClick={() => setOopModalFor({ expense: selected, period: null })}
                    >+ Record another OOP entry</button>
                  ) : null}
                </div>
              );
            })()}

            {/* One-time: receipts */}
            {selected.type === 'one_time' && (() => {
              const receipts = receiptsMap[selected.id]?.['one-time'] || [];
              const canUpload = isAdmin || selected.creator_id === profileId;
              return (
                <div className="detail-section">
                  <h3 className="detail-section-title">RECEIPTS<HelpIcon slug="receipt-upload" /></h3>
                  {receipts.map(r => (
                    <AttachmentRow key={r.id} name={r.file_name} bucket="expense-receipts" path={r.file_path}
                      onDelete={(isAdmin || r.uploaded_by === profileId) ? () => deleteReceipt(r) : undefined}
                      deleteLabel={`Remove ${r.file_name || 'this receipt'}`} />
                  ))}
                  {canUpload && (<>
                    {/* A hit area, not a control: the click repeats what the button inside it
                        does. The input is its sibling, or its click() bubbles back in here. */}
                    <div style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '10px 12px', background: 'var(--surface)', border: '1px dashed var(--border)', borderRadius: 6, cursor: receiptUploading ? 'default' : 'pointer', marginTop: receipts.length ? 4 : 0 }}
                      onClick={() => oneTimeInputRef.current.click()}>
                      <span style={{ flexShrink: 0, color: 'var(--muted)', display: 'inline-flex' }}><AttachIcon size={15} /></span>
                      <span style={{ fontSize: 12, color: 'var(--muted)', flex: 1 }}>{receiptUploading ? 'Uploading…' : RECEIPT_FILE_HINT}</span>
                      <button className="btn btn-ghost btn-sm" disabled={receiptUploading} onClick={e => { e.stopPropagation(); oneTimeInputRef.current.click(); }}>Attach a receipt</button>
                    </div>
                    <input aria-label="Receipt file" ref={oneTimeInputRef} type="file" accept={RECEIPT_FILE_ACCEPT} style={{ display: 'none' }} disabled={receiptUploading}
                      onChange={e => { if (e.target.files[0]) handleReceiptUpload(e.target.files[0], selected.id, null); e.target.value = ''; }} />
                  </>)}
                  {receiptError && <Feedback value={receiptError} style={{ marginTop: 6 }} />}
                </div>
              );
            })()}

            {/* Recurring: multi-select period grid */}
            {selected.type === 'recurring' && recurringPeriods.length > 0 && (() => {
              // recurringPeriods is latest-first. For the 4xN grid we want latest top-right,
              // oldest bottom-left, like a quarterly layout. Reverse to chronological order,
              // then pad the front so that the LAST row (= latest periods) is right-aligned.
              const periodsAsc = [...recurringPeriods].reverse();
              const cols = 4;
              const rowsNeeded = Math.ceil(periodsAsc.length / cols);
              const leadingPad = rowsNeeded * cols - periodsAsc.length;
              const gridCells = [
                ...Array.from({ length: leadingPad }, (_, i) => ({ pad: true, key: `pad-${i}` })),
                ...periodsAsc.map((p) => ({ pad: false, ...p })),
              ];
              return (
                <div className="detail-section">
                  <h3 className="detail-section-title">PERIOD COVERAGE<HelpIcon slug="expense-via-split" /></h3>
                  <div className="oop-grid">
                    {gridCells.map((cell) => {
                      if (cell.pad) return <div key={cell.key} style={{ visibility: 'hidden' }} />;
                      const { date, periodKey, isFuture } = cell;
                      const covered = coverageMap[selected.id]?.[periodKey] || 0;
                      const total   = getEffectiveAmount(priceHistory[selected.id], date) ?? parseFloat(selected.amount);
                      const status  = expenseCoverageStatus(covered, total);
                      const isCovered = status === 'covered' || status === 'overpaid';
                      const isPartial = status === 'partial';
                      const isDisabled = isFuture || isCovered;
                      const isSelectedCell = gridSelection.has(periodKey);
                      const cls = [
                        'oop-grid-cell',
                        isCovered ? 'is-covered' : '',
                        isPartial ? 'is-partial' : '',
                        isDisabled ? 'is-disabled' : '',
                        isSelectedCell ? 'is-selected' : '',
                      ].filter(Boolean).join(' ');
                      const onClick = (ev) => {
                        if (isDisabled) return;
                        const next = new Set(gridSelection);
                        if (ev.shiftKey && gridAnchor) {
                          const allKeys = periodsAsc.filter(p => {
                            const c = coverageMap[selected.id]?.[p.periodKey] || 0;
                            const t = getEffectiveAmount(priceHistory[selected.id], p.date) ?? parseFloat(selected.amount);
                            const s = expenseCoverageStatus(c, t);
                            return !p.isFuture && s !== 'covered' && s !== 'overpaid';
                          }).map(p => p.periodKey);
                          const a = allKeys.indexOf(gridAnchor);
                          const b = allKeys.indexOf(periodKey);
                          if (a >= 0 && b >= 0) {
                            const [lo, hi] = a < b ? [a, b] : [b, a];
                            for (let i = lo; i <= hi; i++) next.add(allKeys[i]);
                          }
                        } else if (ev.metaKey || ev.ctrlKey) {
                          if (next.has(periodKey)) next.delete(periodKey); else next.add(periodKey);
                        } else {
                          if (next.has(periodKey) && next.size === 1) next.delete(periodKey);
                          else { next.clear(); next.add(periodKey); }
                        }
                        setGridSelection(next);
                        setGridAnchor(periodKey);
                      };
                      const onKeyDown = (ev) => {
                        if (ev.key === ' ' || ev.key === 'Enter') {
                          ev.preventDefault();
                          onClick({ shiftKey: ev.shiftKey, metaKey: ev.metaKey, ctrlKey: ev.ctrlKey });
                        }
                      };
                      return (
                        <div
                          key={periodKey}
                          className={cls}
                          role={isDisabled ? undefined : 'button'}
                          tabIndex={isDisabled ? -1 : 0}
                          aria-pressed={isSelectedCell}
                          aria-disabled={isDisabled}
                          aria-label={`${fmtPeriod(periodKey)}, ${fmtMoney(total)}, ${status}`}
                          onClick={onClick}
                          onKeyDown={onKeyDown}
                          title={`${fmtPeriod(periodKey)} · ${fmtMoney(covered)}/${fmtMoney(total)}`}
                        >
                          <div className="oop-grid-cell-month">{date.toLocaleDateString('en-US', { month: 'short' }).toUpperCase()} {date.getFullYear() !== new Date().getFullYear() ? `'${String(date.getFullYear()).slice(-2)}` : ''}</div>
                          <div className="oop-grid-cell-price">{fmtMoney(total)}</div>
                          <div className="oop-grid-cell-bar" />
                        </div>
                      );
                    })}
                  </div>
                </div>
              );
            })()}

            {/* Floating action bar when periods selected */}
            {selected.type === 'recurring' && isAdmin && gridSelection.size > 0 && (() => {
              const selectedPeriods = [...gridSelection].sort();
              const perPrices = selectedPeriods.map((pk) => {
                const occ = recurringPeriods.find((p) => p.periodKey === pk);
                if (!occ) return 0;
                const remaining = (getEffectiveAmount(priceHistory[selected.id], occ.date) ?? parseFloat(selected.amount));
                const covered = coverageMap[selected.id]?.[pk] || 0;
                return Math.max(0, remaining - covered);
              });
              const total = perPrices.reduce((s, n) => s + n, 0);
              const allSame = perPrices.every(p => Math.abs(p - perPrices[0]) < 0.005);
              const eachLabel = allSame ? ` · ${fmtMoney(perPrices[0])} each` : '';
              return (
                <div className="oop-action-bar">
                  <div className="oop-action-bar-summary">
                    <strong>{gridSelection.size}</strong> period{gridSelection.size === 1 ? '' : 's'} selected{eachLabel} · <strong>{fmtMoney(total)} total</strong>
                  </div>
                  <button className="btn btn-ghost btn-sm" onClick={() => { setGridSelection(new Set()); setGridAnchor(null); }}>Cancel</button>
                  <button
                    className="btn btn-primary btn-sm"
                    onClick={() => {
                      const periodEntries = selectedPeriods.map((pk, i) => ({ periodKey: pk, amount: perPrices[i] }));
                      setOopModalFor({ expense: selected, period: null, periods: periodEntries });
                    }}
                  >RECORD PAYMENT →</button>
                </div>
              );
            })()}

            {/* OOP records list (recurring): per-period entries + their receipts */}
            {selected.type === 'recurring' && (() => {
              const byPeriod = oopMap[selected.id] || {};
              // oopMap already holds only live (posted, non-reversed) entries.
              const periodKeys = Object.keys(byPeriod).filter((k) => (byPeriod[k] || []).length > 0);
              if (periodKeys.length === 0) return null;
              const canUpload = isAdmin || selected.creator_id === profileId;
              const mostRecent = (k) => (byPeriod[k] || []).reduce((m, r) => (r.paid_at > m ? r.paid_at : m), '');
              periodKeys.sort((a, b) => (mostRecent(a) < mostRecent(b) ? 1 : mostRecent(a) > mostRecent(b) ? -1 : 0));
              const periodChipColor = (periodKey) => {
                const occ = recurringPeriods.find((p) => p.periodKey === periodKey);
                const covered = coverageMap[selected.id]?.[periodKey] || 0;
                const total = occ ? (getEffectiveAmount(priceHistory[selected.id], occ.date) ?? parseFloat(selected.amount)) : parseFloat(selected.amount);
                const status = expenseCoverageStatus(covered, total);
                if (status === 'overpaid') return 'var(--red)';
                if (status === 'covered')  return 'color-mix(in oklab, var(--green) 75%, var(--surface))';
                if (status === 'partial')  return 'color-mix(in oklab, var(--orange) 80%, var(--surface))';
                return 'var(--muted)';
              };
              const monthChip = (periodKey) => {
                const [y, m] = periodKey.split('-').map(Number);
                const d = new Date(y, m - 1, 1);
                const thisYear = new Date().getFullYear();
                const monthLabel = d.toLocaleDateString('en-US', { month: 'short' }).toUpperCase();
                return y !== thisYear ? `${monthLabel} '${String(y).slice(-2)}` : monthLabel;
              };
              return (
                <div className="detail-section">
                  <h3 className="detail-section-title">PAYMENT RECORDS</h3>
                  <div className="oop-record-list">
                    {periodKeys.map((periodKey) => {
                      const recs = [...(byPeriod[periodKey] || [])].sort((a, b) => (a.paid_at < b.paid_at ? 1 : -1));
                      const receipts = receiptsMap[selected.id]?.[periodKey] || [];
                      return (
                        <div
                          key={periodKey}
                          className="oop-record-group"
                          style={{ '--coverage-color': periodChipColor(periodKey) }}
                        >
                          {recs.map((r) => (
                            <div key={r.id} className="oop-record-row has-period">
                              <div className="oop-record-period">{monthChip(periodKey)}</div>
                              <div className={`oop-record-payer${r.payerType === 'partners' ? ' is-partners' : ''}`}>{r.payerName}</div>
                              <div className="oop-record-amount">{fmtMoney(r.amount)}</div>
                              <div className="oop-record-date">{fmtDate(r.paid_at)}</div>
                              <div className="oop-record-meta" />
                              {isAdmin && r.journalEntry ? (
                                <button
                                  className="btn btn-ghost btn-sm"
                                  style={{ color: 'var(--orange)', padding: '2px 6px', fontSize: 11 }}
                                  onClick={() => setReverseFor(r.journalEntry)}
                                >Reverse</button>
                              ) : <span />}
                            </div>
                          ))}
                          {recs.map((r) => (
                            <PaymentShares key={`sh-${r.id}`} shares={shareMap[r.id]} indented />
                          ))}
                          <div className="oop-receipt-strip">
                            {receipts.map((rc) => (
                              <span key={rc.id} className="oop-receipt-chip">
                                <ReceiptIcon size={13} />
                                <span className="oop-receipt-name">{rc.file_name}</span>
                                <button className="btn btn-secondary btn-sm" onClick={() => viewStoredFile('expense-receipts', rc.file_path)} aria-label={`View ${rc.file_name}`}>View</button>
                                <button className="btn btn-secondary btn-sm" onClick={() => downloadStoredFile('expense-receipts', rc.file_path, rc.file_name)} aria-label={`Download ${rc.file_name}`}>↓</button>
                                {(isAdmin || rc.uploaded_by === profileId) && (
                                  <button className="btn btn-ghost btn-sm" style={{ color: 'var(--red)' }} onClick={() => deleteReceipt(rc)} aria-label={`Remove ${rc.file_name}`}>✕</button>
                                )}
                              </span>
                            ))}
                            {canUpload && (<>
                              {/* The chip IS the control, so it carries the inline resets a
                                  <button> needs to keep the dashed-chip look. */}
                              <button className={`oop-receipt-attach${receiptUploading ? ' is-busy' : ''}`} disabled={receiptUploading}
                                style={{ background: 'none', fontFamily: 'inherit', fontWeight: 'inherit' }}
                                onClick={() => periodInputs.current[periodKey].click()}>
                                <AttachIcon size={13} />
                                <span>{receiptUploading ? 'Uploading…' : (receipts.length ? 'Attach another receipt' : 'Attach a receipt')}</span>
                              </button>
                              <input aria-label="Receipt file" ref={(el) => { periodInputs.current[periodKey] = el; }} type="file" accept={RECEIPT_FILE_ACCEPT} style={{ display: 'none' }} disabled={receiptUploading}
                                onChange={(e) => { if (e.target.files[0]) handleReceiptUpload(e.target.files[0], selected.id, periodKey); e.target.value = ''; }} />
                            </>)}
                          </div>
                        </div>
                      );
                    })}
                  </div>
                  {receiptError && <Feedback value={receiptError} style={{ marginTop: 8 }} />}
                </div>
              );
            })()}

            {/* Price history (recurring only) */}
            {selected.type === 'recurring' && (
              <div className="detail-section">
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 10 }}>
                  <h3 className="detail-section-title" style={{ margin: 0 }}>PRICE HISTORY<HelpIcon slug="expense" /></h3>
                  {isAdmin && (
                    <button className="btn btn-ghost btn-sm" onClick={() => openPriceModal(selected)}>
                      + Update Price
                    </button>
                  )}
                </div>
                {(priceHistory[selected.id] || []).length === 0 ? (
                  <EmptyState variant="note" text="No price history recorded." />
                ) : (
                  (priceHistory[selected.id] || []).slice().reverse().map((entry, i) => {
                    const isCurrent = i === 0;
                    return (
                      <div key={entry.id} style={{
                        display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start',
                        padding: '8px 0', borderBottom: '1px solid var(--border)',
                      }}>
                        <div>
                          <div style={{ fontSize: 12, fontWeight: 500, color: isCurrent ? 'var(--white)' : 'var(--muted)' }}>
                            {fmtDate(entry.effective_date)}
                            {isCurrent && (
                              <span style={{
                                marginLeft: 8, fontSize: 9, fontWeight: 700, letterSpacing: '1px',
                                textTransform: 'uppercase', color: 'var(--orange)',
                              }}>current</span>
                            )}
                          </div>
                          {entry.notes && (
                            <div style={{ fontSize: 10, color: 'var(--muted)', marginTop: 2 }}>{entry.notes}</div>
                          )}
                        </div>
                        <div style={{ fontWeight: 600, fontVariantNumeric: 'tabular-nums', color: isCurrent ? 'var(--white)' : 'var(--muted)' }}>
                          {fmtMoney(entry.amount)}
                        </div>
                      </div>
                    );
                  })
                )}
              </div>
            )}

            {/* Allocations */}
            <div className="detail-section">
              <h3 className="detail-section-title">ALLOCATIONS<HelpIcon slug="expense-via-split" /></h3>
              {selectedAllocations.length === 0 ? (
                <EmptyState variant="note"
                  text={`No allocations yet.${isAdmin ? ' Apply this expense in a payout split to start tracking coverage.' : ''}`} />
              ) : (
                selectedAllocations.map(a => {
                  const campaign = a.payout?.campaign;
                  return (
                    <div key={a.id} style={{
                      display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start',
                      padding: '8px 0', borderBottom: '1px solid var(--border)',
                    }}>
                      <div>
                        <div style={{ fontSize: 12, fontWeight: 500 }}>
                          {campaign?.brand_name || (campaign?.campaign_name || 'Unknown campaign')}
                        </div>
                        {a.expense_period && (
                          <div style={{ fontSize: 10, color: 'var(--muted)' }}>
                            {fmtPeriod(a.expense_period.substring(0, 7))}
                          </div>
                        )}
                        {a.payout?.payout_date && (
                          <div style={{ fontSize: 10, color: 'var(--muted)' }}>{fmtDate(a.payout.payout_date)}</div>
                        )}
                      </div>
                      <div style={{ fontWeight: 700, color: 'var(--green)', fontVariantNumeric: 'tabular-nums' }}>
                        {fmtMoney(a.amount)}
                      </div>
                    </div>
                  );
                })
              )}
            </div>
          </div>
        </div>
      )}

      {/* Add/Edit modal */}
      {modal && (
        <Modal
          title={modal === 'add' ? 'ADD EXPENSE' : 'EDIT EXPENSE'}
          size="md"
          onClose={() => setModal(null)}
        >
            <div className="modal-body">
              {/* One-time / Recurring toggle */}
              <div style={{ display: 'flex', gap: 0, marginBottom: 20, background: 'var(--surface2)', borderRadius: 6, padding: 3, border: '1px solid var(--border2)' }}>
                {[{ v: 'one_time', label: 'ONE-TIME' }, { v: 'recurring', label: 'RECURRING' }].map(({ v, label }) => (
                  <button
                    key={v}
                    onClick={() => setForm(f => ({ ...f, type: v }))}
                    style={{
                      flex: 1, padding: '7px 0', border: 'none', borderRadius: 4, cursor: 'pointer',
                      fontSize: 10, fontFamily: 'var(--font-body)', fontWeight: 700, letterSpacing: '1.2px',
                      textTransform: 'uppercase',
                      background: form.type === v ? 'var(--surface)' : 'transparent',
                      color: form.type === v ? 'var(--white)' : 'var(--muted)',
                      boxShadow: form.type === v ? 'var(--shadow-sm)' : 'none',
                      transition: 'all 0.15s',
                    }}
                  >{label}</button>
                ))}
              </div>

              {/* Full width above the row rather than inside the Category column, matching how
                  PayoutForm reports its own picker-scoped read failures. */}
              {expenseAccountsError && (
                <div style={{ marginBottom: 12 }}><ReadError error={expenseAccountsError} onRetry={refreshStatusOptions} /></div>
              )}
              <div className="form-row">
                <Field label="Name">{(id) => (<>
                  <input id={id} className="form-input" maxLength={120} value={form.name} onChange={e => setForm(f => ({ ...f, name: e.target.value }))} placeholder="e.g. iPhone 15 Pro" />
                </>)}</Field>
                <Field label="Category">{(id) => (<>
                  <select id={id} className="form-select" value={form.category_id} onChange={e => setForm(f => ({ ...f, category_id: e.target.value }))}>
                    {pickerCategories.map(c => <option key={c.id} value={c.id}>{c.name}{c.is_active === false ? ' (inactive)' : ''}</option>)}
                  </select>
                </>)}</Field>
              </div>

              <div className="form-row">
                <div className="form-group">
                  <div className="form-label">Amount ($)</div>
                  {modal !== 'add' && form.type === 'recurring' ? (
                    <>
                      <div style={{ padding: '9px 0', fontSize: 13, fontWeight: 500 }}>{fmtMoney(form.amount)}</div>
                      <div style={{ fontSize: 10, color: 'var(--dim)', marginTop: 4 }}>Use Price History to change the amount.</div>
                    </>
                  ) : (
                    <MoneyInput aria-label="Amount ($)" min="0.01" value={form.amount} onChange={e => setForm(f => ({ ...f, amount: e.target.value }))} placeholder="0.00" />
                  )}
                </div>
                <Field label={form.type === 'recurring' ? 'Start Date' : 'Date'}>{(id) => (<>
                  <input id={id} className="form-input" type="date" min={DB_DATE_MIN} max={DB_DATE_MAX} value={form.start_date} onChange={e => setForm(f => ({ ...f, start_date: e.target.value }))} />
                </>)}</Field>
              </div>

              {form.type === 'recurring' && (
                <>
                  <div className="form-row">
                    <Field label="Frequency">{(id) => (<>
                      <select id={id} className="form-select" value={form.frequency} onChange={e => setForm(f => ({ ...f, frequency: e.target.value }))}>
                        {EXPENSE_FREQUENCIES.map(f => <option key={f} value={f}>{FREQ_LABELS[f]}</option>)}
                      </select>
                    </>)}</Field>
                    <div className="form-group">
                      <div className="form-label">
                        {form.frequency === 'weekly' ? 'Day of week' : 'Day of month'}
                      </div>
                      {form.frequency === 'weekly' ? (
                        <select aria-label="Day of week" className="form-select" value={form.recurrence_day_of_week} onChange={e => setForm(f => ({ ...f, recurrence_day_of_week: e.target.value }))}>
                          {DAYS_OF_WEEK.map((d, i) => <option key={i} value={i}>{d}</option>)}
                        </select>
                      ) : (
                        <select aria-label="Day of month" className="form-select" value={form.recurrence_day_of_month} onChange={e => setForm(f => ({ ...f, recurrence_day_of_month: e.target.value }))}>
                          {Array.from({ length: 28 }, (_, i) => i + 1).map(d => <option key={d} value={d}>{d}{ordSuffix(d)}</option>)}
                          <option value="0">Last day</option>
                        </select>
                      )}
                    </div>
                  </div>
                  <Field label={<>End Date <span style={{ color: 'var(--dim)' }}>optional: leave blank for ongoing</span></>}>{(id) => (<>
                    <input id={id} className="form-input" type="date" min={form.start_date || DB_DATE_MIN} max={DB_DATE_MAX} value={form.end_date} onChange={e => setForm(f => ({ ...f, end_date: e.target.value }))} />
                  </>)}</Field>
                </>
              )}

              {isAdmin && (
                <Field label="Owner">{(id) => (<>
                  <select id={id} className="form-select" value={form.creator_id} onChange={e => setForm(f => ({ ...f, creator_id: e.target.value }))}>
                    <option value="">Business (shared)</option>
                    {creators.map(c => <option key={c.id} value={c.id}>{c.creator_name || c.full_name}</option>)}
                  </select>
                </>)}</Field>
              )}

              <Field label={<>Notes <span style={{ color: 'var(--dim)' }}>optional</span></>}>{(id) => (<>
                <textarea id={id} className="form-textarea" rows={2} maxLength={500} value={form.notes} onChange={e => setForm(f => ({ ...f, notes: e.target.value }))} />
              </>)}</Field>

              {formError && <Feedback value={formError} />}
            </div>
            <div className="modal-footer">
              <button className="btn btn-ghost" onClick={() => setModal(null)}>Cancel</button>
              <SubmitButton saving={saving} className="btn btn-primary" onClick={saveExpense} disabled={saving}>{modal === 'add' ? 'Add Expense' : 'Save Changes'}</SubmitButton>
            </div>
        </Modal>
      )}
      {/* Out-of-pocket modal (Patterns P + Q) */}
      {oopModalFor && (
        <OopPaymentModal
          expense={oopModalFor.expense}
          period={oopModalFor.period}
          periods={oopModalFor.periods}
          onClose={() => setOopModalFor(null)}
          onSaved={() => { setOopModalFor(null); setGridSelection(new Set()); setGridAnchor(null); fetchAll(); }}
        />
      )}
      {/* Reverse OOP entry */}
      {reverseFor && (
        <ReverseEntryModal
          journalEntry={reverseFor}
          onClose={() => setReverseFor(null)}
          onReversed={() => { setReverseFor(null); fetchAll(); }}
        />
      )}
      {/* Update Price modal */}
      {priceModal && (
        <Modal
          title="UPDATE PRICE"
          size="sm"
          onClose={() => setPriceModal(null)}
        >
            <div className="modal-body">
              <div style={{ fontSize: 12, color: 'var(--muted)', marginBottom: 16 }}>
                {priceModal.name}: current: {fmtMoney(priceModal.amount)}
              </div>
              <div className="form-row">
                <Field label="New Amount ($)">{(id) => (<>
                  <MoneyInput id={id}
                    min="0.01"
                    value={priceForm.amount}
                    onChange={e => setPriceForm(f => ({ ...f, amount: e.target.value }))}
                    placeholder="0.00"
                    autoFocus
                  />
                </>)}</Field>
                <Field label="Effective Date">{(id) => (<>
                  <input id={id}
                    className="form-input"
                    type="date" min={DB_DATE_MIN} max={DB_DATE_MAX}
                    value={priceForm.effective_date}
                    onChange={e => setPriceForm(f => ({ ...f, effective_date: e.target.value }))}
                  />
                </>)}</Field>
              </div>
              <Field label={<>Note <span style={{ color: 'var(--dim)' }}>optional</span></>}>{(id) => (<>
                <input id={id}
                  className="form-input"
                  maxLength={200}
                  value={priceForm.notes}
                  onChange={e => setPriceForm(f => ({ ...f, notes: e.target.value }))}
                  placeholder="e.g. Annual price increase"
                />
              </>)}</Field>
              {priceFormError && <Feedback value={priceFormError} />}
            </div>
            <div className="modal-footer">
              <button className="btn btn-ghost" onClick={() => setPriceModal(null)}>Cancel</button>
              <SubmitButton saving={priceSaving} className="btn btn-primary" onClick={savePriceChange} disabled={priceSaving}>Save Price Change</SubmitButton>
            </div>
        </Modal>
      )}
    </div>
  );
}

function ordSuffix(n) {
  const s = ['th', 'st', 'nd', 'rd'];
  const v = n % 100;
  return s[(v - 20) % 10] || s[v] || s[0];
}

