/**
 * components/shared/Tabs.js - the hub's one tab bar.
 *
 * Four tab bars were a `<div className="tab" onClick>` each: not focusable, no `role="tab"`,
 * no `aria-selected`. One of them is the only route a creator has to a campaign's Brief and
 * Payment tabs. The agency dashboard already had a correct tablist and the hub did not, so
 * this is that behaviour moved somewhere both can be held to.
 *
 * @gotcha roving tabindex. Only the SELECTED tab is in the tab order, which is what lets a
 *         keyboard user arrow between tabs instead of tabbing through every one.
 * @see shared/agency.js activatePanels
 */
import React, { useRef } from 'react';

/** The DOM id of one tab, derived so the panel can name the tab that opened it. */
const tabId = (panelId, id) => `${panelId}-tab-${id}`;

/**
 * Props for the element a Tabs bar controls.
 *
 * @param {string} panelId - the same `panelId` given to Tabs
 * @param {string} value - the selected tab's id
 */
export function tabPanelProps(panelId, value) {
  return { id: panelId, role: 'tabpanel', 'aria-labelledby': tabId(panelId, value) };
}

/**
 * @param {object} props
 * @param {Array<{id: string, label: React.ReactNode}>} props.items - in display order
 * @param {string} props.value - the selected tab's id
 * @param {function} props.onChange - called with the newly selected id
 * @param {string} props.label - what the bar switches between, for a screen reader
 * @param {string} props.panelId - the id of the element the tabs control
 * @param {object} [props.style]
 */
export default function Tabs({ items, value, onChange, label, panelId, style }) {
  const refs = useRef({});

  /** Move selection AND focus together, which is what a tablist does by default. */
  function select(id) {
    onChange(id);
    const el = refs.current[id];
    if (el) el.focus();
  }

  function onKeyDown(ev) {
    const at = items.findIndex((it) => it.id === value);
    if (at === -1) return;
    let next = null;
    if (ev.key === 'ArrowRight') next = items[(at + 1) % items.length];
    else if (ev.key === 'ArrowLeft') next = items[(at - 1 + items.length) % items.length];
    else if (ev.key === 'Home') next = items[0];
    else if (ev.key === 'End') next = items[items.length - 1];
    if (!next) return;
    ev.preventDefault();
    select(next.id);
  }

  return (
    <div className="tabs" role="tablist" aria-label={label} style={style} onKeyDown={onKeyDown}>
      {items.map((it) => {
        const on = it.id === value;
        return (
          <button
            key={it.id}
            type="button"
            role="tab"
            id={tabId(panelId, it.id)}
            ref={(el) => { refs.current[it.id] = el; }}
            className={`tab${on ? ' active' : ''}`}
            aria-selected={on}
            aria-controls={panelId}
            tabIndex={on ? 0 : -1}
            onClick={() => onChange(it.id)}
          >
            {it.label}
          </button>
        );
      })}
    </div>
  );
}
