/**
 * components/shared/StatusBadges.js: payout + split status pills.
 *
 * Sibling of Badge.js for the 'payout' and 'split' groups. Colour and label come from the live
 * `status_options` rows through `utils/statusRow.js`, which owns the resolution order for every
 * pill in the hub; the *_FALLBACK maps only apply BEFORE the context loads.
 *
 * @gotcha a status that does not resolve draws NOTHING, the same answer Badge gives.
 * @gotcha the one exception is a payout with NO status at all, which reads
 *         `PAYOUT_DEFAULT_VALUE`. That default is DELIBERATE and lives in one place, because
 *         the filter beside this pill applies the same one: an absent status is a payout
 *         nobody has moved yet, not an unresolvable one.
 *         @see utils/statusValues.js
 * @gotcha never hardcode status arrays elsewhere; derive from useStatusOptions.
 *         @see .claude/rules/hub-data.md
 */
import React from 'react';
import { useStatusOptions } from '../../contexts/StatusOptionsContext';
import { resolveStatusRow } from '../../utils/statusRow';
import { PAYOUT_DEFAULT_VALUE } from '../../utils/statusValues';

const PAYOUT_FALLBACK = {
  'Pending': 'badge-not-invoiced',
  'Partial': 'badge-pending',
  'Paid':    'badge-paid',
  'On Hold': 'badge-overdue',
  'N/A':     'badge-not-invoiced',
};

const SPLIT_FALLBACK = {
  'Pending': 'badge-not-invoiced',
  'Sent':    'badge-invoiced',
  'Cleared': 'badge-paid',
  'Failed':  'badge-overdue',
};

/** The row's own colours, or null when nothing resolves. */
function pill(found) {
  if (!found) return null;
  return (
    <span className="badge" style={{ background: found.bg_color, color: found.text_color }}>
      {found.label}
    </span>
  );
}

export function PayoutBadge({ status, statusId }) {
  const ctx = useStatusOptions();

  if (!ctx || ctx.loading) {
    return <span className={`badge ${PAYOUT_FALLBACK[status] || 'badge-not-invoiced'}`}>{status || PAYOUT_DEFAULT_VALUE}</span>;
  }
  // No id and no value is not an unresolvable status, it is the absence of one, and the
  // filter beside this pill reads the absence the same way. One home for that default.
  if (!statusId && !status) return <span className="badge badge-not-invoiced">{PAYOUT_DEFAULT_VALUE}</span>;

  return pill(resolveStatusRow(ctx.options, 'payout', { statusId, status }));
}

export function SplitStatusBadge({ status, statusId }) {
  const ctx = useStatusOptions();

  if (!ctx || ctx.loading) {
    if (!status) return null;
    return <span className={`badge ${SPLIT_FALLBACK[status] || 'badge-not-invoiced'}`}>{status}</span>;
  }
  return pill(resolveStatusRow(ctx.options, 'split', { statusId, status }));
}
