/**
 * components/shared/Comments.js: per-campaign comment thread.
 *
 * Reads + writes the `comments` table for one campaign (RLS scopes visibility).
 * Only admins may delete a comment. Body capped at 2000 chars.
 */
import React, { useState, useEffect } from 'react';
import { supabase } from '../../lib/supabase';
import { useAuth } from '../../hooks/useAuth';
import { fmtDate } from '../../utils/format';
import Feedback from './Feedback';
import EmptyState from './EmptyState';
import ReadError from './ReadError';
import { useConfirm } from './ConfirmDialog';
import { mutate } from '../../utils/mutate';
import { useToast } from './Toast';

export default function Comments({ campaignId }) {
  const toast = useToast();
  const askConfirm = useConfirm();
  const { profile } = useAuth();
  const [comments, setComments] = useState([]);
  const [newComment, setNewComment] = useState('');
  const [loading, setLoading] = useState(false);
  const [commentError, setCommentError] = useState('');
  // The RAW read error, kept apart from `commentError`, which is a validation message about
  // the box below. One flag for both put "No comments yet." above the reason the thread could
  // not be read. @see .claude/rules/hub-ui.md (the four data states)
  const [readErr, setReadErr] = useState(null);

  useEffect(() => {
    if (campaignId) fetchComments();
  }, [campaignId]);

  async function fetchComments() {
    const { data, error } = await supabase
      .from('comments')
      .select('*, author:profiles(full_name, creator_name, role)')
      .eq('campaign_id', campaignId)
      .order('created_at', { ascending: true });
    // An empty thread reads as "nobody has said anything", which is a claim.
    if (error) { setReadErr(error); setComments([]); return; }
    setReadErr(null);
    setComments(data || []);
  }

  async function submitComment(e) {
    e.preventDefault();
    const body = newComment.trim();
    if (!body) return;
    setCommentError('');
    if (body.length > 2000) { setCommentError('Comment must be 2000 characters or fewer.'); return; }
    setLoading(true);
    await supabase.from('comments').insert({
      campaign_id: campaignId,
      author_id: profile.id,
      body,
    });
    setNewComment('');
    await fetchComments();
    setLoading(false);
  }

  function getInitials(p) {
    if (!p) return '?';
    const name = p.full_name || '';
    return name.split(' ').map(n => n[0]).join('').toUpperCase().slice(0, 2);
  }

  /**
   * Delete one comment, after quoting it back.
   *
   * @param {object} c the comment row, NOT its id. A thread can hold a dozen of these and
   *        they all render the same ✕: "Delete this comment?" is answerable only by
   *        remembering which button was pressed.
   */
  async function deleteComment(c) {
    const quoted = (c.body || '').trim().replace(/\s+/g, ' ');
    const snippet = quoted.length > 60 ? `${quoted.slice(0, 60)}…` : quoted;
    if (!(await askConfirm({
      title: 'Delete this comment?',
      body: snippet ? `"${snippet}" is removed from the thread. This cannot be undone.` : 'The comment is removed from the thread. This cannot be undone.',
      danger: true,
    }))) return;
    const { error } = await mutate(supabase.from('comments').delete().eq('id', c.id));
    if (error) { toast.error(error); return; }
    await fetchComments();
  }

  const isAdmin = profile?.role === 'admin';

  return (
    <div>
      {readErr && <ReadError error={readErr} onRetry={fetchComments} />}
      {!readErr && comments.length === 0 && (
        <EmptyState variant="note" style={{ paddingBottom: 12 }} text="No comments yet." />
      )}
      {comments.map(c => (
        <div className="comment" key={c.id} style={{ position: 'relative' }}>
          <div className="comment-avatar">{getInitials(c.author)}</div>
          <div className="comment-body" style={{ flex: 1 }}>
            <div className="comment-meta">
              <strong>{c.author?.full_name || 'Unknown'}</strong>
              {' · '}
              {fmtDate(c.created_at, 'MMM d, h:mm a')}
            </div>
            <div className="comment-text">{c.body}</div>
          </div>
          {isAdmin && (
            <button
              className="btn btn-ghost btn-sm"
              style={{ fontSize: 11, color: 'var(--red)', flexShrink: 0, alignSelf: 'flex-start', padding: '2px 6px' }}
              onClick={() => deleteComment(c)}
              title="Delete comment"
              aria-label="Delete comment"
            >✕</button>
          )}
        </div>
      ))}
      {commentError && <Feedback value={commentError} style={{ marginBottom: 8 }} />}
      <form onSubmit={submitComment} className="comment-input-row">
        <input
          className="form-input"
          aria-label="Add a comment"
          value={newComment}
          onChange={e => setNewComment(e.target.value)}
          placeholder="Add a comment…"
          maxLength={2000}
          disabled={loading}
        />
        <button className="btn btn-primary btn-sm" type="submit" disabled={loading || !newComment.trim()}>
          Post
        </button>
      </form>
    </div>
  );
}
