/**
 * utils/receipt.js - upload and remove payment + expense receipts, keeping the
 * Storage object and its versioned DB row in step in both directions.
 *
 * @invariant a payment receipt's files and its `invoice_documents` rows are
 *            created together and destroyed together. Every write path here
 *            either completes both halves or undoes the half it managed, so a
 *            row can never name a missing file and a file can never sit in the
 *            bucket with nothing pointing at it.
 */
import { supabase } from '../lib/supabase';
import { validateUploadFile } from './storage';
import { mutate } from './mutate';
import { humanizeError } from './errors';

const RECEIPT_BUCKET = 'payment-receipts';

/**
 * Upload an agency-payment receipt as a versioned invoice_documents row
 * (doc_type='payment_receipt'); the DB trigger demotes any prior is_current row.
 *
 * @param {{file, invoiceId, setUploading, onSuccess, onError}} args -
 *        onSuccess(path, fileName) is kept for backward compat; callers don't
 *        need to know about versioning.
 * @deprecated supersedes the legacy invoices.receipt_path / receipt_name pair.
 */
export async function uploadPaymentReceipt({ file, invoiceId, setUploading, onSuccess, onError }) {
  if (!file || !invoiceId) return;
  const err = await validateUploadFile(file);
  if (err) { if (onError) onError(err); return; }
  setUploading(true);

  // Determine next version number for this (invoice_id, payment_receipt).
  //
  // @gotcha This read's { error } is CHECKED, and it has to be. A refused or failed read
  //         leaves `prev` null, which reads as "no receipt yet" and takes version back to
  //         1. The upload below writes receipts/{invoiceId}/v1.{ext} with upsert: true, so
  //         it would OVERWRITE the v1 file that already exists and then insert a second
  //         row claiming version 1. That destroys a financial record backing a deduction,
  //         silently, on a path whose whole reason for existing is that a receipt has
  //         versions. Refusing the upload is strictly better than losing the old one.
  const { data: prev, error: prevErr } = await supabase
    .from('invoice_documents')
    .select('version')
    .eq('invoice_id', invoiceId)
    .eq('doc_type', 'payment_receipt')
    .order('version', { ascending: false })
    .limit(1)
    .maybeSingle();
  if (prevErr) {
    // A string, like every other onError here: the callers render this value directly.
    if (onError) onError('Could not check the existing receipt versions. Nothing was uploaded.');
    setUploading(false);
    return;
  }
  const version = (prev?.version || 0) + 1;

  const ext  = file.name.split('.').pop();
  const path = `receipts/${invoiceId}/v${version}.${ext}`;

  // @security THE ROW GOES FIRST. Writing the object before the row that says who owns it
  //           makes the RLS on invoice_documents a check on the metadata only, running after
  //           the bytes have landed, so a refused row leaves an object in a private bucket
  //           with nothing pointing at it. Insert first and a refusal costs nothing.
  // @gotcha is_current is FALSE here and flipped after the upload. Inserting it true fires the
  //         demote trigger immediately, so a failed upload followed by deleting this row would
  //         leave the PREVIOUS receipt demoted and no current row at all, which is worse than
  //         the defect this ordering fixes.
  const { data: { user } = {} } = await supabase.auth.getUser();
  const { data: docRow, error: insErr } = await supabase.from('invoice_documents').insert({
    invoice_id: invoiceId,
    doc_type: 'payment_receipt',
    version,
    file_path: path,
    file_name: file.name,
    file_size: file.size || null,
    mime_type: file.type || null,
    is_current: false,
    generated_by: user?.id || null,
  }).select().single();
  if (insErr) {
    if (process.env.NODE_ENV !== 'production') console.error(insErr);
    if (onError) onError('Failed to save receipt record. Please try again.');
    setUploading(false);
    return;
  }

  const { error: upErr } = await supabase.storage.from(RECEIPT_BUCKET).upload(path, file, { upsert: true });
  if (upErr) {
    if (process.env.NODE_ENV !== 'production') console.error(upErr);
    // A failed cleanup leaves a non-current row pointing at an object that does not exist.
    // Harmless to every reader (nothing reads a non-current row) but worth seeing in dev.
    const { error: rbErr } = await supabase.from('invoice_documents').delete().eq('id', docRow.id);
    if (rbErr && process.env.NODE_ENV !== 'production') console.error(rbErr);
    if (onError) onError('Upload failed. Please try again.');
    setUploading(false);
    return;
  }

  // Only now does this become the receipt everything reads. The DB trigger demotes any prior.
  const { error: curErr } = await supabase.from('invoice_documents')
    .update({ is_current: true }).eq('id', docRow.id);
  if (curErr) {
    if (process.env.NODE_ENV !== 'production') console.error(curErr);
    if (onError) onError('Receipt uploaded but could not be marked current. Refresh and try again.');
    setUploading(false);
    return;
  }

  onSuccess(path, file.name);
  setUploading(false);
}

/**
 * Remove an invoice's payment receipt: every stored version's file AND every
 * matching `invoice_documents` row.
 *
 * @param {string} invoiceId
 * @returns {Promise<{error: ?{tone: string, title: string, body: ?string}}>}
 *          `error` is null on success and is already a `humanizeError` feedback
 *          object otherwise, so `if (error)` is the whole check. The caller
 *          must not clear its own receipt state until it is null.
 *
 * @gotcha every upload writes a NEW versioned path (`receipts/{id}/v{n}.{ext}`)
 *         and the DB trigger demotes the previous row rather than replacing it,
 *         so an invoice whose receipt was re-uploaded has n files and n rows.
 *         Removing the ONE path a caller has on screen and then deleting every
 *         row for the invoice destroys the record of v1..v(n-1) and leaves their
 *         files in the bucket unreferenced. Read the paths from the ROWS, never
 *         from what the component happens to hold.
 * @gotcha the files go first and the rows second, on purpose. Deleting the rows
 *         first and failing on the files reproduces the original defect, while
 *         this order leaves at worst a row whose file is gone, and a retry then
 *         converges because removing an absent key is not an error.
 */
export async function deletePaymentReceipt(invoiceId) {
  if (!invoiceId) return { error: null };

  const { data: rows, error: readErr } = await supabase
    .from('invoice_documents')
    .select('file_path')
    .eq('invoice_id', invoiceId)
    .eq('doc_type', 'payment_receipt');
  if (readErr) {
    if (process.env.NODE_ENV !== 'production') console.error(readErr);
    return { error: humanizeError(readErr) };
  }

  const paths = (rows || []).map(r => r.file_path).filter(Boolean);
  if (paths.length) {
    const { error: rmErr } = await mutate(supabase.storage.from(RECEIPT_BUCKET).remove(paths));
    if (rmErr) return { error: rmErr };
  }

  const { error: delErr } = await mutate(
    supabase.from('invoice_documents').delete().eq('invoice_id', invoiceId).eq('doc_type', 'payment_receipt'),
  );
  return { error: delErr };
}

/**
 * Upload a receipt for an expense (one-time or a specific recurring period).
 *
 * @param {{file, expenseId, periodKey, uploadedBy, setUploading, onSuccess, onError}} args -
 *        periodKey is 'YYYY-MM' for a recurring period, null for a one-time
 *        expense; onSuccess receives the full inserted expense_receipts row.
 */
export async function uploadExpenseReceipt({ file, expenseId, periodKey, uploadedBy, setUploading, onSuccess, onError }) {
  if (!file || !expenseId) return;
  const err = await validateUploadFile(file);
  if (err) { if (onError) onError(err); return; }
  setUploading(true);
  const ext    = file.name.split('.').pop();
  const folder = periodKey ?? 'one-time';
  const path   = `${expenseId}/${folder}/${Date.now()}.${ext}`;

  // @security the row before the bytes, same reason as uploadPaymentReceipt above. There is no
  //           is_current trigger on expense_receipts, so this one is a plain inversion: a
  //           refused insert means no object was ever written, and a failed upload deletes the
  //           row it just made.
  const { data: row, error: insertError } = await supabase
    .from('expense_receipts')
    .insert({ expense_id: expenseId, period_key: periodKey ?? null, file_path: path, file_name: file.name, uploaded_by: uploadedBy })
    .select()
    .single();
  if (insertError) {
    if (process.env.NODE_ENV !== 'production') console.error(insertError);
    if (onError) onError('Failed to save receipt record. Please try again.');
    setUploading(false);
    return;
  }

  const { error: uploadError } = await supabase.storage
    .from('expense-receipts')
    .upload(path, file);
  if (uploadError) {
    if (process.env.NODE_ENV !== 'production') console.error(uploadError);
    const { error: rbErr } = await supabase.from('expense_receipts').delete().eq('id', row.id);
    if (rbErr && process.env.NODE_ENV !== 'production') console.error(rbErr);
    if (onError) onError('Upload failed. Please try again.');
    setUploading(false);
    return;
  }

  onSuccess(row);
  setUploading(false);
}
