/**
 * components/shared/CreatorFilterChips.js: "All" + per-creator filter chip row.
 *
 * value is 'all' or a creator id; onChange receives the picked value.
 */
import React from 'react';

export default function CreatorFilterChips({ value, onChange, creators }) {
  return (
    <>
      <button className={`filter-chip ${value === 'all' ? 'active' : ''}`} aria-pressed={value === 'all'} onClick={() => onChange('all')}>All</button>
      {creators.map(c => (
        <button key={c.id} className={`filter-chip ${value === c.id ? 'active' : ''}`} aria-pressed={value === c.id} onClick={() => onChange(c.id)}>
          {c.creator_name || c.full_name}
        </button>
      ))}
    </>
  );
}
