/**
 * components/shared/ErrorBoundary.js: per-section render-error boundary.
 *
 * Wraps each dashboard view (AdminDashboard remounts via key={activeView} so
 * navigating resets a crashed view). @see CLAUDE.md (ErrorBoundary)
 */
import React from 'react';
import EmptyState from './EmptyState';

/**
 * Catches render errors below it and presents an empty-state recovery panel
 * (Try again resets; Refresh reloads).
 *
 * @param {string} [props.sectionName] - names which section died in the message.
 */
export default class ErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = { caught: false };
    this.reset = this.reset.bind(this);
    this.reload = this.reload.bind(this);
  }

  static getDerivedStateFromError() { return { caught: true }; }

  componentDidCatch(error, info) {
    if (process.env.NODE_ENV !== 'production') {
      console.error('[ErrorBoundary]', error, info.componentStack);
    }
  }

  reset()  { this.setState({ caught: false }); }
  reload() { window.location.reload(); }

  render() {
    if (!this.state.caught) return this.props.children;
    const section = this.props.sectionName;
    return (
      /* The shared panel, not the shared CLAIM: a crash is not emptiness, which is why this
         one carries role="alert" and no other call site does. @see EmptyState.js */
      <EmptyState
        role="alert"
        icon="!"
        title="this section crashed"
        text={<span style={{ display: 'block', maxWidth: 360, margin: '0 auto' }}>
          {section ? `The ${section} view hit an error.` : 'A section hit an error.'} Your work is safe.
          Try again, or refresh if it keeps happening.
        </span>}
        action={<>
          <button className="btn btn-secondary btn-sm" onClick={this.reset}>Try again</button>
          <button className="btn btn-ghost btn-sm" onClick={this.reload}>Refresh page</button>
        </>} />
    );
  }
}
